                grid-template-areas:
                    "info"
                    "actions"
                    "metrics";
                row-gap: 12px;
            }
            .dharma-acc-metrics {
                grid-template-columns: repeat(2, minmax(0, 1fr));
                margin-top: 0;
            }
        }

        /* Pagination */
        .trading-list-pagination {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-top: 18px;
