        /* PrimeXBT Top Contracts Section Styles */
        .top-contracts-card {
            background: linear-gradient(135deg, rgba(20, 21, 30, 0.75), rgba(12, 13, 18, 0.95));
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 20px;
            box-shadow: 0 16px 36px rgba(0, 0, 0, 0.25);
        }

        .top-contracts-table {
            width: 100%;
            border-collapse: collapse;
        }

        .top-contracts-table tr {
            border-bottom: 1px solid rgba(255, 255, 255, 0.05);
