        /* ==========================================
           BUY & EXCHANGE FULL PAGE VIEW (PRIMEXBT STYLE)
           ========================================== */
        .swap-header-btn {
            background: #21232c;
            color: #ffffff;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 10px;
            padding: 8px 16px;
            font-size: 0.88rem;
            font-weight: 600;
            cursor: pointer;
            display: inline-flex;
            align-items: center;
            gap: 6px;
            transition: all 0.15s ease;
        }

        .swap-header-btn:hover {
            background: #2c303c;
            border-color: rgba(255, 255, 255, 0.16);
            color: #ffffff;
        }

        .swap-main-card {
            background: #141620;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 20px;
            padding: 22px;
            width: 100%;
            max-width: 520px;
            margin: 0 auto;
            box-sizing: border-box;
            box-shadow: 0 16px 36px rgba(0, 0, 0, 0.5);
            position: relative;
        }

        .swap-box {
            background: #1c1f2b;
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 14px;
            padding: 14px 18px;
            box-sizing: border-box;
            transition: border-color 0.15s ease;
        }

        .swap-box:focus-within {
            border-color: rgba(99, 102, 241, 0.4);
        }

        .swap-box.is-invalid,
        .swap-box.is-invalid:focus-within {
            border-color: #ef4444 !important;
            box-shadow: 0 0 0 1px rgba(239, 68, 68, 0.25) !important;
        }

        .swap-box-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 8px;
        }

        .swap-box-label {
            color: rgba(255, 255, 255, 0.5);
            font-size: 0.86rem;
            font-weight: 600;
        }

        .swap-box-balance-wrap {
            display: flex;
