            color: rgba(255, 255, 255, 0.5);
        }

        .swap-box-balance-wrap strong {
            color: #cbd5e1;
            font-family: ui-monospace, SFMono-Regular, monospace;
        }

        .swap-balance-wallet-btn {
            background: rgba(37, 99, 235, 0.2);
            color: #60a5fa;
            border: none;
            border-radius: 6px;
            padding: 3px 6px;
            display: inline-flex;
