            cursor: pointer;
            transition: all 0.15s ease;
        }

        .swap-balance-wallet-btn:hover {
            background: rgba(37, 99, 235, 0.35);
            color: #ffffff;
        }

        .swap-box-body {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
        }

        .swap-asset-select-btn {
            background: rgba(255, 255, 255, 0.06);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 10px;
            padding: 6px 12px 6px 8px;
            display: inline-flex;
            align-items: center;
            gap: 8px;
            cursor: pointer;
            color: #ffffff;
            transition: all 0.15s ease;
            flex-shrink: 0;
        }

        .swap-asset-select-btn:hover {
            background: rgba(255, 255, 255, 0.12);
            border-color: rgba(255, 255, 255, 0.16);
        }

        .swap-asset-icon-wrap {
            width: 26px;
            height: 26px;
            border-radius: 50%;
            overflow: hidden;
            background: #0f1118;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .swap-asset-icon-wrap img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .swap-asset-symbol {
            font-weight: 700;
