            color: #ffffff;
            letter-spacing: -0.01em;
        }

        .swap-chevron {
            color: rgba(255, 255, 255, 0.4);
            transition: transform 0.15s ease;
        }

        .swap-amount-input {
            background: transparent;
            border: none;
            outline: none;
            font-size: 1.5rem;
            font-weight: 700;
            color: #ffffff;
            text-align: right;
            width: 100%;
            font-family: ui-monospace, SFMono-Regular, monospace;
            padding: 0;
        }

        .swap-amount-input::placeholder {
            color: rgba(255, 255, 255, 0.2);
        }

        .swap-divider-wrap {
            display: flex;
            justify-content: center;
            margin: -14px 0;
            position: relative;
            z-index: 5;
        }

        .swap-circle-switch-btn {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: #262a37;
            border: 3px solid #141620;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #ffffff;
            cursor: pointer;
            transition: all 0.2s ease;
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.35);
        }

        .swap-circle-switch-btn:hover {
            background: #363c4e;
            transform: rotate(180deg);
        }

        .swap-notice-banner {
            background: rgba(37, 99, 235, 0.12);
            border: 1px solid rgba(37, 99, 235, 0.25);
            border-radius: 12px;
            padding: 12px 14px;
            display: flex;
            align-items: center;
            gap: 10px;
            font-size: 0.82rem;
            color: #cbd5e1;
            margin-top: 14px;
            line-height: 1.4;
        }

        .swap-notice-banner a,
        .swap-notice-banner button {
            color: #60a5fa;
            font-weight: 700;
            text-decoration: underline;
            cursor: pointer;
            background: none;
            border: none;
            padding: 0;
        }

        .swap-submit-btn {
            width: 100%;
            padding: 13px;
            border-radius: 12px;
            font-size: 0.96rem;
            font-weight: 700;
            border: none;
            cursor: pointer;
            transition: all 0.2s ease;
            margin-top: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .swap-submit-btn.is-disabled {
            background: rgba(37, 99, 235, 0.22) !important;
            color: rgba(255, 255, 255, 0.35) !important;
            cursor: not-allowed !important;
            box-shadow: none !important;
        }

        .swap-submit-btn:not(.is-disabled) {
            background: #2563eb !important;
            color: #ffffff !important;
            cursor: pointer !important;
            box-shadow: 0 4px 16px rgba(37, 99, 235, 0.4);
        }

        .swap-submit-btn:not(.is-disabled):hover {
            background: #1d4ed8 !important;
            box-shadow: 0 6px 20px rgba(37, 99, 235, 0.5);
            transform: translateY(-1px);
        }

        /* Asset Picker Modal */
        .swap-asset-modal-backdrop {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, 0.75);
            backdrop-filter: blur(8px);
            z-index: 9999;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 16px;
        }

        .swap-asset-modal-card {
            background: #141622;
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 18px;
            width: 100%;
            max-width: 440px;
            max-height: 85vh;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            box-shadow: 0 24px 48px rgba(0, 0, 0, 0.8);
        }

        .swap-modal-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 18px 20px 14px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.06);
        }

        .swap-modal-header h3 {
            font-size: 1.15rem;
            font-weight: 700;
            color: #ffffff;
            margin: 0;
        }

        .swap-modal-close-btn {
            background: none;
            border: none;
            color: rgba(255, 255, 255, 0.6);
            font-size: 1.4rem;
            cursor: pointer;
            padding: 0;
            line-height: 1;
            transition: color 0.15s;
        }

        .swap-modal-close-btn:hover {
            color: #ffffff;
        }

        .swap-modal-search-box {
            display: flex;
            align-items: center;
            gap: 10px;
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 10px;
            margin: 14px 20px 10px;
            padding: 9px 12px;
        }

        .swap-modal-search-box svg {
            color: rgba(255, 255, 255, 0.4);
            flex-shrink: 0;
        }

        .swap-modal-search-box input {
            background: transparent;
            border: none;
            outline: none;
            color: #ffffff;
            font-size: 0.9rem;
            width: 100%;
        }

        .swap-modal-deposit-tip {
            display: flex;
            align-items: center;
            gap: 8px;
            background: rgba(37, 99, 235, 0.12);
            border: 1px solid rgba(37, 99, 235, 0.2);
            border-radius: 10px;
            margin: 0 20px 10px;
            padding: 8px 12px;
            font-size: 0.82rem;
            color: #cbd5e1;
        }

        .swap-modal-deposit-link {
            color: #60a5fa;
            text-decoration: underline;
            background: none;
            border: none;
            font-weight: 700;
            cursor: pointer;
            padding: 0;
        }

        .swap-modal-asset-list {
            flex: 1;
            overflow-y: auto;
            padding: 4px 12px 16px;
        }

        .swap-modal-asset-item {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 10px 12px;
            border-radius: 10px;
            cursor: pointer;
            transition: background 0.15s ease;
        }

        .swap-modal-asset-item:hover {
            background: rgba(255, 255, 255, 0.06);
        }

        .swap-modal-asset-left {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .swap-modal-asset-icon {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            overflow: hidden;
            background: #0f1118;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .swap-modal-asset-icon img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .swap-modal-asset-sym {
            display: block;
            font-weight: 700;
            font-size: 0.92rem;
            color: #ffffff;
            line-height: 1.2;
        }

        .swap-modal-asset-name {
            display: block;
            font-size: 0.74rem;
            color: rgba(255, 255, 255, 0.45);
        }

        .swap-modal-asset-balance {
            font-family: ui-monospace, SFMono-Regular, monospace;
            font-weight: 700;
            font-size: 0.92rem;
            color: #ffffff;
            text-align: right;
        }

        /* =========================================================
           KRYVEX MODERN STEP-BY-STEP DEPOSIT PAGE (MATCHING PRIMEXBT)
           ========================================================= */
        .kvx-deposit-layout {
            display: grid;
            grid-template-columns: minmax(0, 1.45fr) minmax(320px, 1fr);
            gap: 24px;
            align-items: start;
        }

        @media (max-width: 960px) {
            .kvx-deposit-layout {
                grid-template-columns: 1fr;
            }
        }

        /* Center the top subnav tabs */
        .dharma-inner-nav {
            display: flex !important;
            align-items: center !important;
            justify-content: center !important;
            gap: 36px !important;
            border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;
            margin-bottom: 24px !important;
            padding-bottom: 2px !important;
        }

        .dharma-inner-nav-btn {
            font-size: 0.95rem !important;
            font-weight: 600 !important;
            color: rgba(255, 255, 255, 0.5) !important;
            padding: 10px 4px 14px !important;
            position: relative;
            background: none;
            border: none;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .dharma-inner-nav-btn:hover {
            color: rgba(255, 255, 255, 0.85) !important;
        }

        .dharma-inner-nav-btn.is-active {
            color: #ffffff !important;
            font-weight: 700 !important;
        }

        .dharma-inner-nav-btn.is-active::after {
            content: '';
            position: absolute;
            bottom: -1px;
            left: 0;
            right: 0;
            height: 2px;
            background: #ffffff;
            border-radius: 2px;
        }

        /* Left Main Card */
        .kvx-deposit-card {
            background: #14161b;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 20px;
            padding: 28px 32px 24px;
            box-shadow: 0 12px 36px rgba(0, 0, 0, 0.4);
        }

        .kvx-deposit-card-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 30px;
        }

        .kvx-deposit-title {
            font-size: 1.45rem;
            font-weight: 700;
            color: #ffffff;
            letter-spacing: -0.01em;
            margin: 0;
        }

        /* Segmented Pill [ Crypto | Money ] */
        .kvx-deposit-toggle-pill {
            display: inline-flex;
            align-items: center;
            background: #1f2229;
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 10px;
            padding: 3px;
        }

        .kvx-toggle-btn {
            background: transparent;
            border: none;
            color: rgba(255, 255, 255, 0.55);
            font-size: 0.82rem;
            font-weight: 600;
            padding: 5px 14px;
            border-radius: 7px;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .kvx-toggle-btn:hover {
            color: #ffffff;
        }

        .kvx-toggle-btn.is-active {
            background: #ffffff;
            color: #0b0d11;
            font-weight: 700;
            box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
        }

        /* Vertical Step Timeline */
        .kvx-steps-container {
            position: relative;
        }

        .kvx-step-item {
            display: flex;
            position: relative;
            padding-bottom: 28px;
        }

        .kvx-step-item:last-child {
            padding-bottom: 0;
        }

        .kvx-step-indicator {
            display: flex;
            flex-direction: column;
            align-items: center;
            width: 28px;
            flex-shrink: 0;
            margin-right: 16px;
            position: relative;
        }

        .kvx-step-circle {
            width: 28px;
            height: 28px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.82rem;
            font-weight: 700;
            background: #ffffff;
            color: #0f172a;
            z-index: 2;
            flex-shrink: 0;
            transition: all 0.25s ease;
        }

        .kvx-step-circle.is-inactive {
            background: #1e2229;
            color: rgba(255, 255, 255, 0.45);
            border: 1px solid rgba(255, 255, 255, 0.1);
        }

        .kvx-step-circle.is-active {
            background: #ffffff;
            color: #0f172a;
            box-shadow: 0 0 12px rgba(255, 255, 255, 0.3);
            border: none;
        }

        .kvx-step-circle.is-completed {
            background: #ffffff;
            color: #0f172a;
        }

        .kvx-step-circle.is-verified-success {
            background: #10b981;
            color: #ffffff;
        }

        .kvx-step-line {
            position: absolute;
            top: 28px;
            bottom: -8px;
            width: 2px;
            background: rgba(255, 255, 255, 0.12);
            left: 50%;
            transform: translateX(-50%);
            z-index: 1;
            transition: background 0.25s ease;
        }

        .kvx-step-line.is-active {
            background: rgba(255, 255, 255, 0.35);
        }

        .kvx-step-body {
            flex: 1;
            min-width: 0;
        }

        .kvx-step-title {
            font-size: 0.95rem;
            font-weight: 600;
            color: #ffffff;
            line-height: 28px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .kvx-step-title .kvx-info-icon {
            color: rgba(255, 255, 255, 0.45);
            font-size: 0.85rem;
            cursor: pointer;
            transition: color 0.15s;
        }

        .kvx-step-title .kvx-info-icon:hover {
            color: #ffffff;
        }

        /* Step Dropdown / Selector Boxes (Currency, Account, Network) */
        .kvx-currency-selector-wrap,
        .kvx-dropdown-wrap {
            position: relative;
            margin-top: 10px;
        }

        .kvx-currency-floating-label,
        .kvx-dropdown-floating-label {
            position: absolute;
            top: -9px;
            left: 14px;
            background: #111317;
            border: 1px solid rgba(255, 255, 255, 0.12);
            padding: 1px 8px;
            border-radius: 4px;
            font-size: 0.72rem;
            font-weight: 600;
            color: #94a3b8;
            z-index: 5;
            letter-spacing: 0.02em;
        }

        .kvx-currency-select-btn,
        .kvx-dropdown-btn {
            width: 100%;
            background: #191c22;
            border: 1px solid rgba(255, 255, 255, 0.12);
            border-radius: 12px;
            padding: 12px 16px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            color: #ffffff;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .kvx-currency-select-btn:hover,
        .kvx-dropdown-btn:hover {
            border-color: rgba(255, 255, 255, 0.25);
            background: #1e2229;
        }

        .kvx-currency-select-current,
        .kvx-dropdown-current {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .kvx-currency-icon {
            width: 26px;
            height: 26px;
            border-radius: 50%;
            object-fit: cover;
        }

        .kvx-currency-symbol {
            font-weight: 700;
            font-size: 0.95rem;
            color: #ffffff;
        }

        .kvx-currency-name {
            font-size: 0.84rem;
            color: rgba(255, 255, 255, 0.5);
        }

        /* Dropdown Modal / Flyout */
        .kvx-currency-dropdown,
        .kvx-dropdown-panel {
            position: absolute;
            top: calc(100% + 6px);
            left: 0;
            right: 0;
            background: #181b22;
            border: 1px solid rgba(255, 255, 255, 0.15);
            border-radius: 14px;
            box-shadow: 0 16px 36px rgba(0, 0, 0, 0.7);
            z-index: 100;
            overflow: hidden;
            padding: 10px;
            overscroll-behavior: contain;
        }

        .kvx-currency-search-box,
        .kvx-dropdown-search-box {
            display: flex;
            align-items: center;
            gap: 8px;
            background: #111317;
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 8px;
            padding: 8px 12px;
            margin-bottom: 8px;
        }

        .kvx-currency-search-input,
        .kvx-dropdown-search-input {
            width: 100%;
            background: transparent;
            border: none;
            color: #ffffff;
            font-size: 0.85rem;
            outline: none;
        }

        .kvx-currency-list,
        .kvx-dropdown-list {
            max-height: 260px;
            overflow-y: auto;
            overflow-x: hidden;
            overscroll-behavior: contain;
            -webkit-overflow-scrolling: touch;
            touch-action: pan-y;
            scrollbar-width: thin;
            scrollbar-color: rgba(255, 255, 255, 0.25) rgba(255, 255, 255, 0.04);
        }

        /* Demo Trading Guide Sidebar Navigation Styles */
        .demo-nav-link {
            color: rgba(255, 255, 255, 0.55);
            font-size: 0.84rem;
            font-weight: 500;
            text-decoration: none;
            transition: all 0.2s ease;
            display: block;
            position: relative;
        }
        .demo-nav-link:hover {
            color: #ffffff;
        }
        .demo-nav-link.is-active {
            color: #ffffff !important;
            font-weight: 700 !important;
            font-size: 0.88rem !important;
        }

        .kvx-currency-list::-webkit-scrollbar,
        .kvx-dropdown-list::-webkit-scrollbar {
            width: 6px;
        }

        .kvx-currency-list::-webkit-scrollbar-track,
        .kvx-dropdown-list::-webkit-scrollbar-track {
            background: rgba(255, 255, 255, 0.04);
            border-radius: 4px;
        }

        .kvx-currency-list::-webkit-scrollbar-thumb,
        .kvx-dropdown-list::-webkit-scrollbar-thumb {
            background: rgba(255, 255, 255, 0.25);
            border-radius: 4px;
        }

        .kvx-currency-list::-webkit-scrollbar-thumb:hover,
        .kvx-dropdown-list::-webkit-scrollbar-thumb:hover {
            background: rgba(255, 255, 255, 0.4);
        }

        .kvx-currency-item,
        .kvx-dropdown-item {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 10px 12px;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.15s ease;
        }

        .kvx-currency-item:hover,
        .kvx-currency-item.is-selected,
        .kvx-dropdown-item:hover,
        .kvx-dropdown-item.is-selected {
            background: rgba(255, 255, 255, 0.06);
        }

        .kvx-currency-item-left,
        .kvx-dropdown-item-left {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .kvx-currency-item-names,
        .kvx-dropdown-item-names {
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            line-height: 1.25;
        }

        .kvx-currency-item-names .kvx-currency-fullname,
        .kvx-dropdown-item-names .kvx-dropdown-item-sub {
            font-size: 0.78rem;
            color: rgba(255, 255, 255, 0.45);
        }

        .kvx-currency-item-right,
        .kvx-dropdown-item-right {
            display: flex;
            align-items: center;
            justify-content: flex-end;
            gap: 8px;
        }

        /* Step Content Panels */
        .kvx-step-content {
            margin-top: 10px;
            animation: kvxFadeSlideDown 0.25s ease-out;
        }

        @keyframes kvxFadeSlideDown {
            from {
                opacity: 0;
                transform: translateY(-6px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* Network Cards Grid (TRC20, ERC20, BEP20, SOL) */
        .kvx-network-cards-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
            gap: 12px;
            margin-top: 10px;
        }

        .kvx-net-card {
            background: #191c22;
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 12px;
            padding: 12px 14px;
            display: flex;
            align-items: center;
            gap: 10px;
            cursor: pointer;
            position: relative;
            transition: all 0.2s ease;
            user-select: none;
        }

        .kvx-net-card:hover {
            border-color: rgba(59, 130, 246, 0.5);
            background: #1e232e;
        }

        .kvx-net-card.is-active {
            background: #151a24;
            border: 1.5px solid #3b82f6;
            box-shadow: 0 0 12px rgba(59, 130, 246, 0.2);
        }

        .kvx-net-card-icon {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            object-fit: contain;
            flex-shrink: 0;
        }

        .kvx-net-card-name {
            font-size: 0.88rem;
            font-weight: 700;
            color: #ffffff;
            flex: 1;
        }

        .kvx-net-card-check {
            width: 18px;
            height: 18px;
            background: #3b82f6;
            color: #ffffff;
            border-radius: 50%;
            display: none;
            align-items: center;
            justify-content: center;
            font-size: 11px;
            font-weight: 800;
            flex-shrink: 0;
        }

        .kvx-net-card.is-active .kvx-net-card-check {
            display: flex;
        }

        /* QR & Address Card */
        .kvx-qr-address-card {
            display: flex;
            gap: 20px;
            background: #181b22;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 14px;
            padding: 18px;
            align-items: flex-start;
            margin-top: 10px;
        }

        @media (max-width: 600px) {
            .kvx-qr-address-card {
                flex-direction: column;
                align-items: center;
            }
        }

        .kvx-qr-box {
            position: relative;
            background: #ffffff;
            padding: 8px;
            border-radius: 12px;
            flex-shrink: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            width: 144px;
            height: 144px;
            box-sizing: border-box;
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
            border: 2px solid rgba(255, 255, 255, 0.15);
        }

        .kvx-qr-box img.qr-img {
            width: 128px;
            height: 128px;
            display: block;
            image-rendering: -webkit-optimize-contrast;
            image-rendering: crisp-edges;
        }

        .kvx-qr-center-logo {
            position: absolute;
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: #ffffff;
            padding: 2px;
            box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
            display: flex;
            align-items: center;
            justify-content: center;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
        }

        .kvx-qr-center-logo img {
            width: 26px;
            height: 26px;
            border-radius: 50%;
            object-fit: cover;
        }

        .kvx-address-details {
            flex: 1;
            min-width: 0;
            width: 100%;
        }

        .kvx-address-label {
            font-size: 0.88rem;
            font-weight: 700;
            color: #ffffff;
            margin-bottom: 8px;
        }

        .kvx-address-copy-box {
            display: flex;
            align-items: center;
            justify-content: space-between;
            background: #111317;
            border: 1px solid rgba(255, 255, 255, 0.12);
            border-radius: 8px;
            padding: 8px 12px;
            gap: 8px;
            margin-bottom: 10px;
        }

        .kvx-address-text {
            font-family: ui-monospace, SFMono-Regular, monospace;
            font-size: 0.82rem;
            color: #ffffff;
            word-break: break-all;
            user-select: all;
        }

        .kvx-btn-copy-icon {
            background: none;
            border: none;
            color: rgba(255, 255, 255, 0.6);
            cursor: pointer;
            padding: 4px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            transition: color 0.15s ease;
        }

        .kvx-btn-copy-icon:hover {
            color: #ffffff;
        }

        .kvx-btn-copy {
            background: #272a34;
            border: 1px solid rgba(255, 255, 255, 0.12);
            border-radius: 6px;
            padding: 5px 14px;
            color: #ffffff;
            font-size: 0.80rem;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.15s ease;
            flex-shrink: 0;
        }

        .kvx-btn-copy:hover {
            background: #333846;
        }

        .kvx-btn-scan-addr {
            background: #1e2229;
            color: #ffffff;
            border: 1px solid rgba(255, 255, 255, 0.12);
            border-radius: 8px;
            padding: 7px 14px;
            font-size: 0.82rem;
            font-weight: 600;
            cursor: pointer;
            display: inline-flex;
            align-items: center;
            gap: 6px;
            transition: all 0.2s ease;
        }

        .kvx-btn-scan-addr:hover {
            background: #272c35;
            border-color: rgba(255, 255, 255, 0.25);
        }

        .kvx-deposit-notice {
            font-size: 0.78rem;
            color: rgba(255, 255, 255, 0.6);
            line-height: 1.55;
            display: flex;
            flex-direction: column;
            gap: 4px;
            background: #111317;
            border: 1px solid rgba(255, 255, 255, 0.06);
            border-radius: 10px;
            padding: 12px 14px;
        }

        .kvx-deposit-notice strong {
            color: #ffffff;
        }

        .kvx-notice-dot {
            display: inline-block;
            width: 6px;
            height: 6px;
            border-radius: 50%;
            background: #3b82f6;
            margin-right: 6px;
            vertical-align: middle;
        }

        /* Step 5 Verify Card */
        .kvx-verify-step-card {
            background: #181b22;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 14px;
            padding: 16px 20px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 16px;
            margin-top: 10px;
        }

        .kvx-verify-icon-box {
            width: 42px;
            height: 42px;
            border-radius: 12px;
            background: rgba(234, 179, 8, 0.12);
            color: #eab308;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .kvx-verify-btn-blue {
            background: #2563eb;
            color: #ffffff;
            font-weight: 700;
            font-size: 0.88rem;
            padding: 9px 24px;
            border-radius: 10px;
            border: none;
            cursor: pointer;
            text-decoration: none;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            transition: background 0.2s ease;
        }

        .kvx-verify-btn-blue:hover {
            background: #1d4ed8;
        }

        /* Footer Security inside Left Card */
        .kvx-deposit-footer-security {
            display: flex;
            align-items: center;
            justify-content: space-between;
            border-top: 1px solid rgba(255, 255, 255, 0.06);
            padding-top: 18px;
            margin-top: 24px;
            gap: 16px;
        }

        @media (max-width: 600px) {
            .kvx-deposit-footer-security {
                flex-direction: column;
                align-items: flex-start;
                gap: 8px;
            }
        }

        .kvx-security-brand {
            display: flex;
            align-items: center;
            gap: 8px;
            color: #ffffff;
            font-size: 0.84rem;
            font-weight: 500;
        }

        .kvx-security-brand svg {
            color: #3b82f6;
        }

        .kvx-security-text {
            font-size: 0.78rem;
            color: rgba(255, 255, 255, 0.45);
        }

        /* Regulatory Disclaimer */
        .kvx-deposit-disclaimer {
            font-size: 0.72rem;
            color: rgba(255, 255, 255, 0.35);
            line-height: 1.6;
            margin-top: 14px;
            padding: 0 4px;
        }

        /* Right Sidebar Cards */
        .kvx-deposit-sidebar {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .kvx-sidebar-card {
            background: #14161b;
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 20px;
            padding: 24px;
            box-shadow: 0 8px 28px rgba(0, 0, 0, 0.3);
        }

        .kvx-sidebar-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 18px;
        }

        .kvx-sidebar-title {
            font-size: 1.15rem;
            font-weight: 700;
            color: #ffffff;
            margin: 0;
        }

        .kvx-support-link {
            font-size: 0.82rem;
            font-weight: 600;
            color: #ffffff;
            text-decoration: none;
            display: inline-flex;
            align-items: center;
            gap: 4px;
            transition: opacity 0.15s;
        }

        .kvx-support-link:hover {
            opacity: 0.75;
        }

        /* FAQ list */
        .kvx-faq-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .kvx-faq-item {
            border-bottom: 1px solid rgba(255, 255, 255, 0.05);
            padding-bottom: 8px;
        }

        .kvx-faq-item:last-child {
            border-bottom: none;
            padding-bottom: 0;
        }

        .kvx-faq-question {
            width: 100%;
            background: none;
            border: none;
            padding: 10px 4px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            color: rgba(255, 255, 255, 0.85);
            font-size: 0.86rem;
            font-weight: 500;
            cursor: pointer;
            text-align: left;
            transition: color 0.15s ease;
        }

        .kvx-faq-question:hover {
            color: #ffffff;
        }

        .kvx-faq-q-left {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .kvx-faq-q-left svg {
            color: rgba(255, 255, 255, 0.45);
            flex-shrink: 0;
        }

        .kvx-faq-arrow {
            color: rgba(255, 255, 255, 0.4);
            font-size: 0.85rem;
            transition: transform 0.2s ease;
        }

        .kvx-faq-item.is-open .kvx-faq-arrow {
            transform: rotate(90deg);
            color: #ffffff;
        }

        .kvx-faq-answer {
            padding: 4px 6px 12px 28px;
            font-size: 0.8rem;
            color: rgba(255, 255, 255, 0.55);
            line-height: 1.5;
        }

        /* Trade with confidence */
        .kvx-trust-list {
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .kvx-trust-item {
            display: flex;
            gap: 14px;
            align-items: flex-start;
        }

        .kvx-trust-icon {
            color: #ffffff;
            flex-shrink: 0;
            padding-top: 2px;
        }

        .kvx-trust-text {
            flex: 1;
        }

        .kvx-trust-heading {
            font-size: 0.95rem;
            font-weight: 700;
            color: #ffffff;
            margin-bottom: 2px;
        }

        .kvx-trust-sub {
            font-size: 0.8rem;
            color: rgba(255, 255, 255, 0.5);
            line-height: 1.45;
        }

        .kvx-trust-link {
            color: #60a5fa;
            text-decoration: underline;
        }
    </style>
@endpush

@push('scripts')
    @vite('resources/js/pages/wallet.js')
    <script>
        window.getSavedWithdrawMode = function() {
            try {
                const param = (new URLSearchParams(window.location.search).get('withdraw_mode') || '').toLowerCase();
                if (param === 'money' || param === 'crypto') return param;
            } catch(e) {}
            try {
                const saved = sessionStorage.getItem('kryvex_active_withdraw_mode');
                if (saved === 'money' || saved === 'crypto') return saved;
            } catch(e) {}
            return '';
        };

        window.normalizeDepositMode = function(value) {
            const v = String(value || '').toLowerCase();
            if (v === 'money' || v === 'inr' || v === 'fiat') return 'money';
            if (v === 'crypto' || v === 'usdt') return 'crypto';
            return '';
        };

        window.getSavedDepositMode = function() {
            try {
                const params = new URLSearchParams(window.location.search);
                const fromUrl = window.normalizeDepositMode(params.get('mode') || params.get('method') || params.get('type'));
                if (fromUrl) return fromUrl;
            } catch(e) {}
            try {
                const fromSession = window.normalizeDepositMode(sessionStorage.getItem('kryvex_active_deposit_mode'));
                if (fromSession) return fromSession;
            } catch(e) {}
            try {
                const fromLocal = window.normalizeDepositMode(localStorage.getItem('kryvex_active_deposit_mode'));
                if (fromLocal) return fromLocal;
            } catch(e) {}
            return '';
        };

        window.getDefaultWithdrawTab = function() {
            const saved = window.getSavedWithdrawMode();
            if (saved) return saved === 'money' ? 'inr' : 'usdt';
            const activeCur = (window.getActiveCurrency ? window.getActiveCurrency() : (localStorage.getItem('kryvex_currency') || 'USDT')).toUpperCase();
            return activeCur === 'INR' ? 'inr' : 'usdt';
        };

        // Global Floating Toast Notification System
        window.showWalletToast = function(message, type = 'info', duration = 4500) {
            let container = document.getElementById('kryvexToastContainer');
            if (!container) {
                container = document.createElement('div');
                container.id = 'kryvexToastContainer';
                container.style.cssText = 'position: fixed; top: 24px; right: 24px; z-index: 9999999; display: flex; flex-direction: column; gap: 10px; pointer-events: none; max-width: 420px; width: calc(100vw - 48px);';
                document.body.appendChild(container);
            }

            const toast = document.createElement('div');
            toast.style.cssText = 'pointer-events: auto; display: flex; align-items: flex-start; gap: 12px; padding: 14px 16px; border-radius: 12px; backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); box-shadow: 0 10px 30px rgba(0,0,0,0.5), 0 0 0 1px rgba(255,255,255,0.1); font-size: 0.88rem; line-height: 1.45; font-family: ui-sans-serif, system-ui, sans-serif; transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1); transform: translateY(-10px); opacity: 0;';

            let iconSvg = '';
            let bgGradient = '';

            if (type === 'success') {
                bgGradient = 'linear-gradient(135deg, rgba(16, 185, 129, 0.95), rgba(5, 150, 105, 0.95))';
                iconSvg = '<svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7"/></svg>';
            } else if (type === 'error' || type === 'danger') {
                bgGradient = 'linear-gradient(135deg, rgba(239, 68, 68, 0.95), rgba(185, 28, 28, 0.95))';
                iconSvg = '<svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12"/></svg>';
            } else if (type === 'warning') {
                bgGradient = 'linear-gradient(135deg, rgba(245, 158, 11, 0.95), rgba(217, 119, 6, 0.95))';
                iconSvg = '<svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2.5"><path stroke-linecap="round" stroke-linejoin="round" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"/></svg>';
            } else {
                bgGradient = 'linear-gradient(135deg, rgba(59, 130, 246, 0.95), rgba(37, 99, 235, 0.95))';
                iconSvg = '<svg width="20" height="20" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>';
            }

            toast.style.background = bgGradient;
            toast.style.color = '#ffffff';

            toast.innerHTML = `
                <div style="flex-shrink:0; margin-top: 1px;">${iconSvg}</div>
                <div style="flex:1; word-break: break-word; font-weight: 500;">${message}</div>
                <button type="button" style="background:none; border:none; color:rgba(255,255,255,0.7); cursor:pointer; padding:0; margin-left:8px; font-size:1.1rem; line-height:1; display:flex; align-items:center;" onclick="this.parentElement.remove()">×</button>
            `;

            container.appendChild(toast);
            requestAnimationFrame(() => {
                toast.style.transform = 'translateY(0)';
                toast.style.opacity = '1';
            });

            setTimeout(() => {
                toast.style.opacity = '0';
                toast.style.transform = 'translateY(-10px)';
                setTimeout(() => toast.remove(), 300);
            }, duration);
        };

        function initWalletPage() {
            function resetAllWalletModalInputs() {
                const ids = [
                    'dpUsdAmountInput', 'dpInrAmountInput', 'tfAmountInput', 'transferAmountInput',
                    'walletActionAmount', 'wdAmountInput', 'wdAddressInput', 'walletWithdrawAddressInput',
                    'walletUtrInput', 'inrWithdrawAmount', 'withdrawAddressInput', 'cryptoAssetAmountInput',
                    'cryptoAssetTxHashInput', 'internalRecipientAddressInput', 'internalSendAmountInput',
                    'internalSendNoteInput', 'exchangeFromAmount', 'exchangeToAmount', 'newAccountName'
                ];
                ids.forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.value = '';
                });
                const youPay = document.getElementById('inrDepositConvYouPay');
                const cred = document.getElementById('inrDepositConvCredit');
                if (youPay) youPay.textContent = '₹0.00';
                if (cred) cred.textContent = '$0.00 USD';
            }

            // Global close listener for resets across all popup modals
            document.addEventListener('click', (e) => {
                if (e.target.closest('#closeDepositModalBtn, #closeTransferModalBtn, #closeCryptoAssetDepositModalBtn, #closeExchangeModalBtn, #closeInternalTransferModalBtn, #btnCloseCreateAccountModal, [data-close-wallet-modal], .dharma-modal-close, .futures-modal-close')) {
                    resetAllWalletModalInputs();
                }
            });

            // Deposit Modal Controls
            const depositModal = document.getElementById('depositModalBackdrop');
            // Deposit Action Handlers -> Directly navigate to dedicated Step Deposit view
            function openDedicatedStepDeposit(targetCur = null) {
                switchMainTab('wallet-ops', true);
                switchWalletInnerNav('deposit');
                const cur = targetCur ? String(targetCur).toUpperCase() : null;
                if (cur === 'INR' || cur === 'MONEY') {
                    if (typeof window.setStepDepositMode === 'function') {
                        window.setStepDepositMode('money');
                    }
                } else {
                    if (typeof window.setStepDepositMode === 'function') {
                        window.setStepDepositMode('crypto');
                    }
                    const sym = (cur && cur !== 'CRYPTO') ? cur : null;
                    if (sym && typeof window.selectStepDepositCurrency === 'function') {
                        window.selectStepDepositCurrency(sym);
                    } else if (typeof window.resetStepDepositView === 'function') {
                        window.resetStepDepositView();
                    }
                }
                setTimeout(() => {
                    const el = document.getElementById('innerPanelDeposit') || document.getElementById('viewSectionWalletOps');
                    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }, 60);
            }
            window.openDedicatedStepDeposit = openDedicatedStepDeposit;

            function switchModalDepositMode(mode) {
                const btnCrypto = document.getElementById('btnModalDepCrypto');
                const btnMoney = document.getElementById('btnModalDepMoney');
                const usdSec = document.getElementById('dpUsdSection');
                const inrSec = document.getElementById('dpInrSection');
                const titleEl = document.getElementById('dpHeadTitle');
                const subEl = document.getElementById('dpHeadSub');

                if (mode === 'money') {
                    if (btnCrypto) {
                        btnCrypto.classList.remove('bg-blue-600', 'text-white');
                        btnCrypto.classList.add('text-slate-400');
                    }
                    if (btnMoney) {
                        btnMoney.classList.add('bg-blue-600', 'text-white');
                        btnMoney.classList.remove('text-slate-400');
                    }
                    if (usdSec) usdSec.style.display = 'none';
                    if (inrSec) inrSec.style.display = 'block';
                    if (titleEl) titleEl.textContent = 'Deposit Money (INR)';
                    if (subEl) subEl.textContent = 'Deposit via UPI / IMPS / NetBanking to your account.';
                } else {
                    if (btnMoney) {
                        btnMoney.classList.remove('bg-blue-600', 'text-white');
                        btnMoney.classList.add('text-slate-400');
                    }
                    if (btnCrypto) {
                        btnCrypto.classList.add('bg-blue-600', 'text-white');
                        btnCrypto.classList.remove('text-slate-400');
                    }
                    if (inrSec) inrSec.style.display = 'none';
                    if (usdSec) usdSec.style.display = 'block';
                    if (titleEl) titleEl.textContent = 'Deposit Crypto (USDT)';
                    if (subEl) subEl.textContent = 'Deposit USDT to your account using the details below.';
                }
            }
            window.switchModalDepositMode = switchModalDepositMode;

            const btnMCrypto = document.getElementById('btnModalDepCrypto');
            const btnMMoney = document.getElementById('btnModalDepMoney');
            if (btnMCrypto) btnMCrypto.addEventListener('click', () => switchModalDepositMode('crypto'));
            if (btnMMoney) btnMMoney.addEventListener('click', () => switchModalDepositMode('money'));

            function openDepositModalPopup(targetCur = 'USDT') {
                if (typeof window.openAddFundsModal === 'function') {
                    window.openAddFundsModal();
                    return;
                }
                const globalModal = document.getElementById('globalAddFundsModal');
                if (globalModal) {
                    globalModal.hidden = false;
                    globalModal.removeAttribute('hidden');
                    globalModal.style.display = 'flex';
                    globalModal.style.zIndex = '999999';
                    return;
                }
                const depModal = document.getElementById('depositModalBackdrop');
                if (depModal) {
                    const cur = targetCur ? String(targetCur).toUpperCase() : 'USDT';
                    const isMoney = (cur === 'INR' || cur === 'MONEY');
                    switchModalDepositMode(isMoney ? 'money' : 'crypto');
                    depModal.hidden = false;
                    depModal.style.display = 'flex';
                }
            }
            window.openDepositModalPopup = openDepositModalPopup;

            // Global event delegation for all deposit triggers across the page
            document.addEventListener('click', (e) => {
                const depBtn = e.target.closest('[data-action-deposit], [data-action-deposit-asset], [data-action-deposit-crypto], [data-action="deposit"], .btn-deposit, #topBannerDepositBtn');
                if (depBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    const targetCur = depBtn.getAttribute('data-currency') || depBtn.getAttribute('data-action-deposit-asset') || depBtn.getAttribute('data-action-deposit-crypto') || 'USDT';

                    const opsSection = document.getElementById('viewSectionWalletOps');
                    const isOpsVisible = opsSection && opsSection.style.display !== 'none';
                    const innerPanelDeposit = document.getElementById('innerPanelDeposit');
                    const isDepositPanelVisible = isOpsVisible && innerPanelDeposit && innerPanelDeposit.style.display !== 'none';

                    if (isDepositPanelVisible) {
                        openDedicatedStepDeposit(targetCur);
                    } else {
                        // If on Overview, Trading accounts, or Wallet tabs, ONLY open the Popup Modal!
                        if (typeof window.openAddFundsModal === 'function') {
                            window.openAddFundsModal();
                        } else {
                            openDepositModalPopup(targetCur);
                        }
                    }
                }
            });

            // Handle Submitting / Selecting in Modal -> Navigates to dedicated Step Deposit view
            const usdSubmitBtn = document.getElementById('dpUsdSubmitBtn');
            if (usdSubmitBtn) {
                usdSubmitBtn.addEventListener('click', () => {
                    if (depositModal) {
                        depositModal.hidden = true;
                        depositModal.style.display = 'none';
                    }
                    openDedicatedStepDeposit('USDT');
                });
            }

            const inrSubmitBtn = document.getElementById('dpInrSubmitBtn');
            if (inrSubmitBtn) {
                inrSubmitBtn.addEventListener('click', () => {
                    if (depositModal) {
                        depositModal.hidden = true;
                        depositModal.style.display = 'none';
                    }
                    openDedicatedStepDeposit('INR');
                });
            }

            const closeDepositBtn = document.getElementById('closeDepositModalBtn');
            if (closeDepositBtn) {
                closeDepositBtn.addEventListener('click', () => {
                    resetAllWalletModalInputs();
                    if (depositModal) {
                        depositModal.hidden = true;
                        depositModal.style.display = 'none';
                    }
                });
            }

            // Transfer Modal Controls
            const transferModal = document.getElementById('transferModalBackdrop');
            const openTransferBtns = document.querySelectorAll('[data-action-transfer]');
            const closeTransferBtn = document.getElementById('closeTransferModalBtn');

            function openTransferModalWithCurrency(targetCur) {
                resetAllWalletModalInputs();
                if (typeof window.openAccountTransferModal === 'function') {
                    window.openAccountTransferModal(null, null, targetCur || 'USD');
                    return;
                }
                if (transferModal) transferModal.hidden = false;
                if (typeof window.updateTransferLiveCalculation === 'function') {
                    window.updateTransferLiveCalculation();
                }
            }
            window.openTransferModalWithCurrency = openTransferModalWithCurrency;

            // Global delegation for transfer actions
            document.addEventListener('click', (e) => {
                const trBtn = e.target.closest('[data-action-transfer], #topBannerTransferBtn');
                if (trBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    const targetCur = trBtn.getAttribute('data-currency');
                    openTransferModalWithCurrency(targetCur);
                }
            });

            if (closeTransferBtn) {
                closeTransferBtn.addEventListener('click', () => {
                    resetAllWalletModalInputs();
                    if (transferModal) transferModal.hidden = true;
                });
            }

            // Exchange / Convert Controls
            const exchangeModal = document.getElementById('exchangeModalBackdrop') || document.getElementById('exchangeModal');
            const openExchangeBtns = document.querySelectorAll('[data-action-exchange]');
            const closeExchangeBtn = document.getElementById('closeExchangeModalBtn');

            openExchangeBtns.forEach(btn => {
                btn.addEventListener('click', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    resetAllWalletModalInputs();
                    if (exchangeModal) {
                        exchangeModal.hidden = true;
                        exchangeModal.style.display = 'none';
                    }
                    const asset = btn.getAttribute('data-action-exchange-asset');
                    switchMainTab('exchange', true);
                    if (asset && asset.toUpperCase() !== 'USDT' && asset.toUpperCase() !== 'USD' && typeof window.setSwapFromAsset === 'function') {
                        window.setSwapFromAsset(asset);
                    } else if (typeof window.resetSwapToDirectMode === 'function') {
                        window.resetSwapToDirectMode();
                    }
                });
            });

            if (closeExchangeBtn) {
                closeExchangeBtn.addEventListener('click', () => {
                    resetAllWalletModalInputs();
                    if (exchangeModal) {
                        exchangeModal.hidden = true;
                        exchangeModal.style.display = 'none';
                    }
                });
            }

            // Global event delegation for internal transfer buttons
            document.addEventListener('click', (e) => {
                const intBtn = e.target.closest('[data-action-internal-asset], [data-action-internal]');
                if (intBtn) {
                    e.preventDefault();
                    e.stopPropagation();
                    const asset = (intBtn.getAttribute('data-action-internal-asset') || intBtn.getAttribute('data-currency') || 'BTC').toUpperCase();
                    if (typeof window.openInternalTransferModal === 'function') {
                        window.openInternalTransferModal(asset, 'receive');
                    } else {
                        const internalModal = document.getElementById('internalTransferModalBackdrop');
                        if (internalModal) internalModal.hidden = false;
                    }
                }
            });

            // Main Sub-Tab Navigation Switcher (Overview | Trading accounts | Wallet)
            const subnavHeader = document.querySelector('.dharma-subnav');
            const btnOverview = document.getElementById('tabNavOverview');
            const btnTrading = document.getElementById('tabNavTrading');
            const btnWallet = document.getElementById('tabNavWallet');

            const sectionOverview = document.getElementById('viewSectionOverview');
            const sectionTrading = document.getElementById('viewSectionTrading');
            const sectionWallet = document.getElementById('viewSectionWallet');
            const sectionWalletOps = document.getElementById('viewSectionWalletOps');
            const sectionExchange = document.getElementById('viewSectionExchange');

            // Top Header Action Buttons Binding
            const topBtnDeposit = document.getElementById('topBannerDepositBtn');
            const topBtnWithdraw = document.getElementById('topBannerWithdrawBtn');
            const topBtnHistory = document.getElementById('topBannerHistoryBtn');

            let walletBalancesLoading = false;
            async function loadAndRenderAllWalletBalances() {
                if (walletBalancesLoading) return;
                walletBalancesLoading = true;
                try {
                    const token = localStorage.getItem('kryvex_access_token');
                    let user = {};
                    try { user = JSON.parse(localStorage.getItem('kryvex_user') || '{}') || {}; } catch(e) {}
                    const broker = (user.broker_type || 'kryvex').toLowerCase();

                    const res = await fetch(`/api/wallet?broker_type=${broker}`, {
                        headers: {
                            'Accept': 'application/json',
                            'X-Broker-Type': broker,
                            ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                        }
                    });

                    if (!res.ok) return;
                    const json = await res.json();
                    if (!json.success || !json.data || !json.data.wallet) return;

                    const wallet = json.data.wallet;
                    const rate = Number(json.data.inr_rate || json.data.usdt_inr_rate || 95);
                    const isLive = !wallet.is_demo;

                    // 1. Resolve Available USD / USDT Balance
                    const realMain = Number(wallet.real_main_balance || 0);
                    const demoMain = Number(wallet.demo_main_balance || 0);
                    const cryptoBalances = wallet.crypto_balances || {};
                    const usdtBal = Number(cryptoBalances.USDT !== undefined ? cryptoBalances.USDT : (isLive ? realMain : demoMain));
                    const activeMainBal = isLive ? (realMain > 0 ? realMain : usdtBal) : demoMain;
                    const inrBal = activeMainBal * rate;

                    // 2. Update Top Hero Balance Banner & Cards
                    const setVal = (id, valText, rawNum) => {
                        const el = document.getElementById(id);
                        if (el) {
                            el.dataset.realValue = valText;
                            el.textContent = window.isWalletBalanceHidden ? '••••••••' : valText;
                            if (rawNum !== undefined) {
                                const row = el.closest('[data-asset-row]');
                                if (row) row.setAttribute('data-asset-balance', String(rawNum));
                            }
                        }
                    };

                    const formattedUsd = '$' + activeMainBal.toFixed(2);
                    const formattedInr = '₹' + inrBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

                    setVal('demoMainBalance', formattedUsd);
                    setVal('ovWalletAvailBalance', formattedUsd);
                    setVal('ovSplitMainWalletBalance', formattedUsd);
                    setVal('splitMainWalletBalance', formattedUsd);

                    // 3. Update Withdraw Available Banner
                    const withdrawAvail = document.getElementById('withdrawMainAvailBalanceText');
                    if (withdrawAvail) {
                        const isUsdtTab = !document.getElementById('inrWithdrawForm') || document.getElementById('inrWithdrawForm').style.display === 'none';
                        const txt = isUsdtTab ? formattedUsd : formattedInr;
                        withdrawAvail.dataset.realValue = txt;
                        withdrawAvail.textContent = window.isWalletBalanceHidden ? '••••••••' : txt;
                    }

                    // 4. Update Money & Crypto Table Rows (Available & Pending)
                    const cryptoPending = wallet.crypto_pending_balances || {};
                    const pendingUsdt = Number(cryptoPending.USDT !== undefined ? cryptoPending.USDT : (wallet.demo_withdrawal_locked_balance || wallet.real_withdrawal_locked_balance || 0));
                    const pendingInr = Number(wallet.demo_withdrawal_locked_balance_inr || wallet.real_withdrawal_locked_balance_inr || 0);

                    setVal('usdBalanceDisplay', activeMainBal.toFixed(2), activeMainBal);
                    setVal('pendingWithdrawalBalance', pendingUsdt > 0 ? pendingUsdt.toFixed(2) : '0');
                    setVal('inrBalanceDisplay', formattedInr, inrBal);
                    setVal('pendingInrWithdrawalBalance', pendingInr > 0 ? ('₹' + pendingInr.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })) : '₹0.00');
                    setVal('usdtBalanceDisplay', usdtBal.toFixed(2), usdtBal);
                    setVal('pendingUsdtWithdrawalBalance', pendingUsdt > 0 ? pendingUsdt.toFixed(2) : '0');

                    setVal('btcBalanceDisplay', String(cryptoBalances.BTC || 0), Number(cryptoBalances.BTC || 0));
                    setVal('pendingBtcWithdrawalBalance', String(cryptoPending.BTC || 0));
                    setVal('ethBalanceDisplay', String(cryptoBalances.ETH || 0), Number(cryptoBalances.ETH || 0));
                    setVal('pendingEthWithdrawalBalance', String(cryptoPending.ETH || 0));
                    setVal('usdcBalanceDisplay', String(cryptoBalances.USDC || 0), Number(cryptoBalances.USDC || 0));
                    setVal('pendingUsdcWithdrawalBalance', String(cryptoPending.USDC || 0));
                    setVal('solBalanceDisplay', String(cryptoBalances.SOL || 0), Number(cryptoBalances.SOL || 0));
                    setVal('pendingSolWithdrawalBalance', String(cryptoPending.SOL || 0));
                    setVal('bnbBalanceDisplay', String(cryptoBalances.BNB || 0), Number(cryptoBalances.BNB || 0));
                    setVal('pendingBnbWithdrawalBalance', String(cryptoPending.BNB || 0));
                    setVal('xrpBalanceDisplay', String(cryptoBalances.XRP || 0), Number(cryptoBalances.XRP || 0));
                    setVal('pendingXrpWithdrawalBalance', String(cryptoPending.XRP || 0));
                    setVal('adaBalanceDisplay', String(cryptoBalances.ADA || 0), Number(cryptoBalances.ADA || 0));
                    setVal('pendingAdaWithdrawalBalance', String(cryptoPending.ADA || 0));
                    setVal('dogeBalanceDisplay', String(cryptoBalances.DOGE || 0), Number(cryptoBalances.DOGE || 0));
                    setVal('pendingDogeWithdrawalBalance', String(cryptoPending.DOGE || 0));
                    setVal('dotBalanceDisplay', String(cryptoBalances.DOT || 0), Number(cryptoBalances.DOT || 0));
                    setVal('pendingDotWithdrawalBalance', String(cryptoPending.DOT || 0));
                    setVal('ltcBalanceDisplay', String(cryptoBalances.LTC || 0), Number(cryptoBalances.LTC || 0));
                    setVal('pendingLtcWithdrawalBalance', String(cryptoPending.LTC || 0));
                    setVal('trxBalanceDisplay', String(cryptoBalances.TRX || 0), Number(cryptoBalances.TRX || 0));
                    setVal('pendingTrxWithdrawalBalance', String(cryptoPending.TRX || 0));
                    setVal('avaxBalanceDisplay', String(cryptoBalances.AVAX || 0), Number(cryptoBalances.AVAX || 0));
                    setVal('pendingAvaxWithdrawalBalance', String(cryptoPending.AVAX || 0));

                    // Subtitle crypto estimate
                    const subTitle = document.querySelector('.dharma-section-subtitle');
                    if (subTitle) subTitle.textContent = `| ≈ ${usdtBal.toFixed(2)} USDT`;

                    // Update stored global state
                    window.walletDataState = window.walletDataState || {};
                    window.walletDataState.wallet = wallet;
                    window.walletDataState.depositNetworks = json.data.deposit_networks || [];
                    if (json.data && json.data.withdrawal_charges) {
                        window.walletDataState.withdrawal_charges = json.data.withdrawal_charges;
                    }
                    if (typeof window.updateWithdrawCalculation === 'function') {
                        window.updateWithdrawCalculation();
                    }
                } catch(err) {
                    console.warn('loadAndRenderAllWalletBalances error:', err);
                } finally {
                    walletBalancesLoading = false;
                }
            }
            window.loadAndRenderAllWalletBalances = loadAndRenderAllWalletBalances;
            loadAndRenderAllWalletBalances();
            setInterval(() => {
                if (!document.hidden) loadAndRenderAllWalletBalances();
            }, 10000);
            document.addEventListener('visibilitychange', () => {
                if (!document.hidden) loadAndRenderAllWalletBalances();
            });

            function syncBalancesToOverview() {
                const demo = document.getElementById('demoMainBalance');
                const ov = document.getElementById('overviewMainBalance');
                const ovWallet = document.getElementById('ovWalletAvailBalance');
                const ovSplitMain = document.getElementById('ovSplitMainWalletBalance');
                const splitMain = document.getElementById('splitMainWalletBalance');
                const splitTrading = document.getElementById('splitActiveTradingBalance');
                const ovTrading = document.getElementById('ovActiveTradingBalance');
                const ovSplitTrading = document.getElementById('ovSplitActiveTradingBalance');
                const ovTooltipWallet = document.getElementById('ovTooltipWalletVal');
                const ovTooltipTrading = document.getElementById('ovTooltipTradingVal');
                const tradingBal = document.getElementById('tradingMainBalance');
                const tradingTooltip = document.getElementById('tradingTooltipActiveVal');

                const syncElem = (src, dest) => {
                    if (!src || !dest) return;
                    if (src.dataset && src.dataset.realValue && src.dataset.realValue !== '••••••••' && src.dataset.realValue !== '--') {
                        dest.dataset.realValue = src.dataset.realValue;
                    } else if (src.textContent && src.textContent !== '••••••••' && src.textContent !== '--') {
                        dest.dataset.realValue = src.textContent;
                    }
                    if (window.isWalletBalanceHidden) {
                        dest.textContent = '••••••••';
                    } else {
                        dest.textContent = dest.dataset.realValue || src.textContent;
                    }
                };

                syncElem(demo, ovWallet);
                syncElem(splitMain, ovSplitMain);
                syncElem(splitTrading, ovTrading);
                syncElem(splitTrading, ovSplitTrading);
            }
            window.syncBalancesToOverview = syncBalancesToOverview;

            const demoMainBalEl = document.getElementById('demoMainBalance');
            if (demoMainBalEl && window.MutationObserver) {
                const balObserver = new MutationObserver(() => syncBalancesToOverview());
                balObserver.observe(demoMainBalEl, { childList: true, characterData: true, subtree: true });
            }
            setInterval(syncBalancesToOverview, 1000);

            // Overview Top Contracts Logic
            const overviewCoinLogos = {
                BTC: "/images/coins/btc.png",
                ETH: "/images/coins/eth.png",
                USDT: "https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/usdt.png",
                BNB: "https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/bnb.png",
                SOL: "/images/coins/sol.png",
                XRP: "https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/xrp.png",
                DOGE: "https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/doge.png",
                ADA: "https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/ada.png",
                XAU: "/images/coins/gold.svg",
                GOLD: "/images/coins/gold.svg",
                PAXG: "/images/coins/paxg.png",
                XAUT: "/images/coins/gold.svg",
                XAUUSDT: "/images/coins/gold.svg"
            };

            function formatOverviewContractPrice(val) {
                const num = Number(val);
                if (isNaN(num) || num === 0) return '$0.00';
                if (num >= 1000) {
                    return '$' + num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                } else if (num >= 1) {
                    return '$' + num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
                } else {
                    return '$' + num.toFixed(6);
                }
            }

            function renderOverviewTopContracts(tickers) {
                const tbody = document.getElementById('overviewTopContractsBody');
                if (!tbody) return;

                if (!Array.isArray(tickers) || !tickers.length) return;

                // Sort by 24h volume (highest first) and take top 5
                const sorted = [...tickers].sort((a, b) => {
                    const volA = Number(a.quote_volume || a.volume || 0);
                    const volB = Number(b.quote_volume || b.volume || 0);
                    return volB - volA;
                });

                const top5 = sorted.slice(0, 5);
                if (!top5.length) return;

                tbody.innerHTML = top5.map(ticker => {
                    const rawSym = (ticker.symbol || '').toUpperCase().replace('USDT', '');
                    const baseSym = rawSym || 'BTC';
                    const displaySym = `${baseSym}/USDT`;
                    const isGold = (baseSym === 'XAU' || baseSym === 'GOLD' || baseSym === 'PAXG' || baseSym === 'XAUT' || (ticker.symbol || '').toUpperCase().includes('XAU'));
                    const logo = isGold ? "/images/coins/gold.svg" : (overviewCoinLogos[baseSym] || `https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${baseSym.toLowerCase()}.png`);
                    const fallbackLogo = isGold 
                        ? "/images/coins/gold.svg"
                        : `https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${baseSym.toLowerCase()}.png`;
                    const lev = ticker.leverage ? `${ticker.leverage}` : (baseSym === 'BTC' ? '200x' : '100x');
                    const isPos = Number(ticker.price_change_percent) >= 0;
                    const changeStr = (isPos ? '+' : '') + Number(ticker.price_change_percent || 0).toFixed(2) + '%';
                    const changeStyle = isPos ? 'color: #34d399; background: rgba(16, 185, 129, 0.12); border: 1px solid rgba(16, 185, 129, 0.25);' : 'color: #f87171; background: rgba(239, 68, 68, 0.12); border: 1px solid rgba(239, 68, 68, 0.25);';
                    const priceStr = formatOverviewContractPrice(ticker.last_price);
                    const highStr = formatOverviewContractPrice(ticker.high_price || (ticker.last_price * 1.02));
                    const lowStr = formatOverviewContractPrice(ticker.low_price || (ticker.last_price * 0.98));
                    const tradeUrl = `/futures/${(ticker.symbol || '').toLowerCase()}`;

                    return `
                        <tr style="border-bottom: 1px solid rgba(255, 255, 255, 0.05);">
                            <td style="padding: 14px 16px;">
                                <div style="display: flex; align-items: center; gap: 12px;">
                                    <div style="width: 32px; height: 32px; border-radius: 50%; overflow: hidden; background: #1a1d29; border: 1px solid rgba(255,255,255,0.1); flex-shrink: 0; display: flex; align-items: center; justify-content: center;">
                                        <img src="${logo}" alt="${baseSym}" style="width: 100%; height: 100%; object-fit: cover;" onerror="this.onerror=null; this.src='${fallbackLogo}';">
                                    </div>
                                    <div>
                                        <span style="display: block; font-weight: 800; font-size: 0.92rem; color: #fff;">${displaySym}</span>
                                        <span style="display: block; font-size: 0.72rem; color: rgba(255,255,255,0.45);">${ticker.contract_type || 'USDT Perpetual'}</span>
                                    </div>
                                </div>
                            </td>
                            <td style="padding: 14px 16px; text-align: center;">
                                <span style="display: inline-block; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.12); color: #cbd5e1; font-size: 0.72rem; font-weight: 700; padding: 2px 8px; border-radius: 6px;">${lev}</span>
                            </td>
                            <td style="padding: 14px 16px; text-align: right; font-family: ui-monospace, SFMono-Regular, monospace; font-weight: 800; font-size: 0.92rem; color: #fff;">
                                ${priceStr}
                            </td>
                            <td style="padding: 14px 16px; text-align: right;">
                                <span style="display: inline-flex; align-items: center; justify-content: flex-end; padding: 3px 8px; border-radius: 6px; font-family: ui-monospace, SFMono-Regular, monospace; font-weight: 700; font-size: 0.8rem; ${changeStyle}">
                                    ${changeStr}
                                </span>
                            </td>
                            <td style="padding: 14px 16px; text-align: right; font-family: ui-monospace, SFMono-Regular, monospace; font-size: 0.78rem; color: rgba(255,255,255,0.6);" class="top-contracts-hide-mobile">
                                <span>${highStr}</span> / <span style="color: rgba(255,255,255,0.4);">${lowStr}</span>
                            </td>
                            <td style="padding: 14px 16px; text-align: right;">
                                <a href="${tradeUrl}" class="top-contracts-trade-btn">Trade</a>
                            </td>
                        </tr>
                    `;
                }).join('');
            }

            async function fetchOverviewTopContracts() {
                try {
                    const cached = localStorage.getItem('kryvex_cached_markets');
                    if (cached) {
                        try {
                            const parsed = JSON.parse(cached);
                            if (Array.isArray(parsed) && parsed.length) renderOverviewTopContracts(parsed);
                        } catch (e) {}
                    }

                    const res = await fetch('/api/markets/futures/tickers');
                    if (res.ok) {
                        const data = await res.json();
                        if (data && Array.isArray(data.data) && data.data.length) {
                            renderOverviewTopContracts(data.data);
                            try { localStorage.setItem('kryvex_cached_markets', JSON.stringify(data.data)); } catch (e) {}
                        }
                    }
                } catch (err) {
                    // Fail gracefully
                }
            }

            // Fetch top contracts on initial load and setup interval
            fetchOverviewTopContracts();
            setInterval(() => {
                const secOverview = document.getElementById('viewSectionOverview');
                if (!document.hidden && secOverview && secOverview.style.display !== 'none') {
                    fetchOverviewTopContracts();
                }
            }, 6000);

            function switchMainTab(tab, updateUrl = false) {
                const bOverview = document.getElementById('tabNavOverview') || btnOverview;
                const bTrading = document.getElementById('tabNavTrading') || btnTrading;
                const bWallet = document.getElementById('tabNavWallet') || btnWallet;

                const sOverview = document.getElementById('viewSectionOverview') || sectionOverview;
                const sTrading = document.getElementById('viewSectionTrading') || sectionTrading;
                const sWallet = document.getElementById('viewSectionWallet') || sectionWallet;
                const sWalletOps = document.getElementById('viewSectionWalletOps') || sectionWalletOps;
                const sExchange = document.getElementById('viewSectionExchange') || sectionExchange;
                const sHowTo = document.getElementById('viewSectionHowToDeposit');
                const sDemo = document.getElementById('viewSectionDemoTrading');
                const sSecurity = document.getElementById('viewSectionSecurityGuide');
                const sWhy = document.getElementById('viewSectionWhyKryvex');
                const sHeader = document.querySelector('.dharma-subnav') || subnavHeader;

                [bOverview, bTrading, bWallet].forEach(b => b?.classList.remove('is-active'));
                [sOverview, sTrading, sWallet, sWalletOps, sExchange, sHowTo, sDemo, sSecurity, sWhy].forEach(s => { if (s) s.style.display = 'none'; });

                if (tab === 'exchange' || tab === 'buy-exchange' || tab === 'buy_exchange') {
                    if (sHeader) sHeader.style.display = 'none';
                    if (sExchange) sExchange.style.display = 'block';
                    if (typeof window.initBuyExchangeView === 'function') {
                        window.initBuyExchangeView();
                    }
                } else if (tab === 'history' || tab === 'ledger' || tab === 'withdraw' || tab === 'deposit' || tab === 'wallet-ops') {
                    if (sHeader) sHeader.style.display = 'none';
                    if (sWalletOps) sWalletOps.style.display = 'block';
                    if (tab === 'deposit') {
                        switchWalletInnerNav('deposit');
                    } else if (tab === 'withdraw') {
                        switchWalletInnerNav('withdraw');
                    } else if (tab === 'history' || tab === 'ledger') {
                        switchWalletInnerNav('history');
                    }
                } else {
                    if (sHeader) sHeader.style.display = 'flex';

                    if (tab === 'trading' || tab === 'trading-accounts' || tab === 'trading_accounts') {
                        if (bTrading) bTrading.classList.add('is-active');
                        if (sTrading) sTrading.style.display = 'block';
                        syncBalancesToOverview();
                        if (typeof window.renderTradingAccountsPageList === 'function') {
                            window.renderTradingAccountsPageList();
                        } else {
                            setTimeout(() => {
                                if (typeof window.renderTradingAccountsPageList === 'function') {
                                    window.renderTradingAccountsPageList();
                                }
                            }, 120);
                        }
                    } else if (tab === 'overview') {
                        if (bOverview) bOverview.classList.add('is-active');
                        if (sOverview) sOverview.style.display = 'block';
                        syncBalancesToOverview();
                        fetchOverviewTopContracts();
                    } else if (tab === 'wallet') {
                        if (bWallet) bWallet.classList.add('is-active');
                        if (sWallet) sWallet.style.display = 'block';
                        syncBalancesToOverview();
                    } else {
                        // default / fallback to 'overview'
                        if (bOverview) bOverview.classList.add('is-active');
                        if (sOverview) sOverview.style.display = 'block';
                        syncBalancesToOverview();
                        fetchOverviewTopContracts();
                    }
                }

                if (updateUrl && window.history) {
                    const currentUrl = new URL(window.location.href);
                    currentUrl.searchParams.delete('guide');
                    if (tab === 'wallet-ops') {
                        let activeSub = 'deposit';
                        const iBtnWithdraw = document.getElementById('innerNavWithdraw');
                        const iBtnHistory = document.getElementById('innerNavHistory');
                        if (iBtnWithdraw && iBtnWithdraw.classList.contains('is-active')) activeSub = 'withdraw';
                        else if (iBtnHistory && iBtnHistory.classList.contains('is-active')) activeSub = 'history';

                        currentUrl.searchParams.set('tab', activeSub);
                        if (activeSub === 'deposit') {
                            currentUrl.searchParams.set('mode', window.getSavedDepositMode() || 'crypto');
                        } else {
                            currentUrl.searchParams.delete('mode');
                        }
                    } else {
                        currentUrl.searchParams.set('tab', tab === 'trading' ? 'trading' : (tab === 'exchange' ? 'exchange' : tab));
                        currentUrl.searchParams.delete('mode');
                    }
                    if (window.location.href !== currentUrl.toString()) {
                        if (window.history.pushState) {
                            window.history.pushState({ tab: tab }, '', currentUrl.toString());
                        }
                    }
                }
                if (typeof window.updateNavDepositButtonVisibility === 'function') {
                    window.updateNavDepositButtonVisibility();
                }
            }
            window.switchMainTab = switchMainTab;

            function updateNavDepositButtonVisibility() {
                const navDepBtn = document.getElementById('navDepositBtn');
                if (!navDepBtn) return;

                const isWalletPath = window.location.pathname.includes('/wallet');
                const urlParams = new URLSearchParams(window.location.search);
                const tabParam = (urlParams.get('tab') || '').toLowerCase();
                const actionParam = (urlParams.get('action') || '').toLowerCase();
                const subtabParam = (urlParams.get('subtab') || '').toLowerCase();

                const opsSection = document.getElementById('viewSectionWalletOps');
                const isOpsVisible = opsSection && opsSection.style.display !== 'none';
                const innerPanelDeposit = document.getElementById('innerPanelDeposit');
                const isDepositPanelVisible = isOpsVisible && innerPanelDeposit && innerPanelDeposit.style.display !== 'none';

                const isDepositTab = isWalletPath && (tabParam === 'deposit' || actionParam === 'deposit' || subtabParam === 'deposit' || isDepositPanelVisible);

                if (isDepositTab) {
                    navDepBtn.style.setProperty('display', 'none', 'important');
                } else {
                    navDepBtn.style.removeProperty('display');
                    navDepBtn.style.setProperty('display', 'inline-flex', 'important');
                }
            }
            window.updateNavDepositButtonVisibility = updateNavDepositButtonVisibility;

            if (btnOverview) btnOverview.addEventListener('click', () => switchMainTab('overview', true));
            if (btnTrading) btnTrading.addEventListener('click', () => switchMainTab('trading', true));
            if (btnWallet) btnWallet.addEventListener('click', () => switchMainTab('wallet', true));

            // Wallet Sub-Nav Inner Switcher Elements
            const innerBtnDeposit = document.getElementById('innerNavDeposit');
            const innerBtnWithdraw = document.getElementById('innerNavWithdraw');
            const innerBtnHistory = document.getElementById('innerNavHistory');

            const innerPanelDeposit = document.getElementById('innerPanelDeposit');
            const innerPanelWithdraw = document.getElementById('innerPanelWithdraw');
            const innerPanelHistory = document.getElementById('innerPanelHistory');

            function switchWalletInnerNav(sub) {
                const iBtnDeposit = document.getElementById('innerNavDeposit') || innerBtnDeposit;
                const iBtnWithdraw = document.getElementById('innerNavWithdraw') || innerBtnWithdraw;
                const iBtnHistory = document.getElementById('innerNavHistory') || innerBtnHistory;

                const iPanelDeposit = document.getElementById('innerPanelDeposit') || innerPanelDeposit;
                const iPanelWithdraw = document.getElementById('innerPanelWithdraw') || innerPanelWithdraw;
                const iPanelHistory = document.getElementById('innerPanelHistory') || innerPanelHistory;

                [iBtnDeposit, iBtnWithdraw, iBtnHistory].forEach(b => b?.classList.remove('is-active'));
                [iPanelDeposit, iPanelWithdraw, iPanelHistory].forEach(p => { if (p) p.style.display = 'none'; });

                if (topBtnDeposit) topBtnDeposit.classList.remove('is-active');
                if (topBtnWithdraw) topBtnWithdraw.classList.remove('is-active');
                if (topBtnHistory) topBtnHistory.classList.remove('is-active');

                if (sub === 'withdraw') {
                    if (iBtnWithdraw) iBtnWithdraw.classList.add('is-active');
                    if (iPanelWithdraw) iPanelWithdraw.style.display = 'block';
                    if (topBtnWithdraw) topBtnWithdraw.classList.add('is-active');
                    const savedWithdrawMode = window.getSavedWithdrawMode() || 'crypto';
                    if (typeof window.setStepWithdrawMode === 'function') {
                        window.setStepWithdrawMode(savedWithdrawMode);
                    }
                    if (window.history && window.history.replaceState) {
                        try {
                            const url = new URL(window.location.href);
                            url.searchParams.set('tab', 'withdraw');
                            url.searchParams.delete('mode');
                            window.history.replaceState(null, '', url.toString());
                        } catch(e) {}
                    }
                    if (typeof window.loadWithdrawalHistory === 'function') {
                        window.loadWithdrawalHistory(1);
                    } else {
                        setTimeout(() => {
                            if (typeof window.loadWithdrawalHistory === 'function') {
                                window.loadWithdrawalHistory(1);
                            }
                        }, 120);
                    }
                } else if (sub === 'history' || sub === 'ledger') {
                    if (iBtnHistory) iBtnHistory.classList.add('is-active');
                    if (iPanelHistory) iPanelHistory.style.display = 'block';
                    if (topBtnHistory) topBtnHistory.classList.add('is-active');
                    if (window.history && window.history.replaceState) {
                        try {
                            const url = new URL(window.location.href);
                            url.searchParams.set('tab', 'history');
                            url.searchParams.delete('mode');
                            window.history.replaceState(null, '', url.toString());
                        } catch(e) {}
                    }
                    const triggerLedger = (retries = 15) => {
                        if (typeof window.loadLedgerHistory === 'function') {
                            window.loadLedgerHistory(1);
                        } else if (retries > 0) {
                            setTimeout(() => triggerLedger(retries - 1), 120);
                        }
                    };
                    triggerLedger();
                } else if (sub === 'deposit') {
                    if (iBtnDeposit) iBtnDeposit.classList.add('is-active');
                    if (iPanelDeposit) iPanelDeposit.style.display = 'block';
                    if (topBtnDeposit) topBtnDeposit.classList.add('is-active');
                    const activeMode = window.getSavedDepositMode() || 'crypto';
                    if (window.history && window.history.replaceState) {
                        try {
                            const url = new URL(window.location.href);
                            url.searchParams.set('tab', 'deposit');
                            url.searchParams.set('mode', activeMode);
                            window.history.replaceState(null, '', url.toString());
                        } catch(e) {}
                    }
                    if (typeof window.setStepDepositMode === 'function') {
                        window.setStepDepositMode(activeMode, true);
                    }
                }
                if (typeof window.updateNavDepositButtonVisibility === 'function') {
                    window.updateNavDepositButtonVisibility();
                }
            }

            window.switchWalletInnerNav = switchWalletInnerNav;

            // Global delegation for header tabs and inner subnav
            document.addEventListener('click', (e) => {
                if (e.target.closest('#tabNavOverview')) {
                    e.preventDefault();
                    switchMainTab('overview', true);
                } else if (e.target.closest('#tabNavTrading')) {
                    e.preventDefault();
                    switchMainTab('trading', true);
                } else if (e.target.closest('#tabNavWallet')) {
                    e.preventDefault();
                    switchMainTab('wallet', true);
                } else if (e.target.closest('#innerNavDeposit')) {
                    e.preventDefault();
                    switchWalletInnerNav('deposit');
                } else if (e.target.closest('#innerNavWithdraw')) {
                    e.preventDefault();
                    switchWalletInnerNav('withdraw');
                } else if (e.target.closest('#innerNavHistory')) {
                    e.preventDefault();
                    switchWalletInnerNav('history');
                }
            });

            if (innerBtnDeposit) innerBtnDeposit.addEventListener('click', () => switchWalletInnerNav('deposit'));
            if (innerBtnWithdraw) innerBtnWithdraw.addEventListener('click', () => switchWalletInnerNav('withdraw'));
            if (innerBtnHistory) innerBtnHistory.addEventListener('click', () => switchWalletInnerNav('history'));

            // URL Query Parameter Routing (?tab=trading, ?tab=wallet, ?tab=withdraw, etc.)
            function handleUrlRouting() {
                const urlParams = new URLSearchParams(window.location.search);
                const guideParam = (urlParams.get('guide') || '').toLowerCase();
                const tabParam = (urlParams.get('tab') || '').toLowerCase();
                const actionParam = (urlParams.get('action') || '').toLowerCase();
                const subtabParam = (urlParams.get('subtab') || '').toLowerCase();
                const shouldCreate = urlParams.get('create') === '1';

                if (guideParam === 'how-to-deposit' || guideParam === 'how_to_deposit') {
                    if (typeof window.openHowToDepositPage === 'function') {
                        window.openHowToDepositPage(false);
                    }
                    return;
                } else if (guideParam === 'demo-trading' || guideParam === 'demo_trading') {
                    if (typeof window.openDemoTradingGuidePage === 'function') {
                        window.openDemoTradingGuidePage(false);
                    }
                    return;
                } else if (guideParam === 'security-guide' || guideParam === 'security_guide' || guideParam === 'security') {
                    if (typeof window.openSecurityGuidePage === 'function') {
                        window.openSecurityGuidePage(false);
                    }
                    return;
                } else if (guideParam === 'why-kryvex' || guideParam === 'why_kryvex' || guideParam === 'why-nexus' || guideParam === 'why_nexus') {
                    if (typeof window.openWhyKryvexGuidePage === 'function') {
                        window.openWhyKryvexGuidePage(false);
                    }
                    return;
                } else {
                    const ht = document.getElementById('viewSectionHowToDeposit');
                    const dt = document.getElementById('viewSectionDemoTrading');
                    const sg = document.getElementById('viewSectionSecurityGuide');
                    const wk = document.getElementById('viewSectionWhyKryvex');
                    if (ht) ht.style.display = 'none';
                    if (dt) dt.style.display = 'none';
                    if (sg) sg.style.display = 'none';
                    if (wk) wk.style.display = 'none';
                }

                if (tabParam === 'trading' || tabParam === 'trading-accounts' || tabParam === 'trading_accounts') {
                    switchMainTab('trading', false);
                    if (shouldCreate) {
                        const triggerCreate = () => {
                            if (typeof window.openBrokerModal === 'function') {
                                window.openBrokerModal({ isCreateAccount: true });
                            } else {
                                const createModal = document.getElementById('createAccountModalBackdrop');
                                if (createModal) {
                                    createModal.hidden = false;
                                    createModal.classList.add('is-open');
                                    createModal.style.display = 'flex';
                                }
                            }
                        };
                        triggerCreate();
                        setTimeout(triggerCreate, 200);
                    }
                } else if (tabParam === 'overview') {
                    switchMainTab('overview', false);
                } else if (tabParam === 'wallet') {
                    if (actionParam === 'deposit' || subtabParam === 'deposit') {
                        switchMainTab('wallet-ops', false);
                        switchWalletInnerNav('deposit');
                    } else if (actionParam === 'withdraw' || subtabParam === 'withdraw') {
                        switchMainTab('wallet-ops', false);
                        switchWalletInnerNav('withdraw');
                    } else if (actionParam === 'history' || subtabParam === 'history') {
                        switchMainTab('wallet-ops', false);
                        switchWalletInnerNav('history');
                    } else {
                        switchMainTab('wallet', false);
                        if (actionParam) {
                            switchWalletInnerNav(actionParam);
                        }
                    }
                } else if (tabParam === 'withdraw' || actionParam === 'withdraw' || subtabParam === 'withdraw') {
                    switchMainTab('wallet-ops', false);
                    switchWalletInnerNav('withdraw');
                    setGeneralWithdrawDefault();
                } else if (tabParam === 'deposit' || actionParam === 'deposit' || subtabParam === 'deposit') {
                    switchMainTab('wallet-ops', false);
                    const currencyParam = (urlParams.get('currency') || urlParams.get('coin') || urlParams.get('asset') || '').toUpperCase();
                    const explicitMode = window.normalizeDepositMode(urlParams.get('mode') || urlParams.get('method') || urlParams.get('type'));
                    const modeParam = explicitMode || (currencyParam === 'INR' ? 'money' : '') || window.getSavedDepositMode() || 'crypto';
                    switchWalletInnerNav('deposit');
                    if (modeParam === 'money') {
                        if (typeof window.setStepDepositMode === 'function') {
                            window.setStepDepositMode('money', false);
                        }
                    } else {
                        if (typeof window.setStepDepositMode === 'function') {
                            window.setStepDepositMode('crypto', false);
                        }
                        if (currencyParam) {
                            if (typeof window.selectStepDepositCurrency === 'function') {
                                window.selectStepDepositCurrency(currencyParam);
                            }
                        } else {
                            if (typeof window.resetStepDepositView === 'function') {
                                window.resetStepDepositView();
                            }
                        }
                    }
                } else if (tabParam === 'history' || tabParam === 'ledger' || actionParam === 'history' || actionParam === 'ledger' || subtabParam === 'history' || window.location.pathname.endsWith('/wallet/history') || window.location.pathname.endsWith('/history')) {
                    switchMainTab('wallet-ops', false);
                    switchWalletInnerNav('history');
                } else if (tabParam === 'transfer' || actionParam === 'transfer') {
                    if (transferModal) {
                        resetAllWalletModalInputs();
                        transferModal.hidden = false;
                        if (typeof window.updateTransferLiveCalculation === 'function') {
                            window.updateTransferLiveCalculation();
                        }
                    }
                } else if (tabParam === 'exchange' || actionParam === 'exchange') {
                    switchMainTab('exchange', false);
                    const assetParam = urlParams.get('asset') || urlParams.get('coin');
                    if (assetParam && assetParam.toUpperCase() !== 'USDT' && assetParam.toUpperCase() !== 'USD' && typeof window.setSwapFromAsset === 'function') {
                        window.setSwapFromAsset(assetParam);
                    } else if (typeof window.resetSwapToDirectMode === 'function') {
                        window.resetSwapToDirectMode();
                    }
                } else {
                    // Default tab is overview
                    switchMainTab('overview', false);
                }
                if (typeof window.updateNavDepositButtonVisibility === 'function') {
                    window.updateNavDepositButtonVisibility();
                }
            }

            window.addEventListener('popstate', () => {
                handleUrlRouting();
                if (typeof window.updateNavDepositButtonVisibility === 'function') {
                    window.updateNavDepositButtonVisibility();
                }
            });

            if (topBtnDeposit) {
                topBtnDeposit.addEventListener('click', (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    const opsSection = document.getElementById('viewSectionWalletOps');
                    const isOpsVisible = opsSection && opsSection.style.display !== 'none';
                    const innerPanelDeposit = document.getElementById('innerPanelDeposit');
                    const isDepositPanelVisible = isOpsVisible && innerPanelDeposit && innerPanelDeposit.style.display !== 'none';

                    if (isDepositPanelVisible) {
                        switchMainTab('wallet-ops', true);
                        switchWalletInnerNav('deposit');
                    } else {
                        if (typeof window.openAddFundsModal === 'function') {
                            window.openAddFundsModal();
                        } else if (typeof window.openDepositModalPopup === 'function') {
                            window.openDepositModalPopup('USDT');
                        }
                    }
                });
            }

            // =========================================================================
            // COMPLETE REAL CRYPTO & INR WITHDRAWAL CONTROLLER
            // =========================================================================
            function setupWithdrawalControls() {
                const netSelect = document.getElementById('withdrawNetworkSelect');
                const addrInput = document.getElementById('withdrawWalletAddress');
                const amountInput = document.querySelector('#withdrawForm input[name="amount"]');
                const withdrawForm = document.getElementById('withdrawForm');
                const inrWithdrawForm = document.getElementById('inrWithdrawForm');
                const availBalText = document.getElementById('withdrawMainAvailBalanceText');
                const assetPill = document.getElementById('withdrawAssetPill');

                const previewAmount = document.getElementById('withdrawPreviewAmount');
                const previewFee = document.getElementById('withdrawPreviewFee');
                const previewCharge = document.getElementById('withdrawPreviewPlatformCharge');
                const previewNet = document.getElementById('withdrawPreviewNet');

                // INR form elements
                const inrAmountInput = document.getElementById('inrWithdrawAmount');
                const inrMaxBtn = document.getElementById('inrWithdrawMaxButton');
                const inrPreviewAmount = document.getElementById('inrWithdrawPreviewAmount');
                const inrPreviewFee = document.getElementById('inrWithdrawPreviewFee');
                const inrPreviewCharge = document.getElementById('inrWithdrawPreviewPlatformCharge');
                const inrPreviewNet = document.getElementById('inrWithdrawPreviewNet');

                // 1. Supported Withdrawal Networks
                const withdrawNetworks = [
                    { code: 'TRC20', name: 'TRON (TRC20)', rule: 'TRON TRC-20 Address (starts with T, 34 characters)', placeholder: 'Paste your TRC20 (T...) address' },
                    { code: 'BEP20', name: 'BNB Smart Chain (BEP20)', rule: 'BSC BEP-20 Address (starts with 0x, 42 characters)', placeholder: 'Paste your BEP20 (0x...) address' },
                    { code: 'ERC20', name: 'Ethereum (ERC20)', rule: 'Ethereum ERC-20 Address (starts with 0x, 42 characters)', placeholder: 'Paste your ERC20 (0x...) address' },
                    { code: 'POLYGON', name: 'Polygon (MATIC)', rule: 'Polygon Address (starts with 0x, 42 characters)', placeholder: 'Paste your Polygon (0x...) address' },
                    { code: 'SOL', name: 'Solana (SOL)', rule: 'Solana base58 Address', placeholder: 'Paste your Solana address' },
                    { code: 'BTC', name: 'Bitcoin (BTC)', rule: 'Bitcoin Native/SegWit Address', placeholder: 'Paste your BTC address' }
                ];

                // Populate Network Select Dropdown
                if (netSelect) {
                    const savedNetwork = localStorage.getItem('kryvex_last_withdraw_net') || 'TRC20';
                    netSelect.innerHTML = withdrawNetworks.map(n => 
                        `<option value="${n.code}" ${n.code === savedNetwork ? 'selected' : ''}>${n.name}</option>`
                    ).join('');

                    netSelect.addEventListener('change', () => {
                        const code = netSelect.value;
                        localStorage.setItem('kryvex_last_withdraw_net', code);
                        updateWithdrawCalculation();
                    });
                    netSelect.dispatchEvent(new Event('change'));
                }

                // Helper: Get user's available balance
                function getUserAvailableBalance() {
                    let bal = 0;
                    const mainBalEl = document.getElementById('demoMainBalance');
                    if (mainBalEl) {
                        let txt = mainBalEl.dataset.realValue || mainBalEl.textContent || '0';
                        txt = txt.replace(/[^0-9.-]/g, '');
                        const parsed = parseFloat(txt);
                        if (!isNaN(parsed) && parsed > 0) bal = parsed;
                    }
                    if (bal <= 0) {
                        const usdtEl = document.getElementById('usdtBalanceDisplay') || document.getElementById('usdBalanceDisplay');
                        if (usdtEl) {
                            let txt = usdtEl.dataset.realValue || usdtEl.textContent || '0';
                            txt = txt.replace(/[^0-9.-]/g, '');
                            const parsed = parseFloat(txt);
                            if (!isNaN(parsed) && parsed > 0) bal = parsed;
                        }
                    }
                    if (bal <= 0 && window.walletDataState && window.walletDataState.wallet) {
                        bal = parseFloat(window.walletDataState.wallet.demo_main_balance || 0);
                    }
                    return bal;
                }

                // Live USDT Calculation Update
                function updateWithdrawCalculation() {
                    const availBal = getUserAvailableBalance();
                    const isUsdtActive = !inrWithdrawForm || inrWithdrawForm.style.display === 'none';

                    if (availBalText) {
                        if (isUsdtActive) {
                            const cw = typeof window.getCryptoWithdrawable === 'function'
                                ? window.getCryptoWithdrawable()
                                : { asset: 'USDT', amount: availBal };
                            const cwText = typeof window.formatWithdrawAssetAmount === 'function'
                                ? window.formatWithdrawAssetAmount(cw.amount, cw.asset)
                                : '$' + cw.amount.toFixed(2);
                            availBalText.textContent = cwText;
                            availBalText.dataset.realValue = cwText;
                            if (assetPill) assetPill.textContent = 'Tether (USDT)';
                        } else {
                            const rate = (window.inrState && window.inrState.usdtInrRate) || 88;
                            const inrBal = typeof window.getInrWithdrawBalance === 'function' ? window.getInrWithdrawBalance() : availBal * rate;
                            availBalText.textContent = '₹' + inrBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                            availBalText.dataset.realValue = '₹' + inrBal.toFixed(2);
                            if (assetPill) assetPill.textContent = 'Indian Rupee (INR)';
                        }
                    }

                    // Sync moneyAvailableText
                    const moneyAvailText = document.getElementById('withdrawMoneyMainAvailBalanceText');
                    if (moneyAvailText) {
                        const rate = (window.inrState && window.inrState.usdtInrRate) || 88;
                        const inrBal = typeof window.getInrWithdrawBalance === 'function' ? window.getInrWithdrawBalance() : availBal * rate;
                        moneyAvailText.textContent = '₹' + inrBal.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                        moneyAvailText.dataset.realValue = '₹' + inrBal.toFixed(2);
                    }

                    // Get Admin Fee Settings
                    const chargesConfig = (window.walletDataState && (window.walletDataState.withdrawal_charges || window.walletDataState.withdrawalCharges)) || {};
                    const feeType = chargesConfig.withdrawal_fee_type || 'percentage';
                    const feeVal = parseFloat(chargesConfig.withdrawal_fee_value) || 0;
                    const chargeType = chargesConfig.platform_charge_type || 'fixed';
                    const chargeVal = parseFloat(chargesConfig.platform_charge_value) || 0;
                    const inrRate = (window.inrState && window.inrState.usdtInrRate) || (window.walletDataState && window.walletDataState.usdt_inr_rate) || 88;

                    const rateLabel = (type, value, symbol, multiplier) => {
                        if (value <= 0) return '(Free)';
                        if (type === 'percentage') return '(' + value + '%)';
                        return '(' + symbol + (value * multiplier).toFixed(2) + ')';
                    };
                    const setLabel = (id, text) => {
                        const el = document.getElementById(id);
                        if (el) el.textContent = text;
                    };
                    setLabel('withdrawFeeRateLabel', rateLabel(feeType, feeVal, '$', 1));
                    setLabel('withdrawPlatformRateLabel', rateLabel(chargeType, chargeVal, '$', 1));
                    setLabel('inrWithdrawFeeRateLabel', rateLabel(feeType, feeVal, '₹', inrRate));
                    setLabel('inrWithdrawPlatformRateLabel', rateLabel(chargeType, chargeVal, '₹', inrRate));

                    // Crypto preview is in units of the selected asset; fixed charges are USD and
                    // converted with the asset price (mirrors DemoWalletService::calculateWithdrawalCharges).
                    const cwAsset = typeof window.getCryptoWithdrawable === 'function'
                        ? window.getCryptoWithdrawable()
                        : { asset: 'USDT', price: 1, isUsd: true };
                    const fmtAsset = (v) => typeof window.formatWithdrawAssetAmount === 'function'
                        ? window.formatWithdrawAssetAmount(v, cwAsset.asset)
                        : '$' + Number(v || 0).toFixed(2);
                    const assetPrice = cwAsset.price > 0 ? cwAsset.price : 1;

                    const amountPrefix = document.querySelector('#withdrawForm .withdraw-input-prefix');
                    if (amountPrefix) amountPrefix.style.display = cwAsset.isUsd ? '' : 'none';
                    if (amountInput) {
                        amountInput.style.paddingLeft = cwAsset.isUsd ? '28px' : '14px';
                        amountInput.placeholder = cwAsset.isUsd ? '0.00' : ('0.00 ' + cwAsset.asset);
                    }

                    const amt = parseFloat(amountInput?.value) || 0;
                    if (amt <= 0) {
                        if (previewAmount) previewAmount.textContent = '--';
                        if (previewFee) previewFee.textContent = '--';
                        if (previewCharge) previewCharge.textContent = '--';
                        if (previewNet) previewNet.textContent = '--';
                    } else {
                        const fee = feeType === 'percentage' ? (amt * (feeVal / 100)) : (feeVal / assetPrice);
                        const platformCharge = chargeType === 'percentage' ? (amt * (chargeVal / 100)) : (chargeVal / assetPrice);
                        const netReceive = Math.max(0, amt - (fee + platformCharge));

                        if (previewAmount) previewAmount.textContent = fmtAsset(amt);
                        if (previewFee) previewFee.textContent = fee > 0 ? ('-' + fmtAsset(fee)) : 'Free';
                        if (previewCharge) previewCharge.textContent = platformCharge > 0 ? ('-' + fmtAsset(platformCharge)) : 'Free';
                        if (previewNet) {
                            previewNet.textContent = cwAsset.isUsd ? (fmtAsset(netReceive) + ' ' + cwAsset.asset) : fmtAsset(netReceive);
                            previewNet.style.color = netReceive > 0 ? '#10b981' : '#f87171';
                        }
                    }

                    // INR preview calculation (mirrors DemoWalletService::calculateInrWithdrawalCharges)
                    const inrAmt = parseFloat(inrAmountInput?.value) || 0;
                    if (inrAmt <= 0) {
                        if (inrPreviewAmount) inrPreviewAmount.textContent = '--';
                        if (inrPreviewFee) inrPreviewFee.textContent = '--';
                        if (inrPreviewCharge) inrPreviewCharge.textContent = '--';
                        if (inrPreviewNet) inrPreviewNet.textContent = '₹0.00';
                    } else {
                        const inrFee = feeType === 'percentage' ? (inrAmt * (feeVal / 100)) : (feeVal * inrRate);
                        const inrCharge = chargeType === 'percentage' ? (inrAmt * (chargeVal / 100)) : (chargeVal * inrRate);
                        const inrNet = Math.max(0, inrAmt - (inrFee + inrCharge));

                        if (inrPreviewAmount) inrPreviewAmount.textContent = '₹' + inrAmt.toFixed(2);
                        if (inrPreviewFee) inrPreviewFee.textContent = inrFee > 0 ? ('-₹' + inrFee.toFixed(2)) : 'Free';
                        if (inrPreviewCharge) inrPreviewCharge.textContent = inrCharge > 0 ? ('-₹' + inrCharge.toFixed(2)) : 'Free';
                        if (inrPreviewNet) {
                            inrPreviewNet.textContent = '₹' + inrNet.toFixed(2);
                            inrPreviewNet.style.color = inrNet > 0 ? '#10b981' : '#f87171';
                        }
                    }
                }
                window.updateWithdrawCalculation = updateWithdrawCalculation;

                if (amountInput) {
                    amountInput.addEventListener('input', updateWithdrawCalculation);
                    amountInput.addEventListener('keyup', updateWithdrawCalculation);
                }
                if (inrAmountInput) {
                    inrAmountInput.addEventListener('input', () => {
                        updateWithdrawCalculation();
                        if (typeof updateWithdrawMoneyStepProgress === 'function') updateWithdrawMoneyStepProgress();
                    });
                    inrAmountInput.addEventListener('keyup', () => {
                        updateWithdrawCalculation();
                        if (typeof updateWithdrawMoneyStepProgress === 'function') updateWithdrawMoneyStepProgress();
                    });
                }

                // Crypto MAX / % buttons are handled in resources/js/pages/wallet.js (fillWithdrawAmount).

                // Quick % and MAX buttons for INR
                if (inrMaxBtn) {
                    inrMaxBtn.addEventListener('click', () => {
                        const bal = getUserAvailableBalance();
                        const rate = (window.inrState && window.inrState.usdtInrRate) || 88;
                        const inrBal = bal * rate;
                        if (inrAmountInput) {
                            inrAmountInput.value = inrBal > 0 ? inrBal.toFixed(2) : '';
                            updateWithdrawCalculation();
                        }
                    });
                }

                document.querySelectorAll('.withdraw-pct-btn[data-inr-pct]').forEach(btn => {
                    btn.addEventListener('click', () => {
                        const pct = parseFloat(btn.getAttribute('data-inr-pct')) || 100;
                        const bal = getUserAvailableBalance();
                        const rate = (window.inrState && window.inrState.usdtInrRate) || 88;
                        const inrBal = (bal * rate) * (pct / 100);
                        if (inrAmountInput) {
                            inrAmountInput.value = inrBal.toFixed(2);
                            updateWithdrawCalculation();
                        }
                    });
                });

                // Crypto form submission is handled once, in resources/js/pages/wallet.js (setupWithdrawForm).

                // Initial calculation
                updateWithdrawCalculation();
                setInterval(updateWithdrawCalculation, 2500);
            }

            function setGeneralWithdrawDefault() {
                activateWithdrawTab(window.getDefaultWithdrawTab());
                if (typeof window.updateWithdrawCalculation === 'function') {
                    window.updateWithdrawCalculation();
                }
            }

            if (topBtnWithdraw) {
                topBtnWithdraw.addEventListener('click', () => {
                    switchMainTab('wallet-ops', true);
                    switchWalletInnerNav('withdraw');
                    setGeneralWithdrawDefault();
                });
            }

            // 3-Dots Action Dropdown Menu Logic (PrimeXBT Style)
            const moreBtn = document.getElementById('topBannerMoreBtn');
            const moreMenu = document.getElementById('topBannerMoreMenu');
            const itemExchange = document.getElementById('menuItemExchange');
            const itemTransferHistory = document.getElementById('menuItemTransferHistory');
            const itemManageAccounts = document.getElementById('menuItemManageAccounts');

            if (moreBtn && moreMenu) {
                moreBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const isOpen = moreMenu.classList.toggle('is-open');
                    moreBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
                });

                document.addEventListener('click', (e) => {
                    if (!moreBtn.contains(e.target) && !moreMenu.contains(e.target)) {
                        moreMenu.classList.remove('is-open');
                        moreBtn.setAttribute('aria-expanded', 'false');
                    }
                });
            }

            if (itemExchange) {
                itemExchange.addEventListener('click', () => {
                    if (moreMenu) moreMenu.classList.remove('is-open');
                    switchMainTab('exchange', true);
                    if (typeof window.resetSwapToDirectMode === 'function') {
                        window.resetSwapToDirectMode();
                    }
                });
            }

            if (itemTransferHistory) {
                itemTransferHistory.addEventListener('click', () => {
                    if (moreMenu) moreMenu.classList.remove('is-open');
                    switchMainTab('wallet-ops', true);
                    switchWalletInnerNav('history');
                });
            }

            if (itemManageAccounts) {
                itemManageAccounts.addEventListener('click', () => {
                    if (moreMenu) moreMenu.classList.remove('is-open');
                    switchMainTab('trading', true);
                });
            }

            // Global Withdraw & History Action Bindings across overview & table links
            document.querySelectorAll('[data-action-withdraw], a[href*="/wallet/withdraw"]').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    e.preventDefault();
                    switchMainTab('wallet-ops', true);
                    switchWalletInnerNav('withdraw');
                    setGeneralWithdrawDefault();
                });
            });

            document.querySelectorAll('[data-action-history]').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    e.preventDefault();
                    switchMainTab('wallet-ops', true);
                    switchWalletInnerNav('history');
                });
            });

            // Withdraw USDT vs INR Tab Pill Switcher logic
            const btnUsdTab = document.getElementById('btnWithdrawUsdPill') || document.getElementById('withdrawTabUsdt');
            const btnInrTab = document.getElementById('btnWithdrawInrPill') || document.getElementById('withdrawTabInr');
            const usdForm = document.getElementById('withdrawForm');
            const inrForm = document.getElementById('inrWithdrawForm');

            function activateWithdrawTab(tab) {
                const assetPill = document.getElementById('withdrawAssetPill');
                const stepModeAvailable = typeof window.setStepWithdrawMode === 'function';
                if (stepModeAvailable) window.setStepWithdrawMode(tab === 'inr' ? 'money' : 'crypto');
                if (tab === 'inr') {
                    if (btnInrTab) btnInrTab.classList.add('is-active');
                    if (btnUsdTab) btnUsdTab.classList.remove('is-active');
                    if (!stepModeAvailable && inrForm) inrForm.style.display = 'block';
                    if (!stepModeAvailable && usdForm) usdForm.style.display = 'none';
                    if (assetPill) assetPill.textContent = 'Indian Rupee (INR)';
                } else {
                    if (btnUsdTab) btnUsdTab.classList.add('is-active');
                    if (btnInrTab) btnInrTab.classList.remove('is-active');
                    if (!stepModeAvailable && usdForm) usdForm.style.display = 'block';
                    if (!stepModeAvailable && inrForm) inrForm.style.display = 'none';
                    if (assetPill) assetPill.textContent = 'Tether (USDT)';
                }
                if (typeof window.updateWithdrawCalculation === 'function') {
                    window.updateWithdrawCalculation();
                }
            }
            window.activateWithdrawTab = activateWithdrawTab;

            if (btnUsdTab && btnInrTab) {
                btnUsdTab.addEventListener('click', () => activateWithdrawTab('usdt'));
                btnInrTab.addEventListener('click', () => activateWithdrawTab('inr'));

                activateWithdrawTab(window.getDefaultWithdrawTab());
            }

            // =========================================================================
            // REAL-TIME WITHDRAWAL HISTORY & LEDGER HISTORY CONTROLLERS
            // =========================================================================
            function getExplorerLink(network, txHash) {
                if (!txHash) return null;
                const net = (network || '').toUpperCase();
                if (net.includes('BEP') || net.includes('BSC') || net.includes('BNB')) return `https://bscscan.com/tx/${txHash}`;
                if (net.includes('TRC') || net.includes('TRON')) return `https://tronscan.org/#/transaction/${txHash}`;
                if (net.includes('POLYGON') || net.includes('MATIC')) return `https://polygonscan.com/tx/${txHash}`;
                if (net.includes('SOL')) return `https://solscan.io/tx/${txHash}`;
                if (net.includes('BTC')) return `https://mempool.space/tx/${txHash}`;
                return `https://etherscan.io/tx/${txHash}`;
            }

            async function loadWithdrawalHistory(page = 1) {
                const list = document.getElementById('withdrawalRequestsList');
                if (!list) return;
                
                try {
                    const token = localStorage.getItem('kryvex_access_token');
                    let user = {};
                    try { user = JSON.parse(localStorage.getItem('kryvex_user') || '{}') || {}; } catch(e) {}
                    const broker = (user.broker_type || 'kryvex').toLowerCase();

                    const res = await fetch(`/api/wallet/withdrawals?page=${page}&broker_type=${broker}`, {
                        headers: {
                            'Accept': 'application/json',
                            'X-Broker-Type': broker,
                            ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                        }
                    });

                    if (!res.ok) {
                        list.innerHTML = '<div class="wallet-empty" style="padding: 24px; text-align: center; color: rgba(255,255,255,0.4);">Unable to load withdrawal requests.</div>';
                        return;
                    }

                    const json = await res.json();
                    const requests = (json.data && json.data.withdrawal_requests) || [];

                    if (!requests.length) {
                        list.innerHTML = '<div class="wallet-empty" style="padding: 24px; text-align: center; color: rgba(255,255,255,0.4);">No withdrawal requests found.</div>';
                        return;
                    }

                    list.innerHTML = requests.map(req => {
                        const statusRaw = String(req.status || 'pending').toLowerCase();
                        const net = (req.network || req.currency || 'USDT').toUpperCase();
                        const isCrypto = ['BTC', 'ETH', 'SOL', 'USDT', 'USDC', 'XRP', 'ADA', 'BNB', 'TRC20', 'BEP20', 'ERC20', 'POLYGON'].includes(net);
                        const curSymbol = isCrypto ? 'USDT' : (req.currency || 'USD');
                        
                        const amt = Number(req.amount || 0);
                        const fee = Number(req.withdraw_fee || 0) + Number(req.platform_charge || 0);
                        const netAmt = Number(req.net_amount || (amt - fee));
                        
                        let badgeClass = 'is-pending';
                        let badgeLabel = 'Pending';
                        if (statusRaw === 'approved' || statusRaw === 'completed' || statusRaw === 'success') {
                            badgeClass = 'is-completed';
                            badgeLabel = 'Completed';
                        } else if (statusRaw === 'rejected' || statusRaw === 'failed') {
                            badgeClass = 'is-rejected';
                            badgeLabel = 'Rejected';
                        }

                        const dateStr = req.created_at ? new Date(req.created_at).toLocaleString() : '--';
                        const noteText = req.admin_note || req.note || '--';
                        const txHash = req.on_chain_tx_hash || '';
                        const explorerUrl = txHash ? getExplorerLink(net, txHash) : null;

                        return `
                            <div class="withdrawal-item" style="display: grid; grid-template-columns: repeat(6, 1fr); padding: 14px 16px; border-bottom: 1px solid rgba(255,255,255,0.06); align-items: center; font-size: 0.86rem;">
                                <div>
                                    <strong style="color: #ffffff; display: block;">${amt.toFixed(4)} ${curSymbol}</strong>
                                    <small style="color: rgba(255,255,255,0.45); font-size: 0.75rem;">${net}</small>
                                </div>
                                <div>
                                    <span style="color: rgba(255,255,255,0.65);">${fee > 0 ? fee.toFixed(4) : '0.00'} ${curSymbol}</span>
                                </div>
                                <div>
                                    <strong style="color: #10b981;">${netAmt.toFixed(4)} ${curSymbol}</strong>
                                </div>
                                <div>
                                    <span class="wh-status-badge ${badgeClass}">${badgeLabel}</span>
                                    ${explorerUrl ? `<a href="${explorerUrl}" target="_blank" rel="noopener noreferrer" style="display: inline-block; margin-left: 6px; color: #3b82f6; font-size: 0.75rem; text-decoration: underline;">View TX ↗</a>` : ''}
                                </div>
                                <div style="color: rgba(255,255,255,0.55); font-size: 0.8rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${noteText}">
                                    ${noteText}
                                </div>
                                <div style="color: rgba(255,255,255,0.5); font-size: 0.8rem;">
                                    ${dateStr}
                                </div>
                            </div>
                        `;
                    }).join('');

                } catch (err) {
                    console.error('loadWithdrawalHistory error:', err);
                    list.innerHTML = '<div class="wallet-empty" style="padding: 24px; text-align: center; color: rgba(255,255,255,0.4);">Error loading withdrawal requests.</div>';
                }
            }
            window.loadWithdrawalHistory = loadWithdrawalHistory;

            async function loadLedgerHistory(page = 1) {
                const body = document.getElementById('walletLedgerBody');
                const cardList = document.getElementById('walletLedgerCardsList');
                if (!body && !cardList) return;

                try {
                    const token = localStorage.getItem('kryvex_access_token');
                    let user = {};
                    try { user = JSON.parse(localStorage.getItem('kryvex_user') || '{}') || {}; } catch(e) {}
                    const broker = (user.broker_type || 'kryvex').toLowerCase();

                    const search = document.getElementById('ledgerSearchInput')?.value || '';
                    const currency = document.getElementById('ledgerCurrencyFilter')?.value || 'all';
                    const type = document.getElementById('ledgerTypeFilter')?.value || 'all';
                    const direction = document.getElementById('ledgerDirectionFilter')?.value || 'all';
                    const fromDate = document.getElementById('ledgerStartDate')?.value || '';
                    const toDate = document.getElementById('ledgerEndDate')?.value || '';

                    const params = new URLSearchParams({
                        page: page,
                        search: search,
                        currency: currency,
                        type: type,
                        direction: direction,
                        from_date: fromDate,
                        to_date: toDate,
                        broker_type: broker
                    });

                    const res = await fetch(`/api/wallet/ledger?${params.toString()}`, {
                        headers: {
                            'Accept': 'application/json',
                            'X-Broker-Type': broker,
                            ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                        }
                    });

                    if (!res.ok) {
                        if (body) body.innerHTML = '<tr><td colspan="5" class="wallet-empty" style="padding: 24px; text-align: center; color: rgba(255,255,255,0.4);">Unable to load ledger.</td></tr>';
                        return;
                    }

                    const json = await res.json();
                    const ledgers = (json.data && json.data.ledger) || [];

                    if (!ledgers.length) {
                        if (body) body.innerHTML = '<tr><td colspan="5" class="wallet-empty" style="padding: 24px; text-align: center; color: rgba(255,255,255,0.4);">No ledger records found.</td></tr>';
                        if (cardList) cardList.innerHTML = '<div class="wallet-empty" style="padding: 24px; text-align: center; color: rgba(255,255,255,0.4);">No ledger records found.</div>';
                        return;
                    }

                    if (body) {
                        body.innerHTML = ledgers.map(row => {
                            const isCredit = row.direction === 'credit';
                            const dirClass = isCredit ? 'text-emerald' : 'text-rose';
                            const dirSign = isCredit ? '+' : '-';
                            const cur = (row.wallet_currency || row.currency || 'USDT').toUpperCase();
                            const isINR = cur === 'INR';
                            const amt = Number(row.amount || 0);
                            const amtText = isINR ? ('₹' + amt.toLocaleString('en-IN', { minimumFractionDigits: 2 })) : (amt.toFixed(4) + ' ' + cur);
                            const dateStr = row.created_at ? new Date(row.created_at).toLocaleString() : '--';
                            const typeName = (row.type || 'Transaction').replace(/_/g, ' ');

                            return `
                                <tr style="border-bottom: 1px solid rgba(255,255,255,0.06);">
                                    <td style="padding: 14px 16px; font-weight: 600; text-transform: capitalize; color: #ffffff;">
                                        ${typeName}
                                        <small style="display: block; color: rgba(255,255,255,0.4); font-size: 0.75rem; font-weight: normal;">${row.note || row.reference || '--'}</small>
                                    </td>
                                    <td style="padding: 14px 16px;">
                                        <span style="font-size: 0.78rem; font-weight: 700; padding: 2px 8px; border-radius: 6px; background: ${isCredit ? 'rgba(16,185,129,0.15)' : 'rgba(244,63,94,0.15)'}; color: ${isCredit ? '#34d399' : '#fb7185'};">
                                            ${(row.direction || '--').toUpperCase()}
                                        </span>
                                    </td>
                                    <td style="padding: 14px 16px; font-weight: 700; color: ${isCredit ? '#34d399' : '#fb7185'};">
                                        ${dirSign}${amtText}
                                    </td>
                                    <td style="padding: 14px 16px;">
                                        <span class="wh-status-badge is-${row.status || 'pending'}">${row.status || 'Completed'}</span>
                                    </td>
                                    <td style="padding: 14px 16px; color: rgba(255,255,255,0.5); font-size: 0.8rem;">
                                        ${dateStr}
                                    </td>
                                </tr>
                            `;
                        }).join('');
                    }

                    if (cardList) {
                        cardList.innerHTML = ledgers.map(row => {
                            const isCredit = row.direction === 'credit';
                            const dirSign = isCredit ? '+' : '-';
                            const cur = (row.wallet_currency || row.currency || 'USDT').toUpperCase();
                            const isINR = cur === 'INR';
                            const amt = Number(row.amount || 0);
                            const amtText = isINR ? ('₹' + amt.toLocaleString('en-IN', { minimumFractionDigits: 2 })) : (amt.toFixed(4) + ' ' + cur);
                            const dateStr = row.created_at ? new Date(row.created_at).toLocaleString() : '--';
                            const typeName = (row.type || 'Transaction').replace(/_/g, ' ');

                            return `
                                <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.07); border-radius: 12px; padding: 14px; margin-bottom: 10px;">
                                    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;">
                                        <strong style="text-transform: capitalize; color: #fff; font-size: 0.9rem;">${typeName}</strong>
                                        <strong style="color: ${isCredit ? '#34d399' : '#fb7185'}; font-size: 0.95rem;">${dirSign}${amtText}</strong>
                                    </div>
                                    <div style="display: flex; justify-content: space-between; align-items: center; font-size: 0.78rem; color: rgba(255,255,255,0.45);">
                                        <span>${dateStr}</span>
                                        <span class="wh-status-badge is-${row.status || 'pending'}">${row.status || 'Completed'}</span>
                                    </div>
                                </div>
                            `;
                        }).join('');
                    }

                } catch (err) {
                    console.error('loadLedgerHistory error:', err);
                    if (body) body.innerHTML = '<tr><td colspan="5" class="wallet-empty" style="padding: 24px; text-align: center; color: rgba(255,255,255,0.4);">Error loading ledger.</td></tr>';
                }
            }
            window.loadLedgerHistory = loadLedgerHistory;

            // Bind Ledger filter events
            ['ledgerSearchInput', 'ledgerCurrencyFilter', 'ledgerTypeFilter', 'ledgerDirectionFilter', 'ledgerStartDate', 'ledgerEndDate'].forEach(id => {
                const el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', () => loadLedgerHistory(1));
                    el.addEventListener('change', () => loadLedgerHistory(1));
                }
            });

            // Initial load of history & controls
            loadWithdrawalHistory(1);
            loadLedgerHistory(1);
            setupWithdrawalControls();

            // Hide empty balances filter logic for Overview table
            const hideEmptyCheck = document.getElementById('hideEmptyBalancesCheck');
            const searchInput = document.getElementById('assetSearchInput');

            function getRowBalance(row) {
                const strong = row.querySelector('td:nth-child(2) strong, td strong');
                if (strong) {
                    let text = strong.dataset.realValue || strong.textContent || strong.innerText || '';
                    if (text && text !== '••••••••') {
                        text = text.replace(/[^0-9.-]/g, '');
                        const val = parseFloat(text);
                        if (!isNaN(val) && val > 0) return val;
                    }
                }
                const attrBal = row.getAttribute('data-asset-balance');
                if (attrBal !== null && attrBal !== undefined && attrBal !== '') {
                    const val = parseFloat(attrBal);
                    if (!isNaN(val)) return val;
                }
                return 0;
            }

            function filterRows() {
                const searchVal = searchInput ? searchInput.value.toLowerCase().trim() : '';
                const hideEmpty = hideEmptyCheck ? hideEmptyCheck.checked : false;

                const rows = document.querySelectorAll('[data-asset-row]');
                rows.forEach(row => {
                    const name = (row.getAttribute('data-asset-name') || '').toLowerCase();
                    const bal = getRowBalance(row);

                    let matchSearch = !searchVal || name.includes(searchVal);
                    let matchEmpty = !hideEmpty || bal > 0;

                    row.style.display = (matchSearch && matchEmpty) ? '' : 'none';
                });
            }

            if (hideEmptyCheck) {
                hideEmptyCheck.addEventListener('change', filterRows);
            }
            if (searchInput) {
                searchInput.addEventListener('input', filterRows);
            }

            window.triggerWalletTableFilter = filterRows;

            // Balance Masking / Eye Toggle Logic
            window.isWalletBalanceHidden = localStorage.getItem('kryvex_hide_wallet_balance') === 'true';

            window.applyBalanceMasking = function() {
                document.querySelectorAll('.balance-eye-open').forEach(el => el.style.display = window.isWalletBalanceHidden ? 'none' : 'inline-block');
                document.querySelectorAll('.balance-eye-closed').forEach(el => el.style.display = window.isWalletBalanceHidden ? 'inline-block' : 'none');

                const eyeOpen = document.getElementById('eyeIconOpen');
                const eyeClosed = document.getElementById('eyeIconClosed');
                if (eyeOpen && eyeClosed) {
                    eyeOpen.style.display = window.isWalletBalanceHidden ? 'none' : 'inline-block';
                    eyeClosed.style.display = window.isWalletBalanceHidden ? 'inline-block' : 'none';
                }

                const sensitiveElems = document.querySelectorAll('[data-sensitive-balance]');
                sensitiveElems.forEach(elem => {
                    if (window.isWalletBalanceHidden) {
                        if (!elem.dataset.realValue && elem.textContent !== '••••••••') {
                            elem.dataset.realValue = elem.textContent || elem.innerText || '';
                        }
                        elem.textContent = '••••••••';
                    } else {
                        if (elem.dataset.realValue) {
                            elem.textContent = elem.dataset.realValue;
                        }
                    }
                });
            };

            window.toggleWalletBalanceVisibility = function() {
                window.isWalletBalanceHidden = !window.isWalletBalanceHidden;
                localStorage.setItem('kryvex_hide_wallet_balance', String(window.isWalletBalanceHidden));
                window.applyBalanceMasking();
            };

            window.toggleSpotlightRow = function() {
                const el = document.getElementById('ovSpotlightRow');
                const btn = document.getElementById('ovSpotlightToggleBtn');
                if (!el) return;

                const isCurrentlyHidden = el.style.display === 'none' || getComputedStyle(el).display === 'none';

                if (isCurrentlyHidden) {
                    el.style.setProperty('display', 'grid', 'important');
                    if (btn) btn.innerHTML = 'Hide Spotlight ↗';
                    localStorage.setItem('kryvex_spotlight_hidden', 'false');
                } else {
                    el.style.setProperty('display', 'none', 'important');
                    if (btn) btn.innerHTML = 'Show Spotlight ↘';
                    localStorage.setItem('kryvex_spotlight_hidden', 'true');
                }
            };

            window.initSpotlightState = function() {
                const el = document.getElementById('ovSpotlightRow');
                const btn = document.getElementById('ovSpotlightToggleBtn');
                if (!el || !btn) return;
                const isHidden = localStorage.getItem('kryvex_spotlight_hidden') === 'true';
                if (isHidden) {
                    el.style.setProperty('display', 'none', 'important');
                    btn.innerHTML = 'Show Spotlight ↘';
                } else {
                    el.style.setProperty('display', 'grid', 'important');
                    btn.innerHTML = 'Hide Spotlight ↗';
                }
            };

            window.castMarketSentiment = function(vote) {
                localStorage.setItem('kryvex_market_sentiment_vote', vote);
                
                let bullCount = parseInt(localStorage.getItem('kryvex_sentiment_bull_count') || '142');
                let bearCount = parseInt(localStorage.getItem('kryvex_sentiment_bear_count') || '67');

                if (vote === 'bullish') {
                    bullCount += 1;
                } else {
                    bearCount += 1;
                }

                localStorage.setItem('kryvex_sentiment_bull_count', bullCount);
                localStorage.setItem('kryvex_sentiment_bear_count', bearCount);

                window.updateSentimentPollUI(vote, bullCount, bearCount);

                if (window.showToast) {
                    window.showToast('success', vote === 'bullish' ? 'Voted Bullish! 🐂' : 'Voted Bearish! 🐻');
                }
            };

            window.resetMarketSentimentVote = function() {
                localStorage.removeItem('kryvex_market_sentiment_vote');
                const btns = document.getElementById('ovSentimentVoteBtns');
                const result = document.getElementById('ovSentimentResultWrap');
                const title = document.getElementById('ovSentimentTitle');
                if (btns) btns.style.display = 'inline-flex';
                if (result) result.style.display = 'none';
                if (title) title.textContent = 'How do you feel about the market today?';
            };

            window.updateSentimentPollUI = function(userVote, bullCount, bearCount) {
                const btns = document.getElementById('ovSentimentVoteBtns');
                const result = document.getElementById('ovSentimentResultWrap');
                const title = document.getElementById('ovSentimentTitle');
                const userBadge = document.getElementById('ovUserVoteBadge');
                const bullPctText = document.getElementById('ovBullishPctText');
                const bearPctText = document.getElementById('ovBearishPctText');
                const progressBar = document.getElementById('ovSentimentProgressBar');

                if (!btns || !result) return;

                const total = bullCount + bearCount;
                const bullPct = Math.round((bullCount / total) * 100);
                const bearPct = 100 - bullPct;

                if (userVote) {
                    btns.style.display = 'none';
                    result.style.display = 'flex';

                    if (title) title.textContent = 'Community Market Sentiment Today';

                    if (bullPctText) bullPctText.textContent = bullPct + '% Bullish';
                    if (bearPctText) bearPctText.textContent = bearPct + '% Bearish';
                    if (progressBar) progressBar.style.width = bullPct + '%';

                    if (userBadge) {
                        if (userVote === 'bullish') {
                            userBadge.textContent = 'Your Vote: Bullish 🐂';
                            userBadge.style.background = 'rgba(16, 185, 129, 0.15)';
                            userBadge.style.color = '#34d399';
                            userBadge.style.borderColor = 'rgba(16, 185, 129, 0.3)';
                        } else {
                            userBadge.textContent = 'Your Vote: Bearish 🐻';
                            userBadge.style.background = 'rgba(239, 68, 68, 0.15)';
                            userBadge.style.color = '#f87171';
                            userBadge.style.borderColor = 'rgba(239, 68, 68, 0.3)';
                        }
                    }
                }
            };

            window.initMarketSentimentPoll = function() {
                const savedVote = localStorage.getItem('kryvex_market_sentiment_vote');
                let bullCount = parseInt(localStorage.getItem('kryvex_sentiment_bull_count') || '142');
                let bearCount = parseInt(localStorage.getItem('kryvex_sentiment_bear_count') || '67');

                if (savedVote) {
                    window.updateSentimentPollUI(savedVote, bullCount, bearCount);
                }
            };

            window.openHowToDepositPage = function(pushState = true) {
                const ov = document.getElementById('viewSectionOverview');
                const ht = document.getElementById('viewSectionHowToDeposit');
                const dt = document.getElementById('viewSectionDemoTrading');
                const sg = document.getElementById('viewSectionSecurityGuide');
                const subnav = document.querySelector('.dharma-subnav');
                if (ov) ov.style.display = 'none';
                if (dt) dt.style.display = 'none';
                if (sg) sg.style.display = 'none';
                if (ht) ht.style.display = 'block';
                if (subnav) subnav.style.display = 'none';
                window.scrollTo({ top: 0, behavior: 'smooth' });

                if (pushState !== false && window.history && window.history.pushState) {
                    const currentUrl = new URL(window.location.href);
                    if (currentUrl.searchParams.get('guide') !== 'how-to-deposit') {
                        currentUrl.searchParams.set('guide', 'how-to-deposit');
                        window.history.pushState({ guide: 'how-to-deposit' }, '', currentUrl.toString());
                    }
                }
            };

            window.closeHowToDepositPage = function() {
                const currentUrl = new URL(window.location.href);
                if (currentUrl.searchParams.has('guide')) {
                    window.history.back();
                } else {
                    const ov = document.getElementById('viewSectionOverview');
                    const ht = document.getElementById('viewSectionHowToDeposit');
                    const dt = document.getElementById('viewSectionDemoTrading');
                    const sg = document.getElementById('viewSectionSecurityGuide');
                    const subnav = document.querySelector('.dharma-subnav');
                    if (ht) ht.style.display = 'none';
                    if (dt) dt.style.display = 'none';
                    if (sg) sg.style.display = 'none';
                    if (ov) ov.style.display = 'block';
                    if (subnav) subnav.style.display = 'flex';
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                }
            };

            window.activateDemoSidebarNav = function(secId, event) {
                if (event) {
                    event.preventDefault();
                }
                const sec = document.getElementById(secId);
                if (sec) {
                    sec.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
                
                document.querySelectorAll('#demoSidebarNavList .demo-nav-link').forEach(link => {
                    if (link.getAttribute('data-sec') === secId) {
                        link.classList.add('is-active');
                    } else {
                        link.classList.remove('is-active');
                    }
                });
            };

            function initDemoSidebarScrollSpy() {
                if (window.demoScrollSpyInitialized) return;
                window.demoScrollSpyInitialized = true;

                const sections = ['demo-sec-what', 'demo-sec-why', 'demo-sec-where', 'demo-sec-how', 'demo-sec-balance', 'demo-sec-live', 'demo-sec-faq'];
                
                window.addEventListener('scroll', () => {
                    const dt = document.getElementById('viewSectionDemoTrading');
                    if (!dt || dt.style.display === 'none') return;

                    let currentSec = 'demo-sec-what';
                    const scrollPos = window.scrollY + 140;

                    sections.forEach(id => {
                        const el = document.getElementById(id);
                        if (el) {
                            const top = el.offsetTop;
                            if (scrollPos >= top) {
                                currentSec = id;
                            }
                        }
                    });

                    document.querySelectorAll('#demoSidebarNavList .demo-nav-link').forEach(link => {
                        if (link.getAttribute('data-sec') === currentSec) {
                            link.classList.add('is-active');
                        } else {
                            link.classList.remove('is-active');
                        }
                    });
                });
            }

            window.openDemoTradingGuidePage = function(pushState = true) {
                const ov = document.getElementById('viewSectionOverview');
                const ht = document.getElementById('viewSectionHowToDeposit');
                const dt = document.getElementById('viewSectionDemoTrading');
                const sg = document.getElementById('viewSectionSecurityGuide');
                const subnav = document.querySelector('.dharma-subnav');
                if (ov) ov.style.display = 'none';
                if (ht) ht.style.display = 'none';
                if (sg) sg.style.display = 'none';
                if (dt) dt.style.display = 'block';
                if (subnav) subnav.style.display = 'none';
                window.scrollTo({ top: 0, behavior: 'smooth' });
                initDemoSidebarScrollSpy();

                if (pushState !== false && window.history && window.history.pushState) {
                    const currentUrl = new URL(window.location.href);
                    if (currentUrl.searchParams.get('guide') !== 'demo-trading') {
                        currentUrl.searchParams.set('guide', 'demo-trading');
                        window.history.pushState({ guide: 'demo-trading' }, '', currentUrl.toString());
                    }
                }
            };

            window.closeDemoTradingGuidePage = function() {
                const currentUrl = new URL(window.location.href);
                if (currentUrl.searchParams.has('guide')) {
                    window.history.back();
                } else {
                    const ov = document.getElementById('viewSectionOverview');
                    const ht = document.getElementById('viewSectionHowToDeposit');
                    const dt = document.getElementById('viewSectionDemoTrading');
                    const sg = document.getElementById('viewSectionSecurityGuide');
                    const subnav = document.querySelector('.dharma-subnav');
                    if (dt) dt.style.display = 'none';
                    if (ht) ht.style.display = 'none';
                    if (sg) sg.style.display = 'none';
                    if (ov) ov.style.display = 'block';
                    if (subnav) subnav.style.display = 'flex';
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                }
