            window.updateOverviewRealizedPnl = async function() {
                const pnlEl = document.getElementById('ov30dPnlVal');
                const countEl = document.getElementById('ov30dClosedTradesCount');
                if (!pnlEl && !countEl) return;

                let accounts = [];
                try { accounts = window.__cachedTradingAccounts || JSON.parse(localStorage.getItem('kryvex_cached_trading_accounts') || '[]') || []; } catch (e) {}
                const activeUid = localStorage.getItem('kryvex_active_account_uid') || '';
                const acc = accounts.find(a => a.account_uid === activeUid) || accounts.find(a => a.is_default) || null;
                const accountUid = acc ? acc.account_uid : activeUid;
                if (!accountUid) return;

                const broker = String(acc?.broker_type || 'kryvex').toLowerCase();
                const isCent = broker === 'mt5' && (acc?.is_cent || String(acc?.plan_key || '').toLowerCase() === 'cent' || acc?.account_currency === 'USC');

                try {
                    const token = localStorage.getItem('kryvex_access_token') || '';
                    const res = await fetch('/api/futures/realized-pnl?days=30&account_uid=' + encodeURIComponent(accountUid), {
                        headers: { 'Accept': 'application/json', ...(token ? { 'Authorization': 'Bearer ' + token } : {}) }
                    });
                    if (!res.ok) return;
                    const json = await res.json();
                    const data = json && json.data ? json.data : null;
                    if (!data) return;

                    const pnlUsd = Number(data.realized_pnl || 0);
                    const sign = pnlUsd >= 0 ? '+' : '-';
                    const abs = Math.abs(isCent ? pnlUsd * 100 : pnlUsd)
                        .toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                    if (pnlEl) {
                        pnlEl.textContent = `${sign}${abs} ${isCent ? 'USC' : 'USD'}`;
                        pnlEl.style.color = pnlUsd >= 0 ? '#34d399' : '#ef4444';
                    }
                    if (countEl) countEl.textContent = String(data.closed_count || 0);
                } catch (e) {
                    console.warn('Could not update 30d realized PnL:', e);
                }
            };
            window.addEventListener('kryvex_trading_accounts_loaded', () => window.updateOverviewRealizedPnl());

            /* TOP MOVERS LIVE DATA & TAB TOGGLE HANDLERS */
