            function getCoinColor(symbol) {
                const colors = {
                    'BTC': '#f7931a', 'ETH': '#627eea', 'SOL': '#14f195', 'XRP': '#23292f',
                    'BNB': '#f3ba2f', 'ADA': '#0033ad', 'DOGE': '#c2a633', 'AVAX': '#e84142',
                    'DOT': '#e6007a', 'NEAR': '#000000', 'APT': '#3b82f6', 'LINK': '#375bd2',
                    'PEPE': '#55ac56', 'SHIB': '#ffa409', 'LTC': '#345d9d', 'BCH': '#8dc351',
                    'XAU': '#d4af37', 'OP': '#ff0420', 'POL': '#8247e5', 'ATOM': '#2e3148'
                };
                return colors[symbol] || '#7c3aed';
            }

