            function renderTopMovers() {
                const container = document.getElementById('topMoversContainer');
                if (!container) return;

                if (!cachedMoversTickers || cachedMoversTickers.length === 0) {
                    container.innerHTML = `<div style="grid-column: 1 / -1; text-align: center; color: rgba(255,255,255,0.4); padding: 20px; font-size: 0.85rem;">Loading live movers...</div>`;
                    return;
                }

                let filtered = [...cachedMoversTickers];

                if (topMoversActiveTab === 'bullish') {
                    // Strictly ONLY positive tickers (>= 0%)
                    filtered = filtered.filter(item => (item.price_change_percent || 0) >= 0);
                    filtered.sort((a, b) => (b.price_change_percent || 0) - (a.price_change_percent || 0));
                } else {
                    // Strictly ONLY negative tickers (< 0%)
                    filtered = filtered.filter(item => (item.price_change_percent || 0) < 0);
                    filtered.sort((a, b) => (a.price_change_percent || 0) - (b.price_change_percent || 0));
                }

                const top8 = filtered.slice(0, 8);

                if (top8.length === 0) {
                    const label = topMoversActiveTab === 'bullish' ? 'bullish (gaining)' : 'bearish (losing)';
                    container.innerHTML = `<div style="grid-column: 1 / -1; text-align: center; color: rgba(255,255,255,0.4); padding: 20px; font-size: 0.85rem;">No ${label} movers at this moment</div>`;
                    return;
                }

                container.innerHTML = top8.map(item => {
                    const rawSym = (item.symbol || '').replace('USDT', '').replace('USD', '');
                    const sym = rawSym || 'CRYPTO';
                    const pct = item.price_change_percent || 0;
                    const isUp = pct >= 0;
                    const pctColor = isUp ? '#10b981' : '#ef4444';
                    const arrow = isUp ? '↑' : '↓';
                    const price = item.last_price > 10 ? item.last_price.toFixed(2) : (item.last_price > 1 ? item.last_price.toFixed(3) : item.last_price.toFixed(5));
                    const bgColor = getCoinColor(sym);
                    const firstLetter = sym.charAt(0);
                    const logoUrl = getCoinLogoUrl(sym);

                    return `
                        <div style="background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 10px; padding: 6px 10px; display: flex; align-items: center; justify-content: space-between; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.06)';" onmouseout="this.style.background='rgba(255,255,255,0.03)';">
                            <div style="display: flex; align-items: center; gap: 8px;">
                                <div style="width: 22px; height: 22px; border-radius: 50%; overflow: hidden; background: #0f172a; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; border: 1px solid rgba(255,255,255,0.15);">
                                    <img src="${logoUrl}" alt="${sym}" style="width: 100%; height: 100%; object-fit: cover; display: block;" onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='inline-flex';" />
                                    <span style="display: none; width: 100%; height: 100%; border-radius: 50%; background: ${bgColor}; color: #ffffff; font-size: 0.68rem; font-weight: 800; align-items: center; justify-content: center;">${firstLetter}</span>
                                </div>
                                <span style="font-size: 0.82rem; font-weight: 700; color: #ffffff;">${sym}</span>
                            </div>
                            <div style="text-align: right;">
                                <span style="font-size: 0.80rem; font-weight: 700; color: ${pctColor}; display: block; line-height: 1.1;">${arrow} ${Math.abs(pct).toFixed(2)}%</span>
                                <span style="font-size: 0.70rem; color: rgba(255, 255, 255, 0.5); display: block; line-height: 1.1;">Last ${price}</span>
                            </div>
                        </div>
                    `;
                }).join('');
            }

            window.fetchTopMoversData = async function() {
                try {
                    const res = await fetch('/api/markets/futures/tickers');
                    if (res.ok) {
                        const data = await res.json();
                        if (data && Array.isArray(data.data) && data.data.length > 0) {
                            cachedMoversTickers = data.data;
                            renderTopMovers();
                        }
                    }
                } catch(e) {
                    console.warn('Failed to fetch top movers live tickers:', e);
                }
            };

            // Immediate render on script parse
            setTimeout(() => {
                if (typeof renderTopMovers === 'function') renderTopMovers();
                if (typeof window.fetchTopMoversData === 'function') window.fetchTopMoversData();
            }, 0);

            document.addEventListener('DOMContentLoaded', () => {
                const vipModalBackdrop = document.getElementById('vipTiersModalBackdrop');
                if (vipModalBackdrop) {
                    vipModalBackdrop.addEventListener('click', (e) => {
                        if (!e.target.closest('.dharma-modal-card')) {
                            closeVipTiersModal();
                        }
                    });
                }

                document.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') {
                        closeVipTiersModal();
                    }
                });

                if (typeof window.updateOverviewRealizedPnl === 'function') {
                    window.updateOverviewRealizedPnl();
                }

                if (typeof renderTopMovers === 'function') {
                    renderTopMovers();
