            async function fetchLiveFxEmpireNews() {
                try {
                    const response = await fetch('/api/markets/fxempire-news');
                    if (!response.ok) return;
                    const data = await response.json();
                    if (data.success) {
                        const seenResearch = new Set();
                        let resList = (data.research || []).filter(item => {
                            const norm = (item.title || '').trim().toLowerCase();
                            if (seenResearch.has(norm)) return false;
                            seenResearch.add(norm);
                            return true;
                        });

                        const seenNews = new Set();
                        let newsList = (data.news || []).filter(item => {
                            const norm = (item.title || '').trim().toLowerCase();
                            if (seenResearch.has(norm) || seenNews.has(norm)) return false;
                            seenNews.add(norm);
                            return true;
                        });

                        resList.sort((a, b) => (Number(b.timestamp) || 0) - (Number(a.timestamp) || 0));
                        newsList.sort((a, b) => (Number(b.timestamp) || 0) - (Number(a.timestamp) || 0));

                        resList = resList.slice(0, 4);
                        newsList = newsList.slice(0, 4);

                        if (resList.length > 0) {
                            const researchContainer = document.getElementById('ovMarketResearchList');
                            if (researchContainer) {
                                researchContainer.innerHTML = resList.map((item, idx) => `
                                    <a href="/research?id=${item.id || ('res-' + (idx + 1))}" style="background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 12px; padding: 10px 14px; display: flex; align-items: center; justify-content: space-between; gap: 12px; text-decoration: none; transition: all 0.2s ease; width: 100%; box-sizing: border-box;" onmouseover="this.style.borderColor='rgba(139, 92, 246, 0.4)';" onmouseout="this.style.borderColor='rgba(255, 255, 255, 0.06)';">
                                        <div style="display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0;">
                                            <div style="width: 52px; height: 44px; border-radius: 8px; overflow: hidden; flex-shrink: 0; background: #1f2937;">
                                                <img src="${item.image}" alt="Thumbnail" style="width: 100%; height: 100%; object-fit: cover;" onerror="this.onerror=null; this.src='https://responsive.fxempire.com/v7/_fxempire_/2026/10/gold-precious-metal-price-chart-19.jpg';">
                                            </div>
                                            <div style="flex: 1; min-width: 0;">
                                                <div style="font-size: 0.72rem; color: rgba(255, 255, 255, 0.5); font-weight: 600; margin-bottom: 2px;">${item.category} | ${item.date}</div>
                                                <h4 style="font-size: 0.84rem; font-weight: 700; color: #ffffff; margin: 0 0 2px 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.title}</h4>
                                                <p style="font-size: 0.72rem; color: rgba(255, 255, 255, 0.5); margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.description}</p>
                                            </div>
                                        </div>
                                        <span style="color: rgba(255, 255, 255, 0.4); font-size: 0.84rem; flex-shrink: 0;">&gt;</span>
                                    </a>
                                `).join('');
                            }
                        }

                        if (newsList.length > 0) {
                            const newsContainer = document.getElementById('ovLiveNewsList');
                            if (newsContainer) {
                                newsContainer.innerHTML = newsList.map((item, idx) => `
                                    <a href="/news?id=${item.id || ('news-' + (idx + 1))}" style="background: rgba(255, 255, 255, 0.03); border: 1px solid rgba(255, 255, 255, 0.06); border-radius: 12px; padding: 10px 14px; display: flex; align-items: center; justify-content: space-between; gap: 12px; text-decoration: none; transition: all 0.2s ease; width: 100%; box-sizing: border-box;" onmouseover="this.style.borderColor='rgba(59, 130, 246, 0.4)';" onmouseout="this.style.borderColor='rgba(255, 255, 255, 0.06)';">
                                        <div style="display: flex; align-items: center; gap: 12px; flex: 1; min-width: 0;">
                                            <div style="width: 52px; height: 44px; border-radius: 8px; overflow: hidden; flex-shrink: 0; background: #1f2937;">
                                                <img src="${item.image}" alt="Thumbnail" style="width: 100%; height: 100%; object-fit: cover;" onerror="this.onerror=null; this.src='https://cdn.sanity.io/images/s3y3vcno/production/b776ce97c32e7c01879339ea0ece5eedd0c358cf-1510x856.png';">
                                            </div>
                                            <div style="flex: 1; min-width: 0;">
                                                <div style="font-size: 0.72rem; color: rgba(255, 255, 255, 0.5); font-weight: 600; margin-bottom: 2px;">${item.category} &bull; <span style="color: #60a5fa; font-weight: 700;">${item.source || 'News'}</span> | ${item.date}</div>
                                                <h4 style="font-size: 0.84rem; font-weight: 700; color: #ffffff; margin: 0 0 2px 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.title}</h4>
                                                <p style="font-size: 0.72rem; color: rgba(255, 255, 255, 0.5); margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.description}</p>
                                            </div>
                                        </div>
                                        <span style="color: rgba(255, 255, 255, 0.4); font-size: 0.84rem; flex-shrink: 0;">&gt;</span>
