            function generateUpcomingEventsList() {
                const nowSec = Math.floor(Date.now() / 1000);
                const mockList = [
                    { offset: 3600 * 3.5, time: '14:00', flag: '🇺🇸', currency: 'USD', title: 'FOMC Member Waller Speaks', impact: 'Medium' },
                    { offset: 3600 * 5.0, time: '15:00', flag: '🇯🇵', currency: 'JPY', title: 'BOJ Summary of Opinions', impact: 'Medium' },
                    { offset: 3600 * 7.5, time: '17:30', flag: '🇪🇺', currency: 'EUR', title: 'ECB Press Conference', impact: 'High' },
                    { offset: 3600 * 9.5, time: '19:30', flag: '🇨🇦', currency: 'CAD', title: 'Ivey PMI (Sep)', impact: 'Medium' },
                    { offset: 3600 * 11.5, time: '21:30', flag: '🇺🇸', currency: 'USD', title: 'Core CPI (MoM)', impact: 'High' },
                    { offset: 86400 * 1.2 + 3600 * 11, time: '11:00', flag: '🇪🇺', currency: 'EUR', title: 'German ZEW Economic Sentiment', impact: 'Low' },
                    { offset: 86400 * 1.2 + 3600 * 16.5, time: '16:30', flag: '🇦🇺', currency: 'AUD', title: 'RBA Rate Statement', impact: 'Medium' },
                    { offset: 86400 * 1.2 + 3600 * 18, time: '18:00', flag: '🇺🇸', currency: 'USD', title: 'Unemployment Claims', impact: 'Low' },
                    { offset: 86400 * 1.2 + 3600 * 18.5, time: '18:30', flag: '🇺🇸', currency: 'USD', title: 'Non-Farm Employment Change', impact: 'High' },
                    { offset: 86400 * 1.2 + 3600 * 19.5, time: '19:30', flag: '🇺🇸', currency: 'USD', title: 'Crude Oil Inventories', impact: 'Low' }
                ];

                return mockList.map(item => {
                    const ts = nowSec + Math.floor(item.offset);
                    const d = new Date(ts * 1000);
                    const dateStr = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
                    return {
                        timestamp: ts,
                        date: dateStr,
                        time: item.time,
                        flag: item.flag,
                        currency: item.currency,
                        title: item.title,
                        impact: item.impact,
                        link: 'https://www.forexfactory.com/calendar'
                    };
                });
            }

            window.allUpcomingEventsData = generateUpcomingEventsList();

            window.currentUpcomingImpactFilter = 'all';

            async function fetchLiveUpcomingEvents() {
                try {
                    const response = await fetch('/api/markets/upcoming-events');
                    if (response.ok) {
                        const data = await response.json();
                        if (data.success && data.data && data.data.length > 0) {
                            const nowTs = Math.floor(Date.now() / 1000);
                            const futureOnly = data.data.filter(ev => Number(ev.timestamp) >= nowTs);
                            if (futureOnly.length > 0) {
                                window.allUpcomingEventsData = futureOnly;
                            }
                        }
                    }
                } catch (err) {
                    console.error('Error fetching live Forex Factory upcoming events:', err);
                } finally {
                    if (window.filterUpcomingEvents) {
                        window.filterUpcomingEvents(window.currentUpcomingImpactFilter || 'all');
                    }
                }
            }

            function getCountryBadgeCode(ev) {
                if (ev.country) return String(ev.country).toUpperCase();
                if (ev.currency) {
                    const cur = String(ev.currency).toUpperCase();
                    if (cur === 'USD') return 'US';
                    if (cur === 'GBP') return 'GB';
                    if (cur === 'EUR') return 'EU';
                    if (cur === 'CAD') return 'CA';
                    if (cur === 'JPY') return 'JP';
                    if (cur === 'AUD') return 'AU';
                    if (cur === 'CHF') return 'CH';
                    if (cur === 'NZD') return 'NZ';
                    if (cur === 'CNY') return 'CN';
                }

                const flag = String(ev.flag || '');
                if (flag.includes('🇺🇸') || flag.toLowerCase().includes('us')) return 'US';
                if (flag.includes('🇬🇧') || flag.toLowerCase().includes('gb') || flag.toLowerCase().includes('uk')) return 'GB';
                if (flag.includes('🇪🇺') || flag.toLowerCase().includes('eu')) return 'EU';
                if (flag.includes('🇨🇦') || flag.toLowerCase().includes('ca')) return 'CA';
                if (flag.includes('🇯🇵') || flag.toLowerCase().includes('jp')) return 'JP';
                if (flag.includes('🇦🇺') || flag.toLowerCase().includes('au')) return 'AU';
                if (flag.includes('🇨🇭') || flag.toLowerCase().includes('ch')) return 'CH';
                if (flag.includes('🇳ℤ') || flag.toLowerCase().includes('nz')) return 'NZ';
                if (flag.includes('🇨🇳') || flag.toLowerCase().includes('cn')) return 'CN';

                const title = String(ev.title || '').toLowerCase();
                if (title.includes('fomc') || title.includes('cpi') || title.includes('nfp') || title.includes('fed') || title.includes('unemployment')) return 'US';
                if (title.includes('boe') || title.includes('uk') || title.includes('britain')) return 'GB';
                if (title.includes('ecb') || title.includes('euro') || title.includes('germany')) return 'EU';
                if (title.includes('boj') || title.includes('japan') || title.includes('yen')) return 'JP';
                if (title.includes('rba') || title.includes('australia')) return 'AU';
                if (title.includes('ivey') || title.includes('canada')) return 'CA';

                const clean = flag.replace(/[\uD83C-\uDBFF\uDC00-\uDFFF]/g, '').trim();
                return clean ? clean.toUpperCase().substring(0, 2) : 'US';
            }

            function renderUpcomingImpactTriangles(impact) {
                const imp = (impact || 'medium').toLowerCase();
                if (imp === 'high') {
                    return `<span style="letter-spacing: -2px; font-size: 0.72rem; display: block;"><span style="color: #ef4444;">▼</span><span style="color: #ef4444;">▼</span><span style="color: #ef4444;">▼</span></span>`;
                } else if (imp === 'medium') {
                    return `<span style="letter-spacing: -2px; font-size: 0.72rem; display: block;"><span style="color: #f59e0b;">▼</span><span style="color: #f59e0b;">▼</span><span style="color: rgba(255, 255, 255, 0.2);">▼</span></span>`;
                } else {
                    return `<span style="letter-spacing: -2px; font-size: 0.72rem; display: block;"><span style="color: #9ca3af;">▼</span><span style="color: rgba(255, 255, 255, 0.2);">▼</span><span style="color: rgba(255, 255, 255, 0.2);">▼</span></span>`;
                }
            }

            function renderUpcomingEventsRows(events) {
                const container = document.getElementById('ovUpcomingEventsListRows');
                if (!container) return;

                const nowTs = Math.floor(Date.now() / 1000);
                // STRICTLY ONLY FUTURE / PENDING EVENTS:
                const upcoming = (events || []).filter(ev => {
                    if (ev.timestamp) {
                        return Number(ev.timestamp) >= nowTs;
                    }
                    if (ev.date && ev.time) {
                        try {
                            const currentYear = new Date().getFullYear();
                            const parsedMs = Date.parse(`${ev.date}, ${currentYear} ${ev.time}`);
                            if (!isNaN(parsedMs)) {
                                return Math.floor(parsedMs / 1000) >= nowTs;
                            }
                        } catch(e) {}
                    }
                    return true;
                });

                // Sort chronologically ascending (earliest upcoming event first)
                upcoming.sort((a, b) => (Number(a.timestamp) || 0) - (Number(b.timestamp) || 0));

                const top5 = upcoming.slice(0, 5);

                if (!top5 || top5.length === 0) {
                    container.innerHTML = '<div style="padding: 16px; text-align: center; color: rgba(255,255,255,0.5); font-size: 0.82rem;">No upcoming events found for this filter.</div>';
                    return;
                }

                container.innerHTML = top5.map(ev => {
                    const impLower = (ev.impact || '').toLowerCase();
                    const textColor = impLower === 'low' ? '#9ca3af' : (impLower === 'high' ? '#ef4444' : '#f59e0b');
                    const badgeCode = getCountryBadgeCode(ev);
                    const codeLower = badgeCode.toLowerCase();
                    return `
                        <a href="{{ url('/calendar') }}" style="display: grid; grid-template-columns: 80px 1fr 90px; gap: 10px; align-items: center; font-size: 0.80rem; text-decoration: none; padding: 4px 6px; border-radius: 8px; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.04)';" onmouseout="this.style.background='transparent';">
                            <div style="color: #ffffff; font-weight: 600; line-height: 1.2;">
                                <span>${ev.date}</span>
                                <span style="display: block; font-size: 0.72rem; color: rgba(255,255,255,0.5);">${ev.time}</span>
                            </div>
                            <div style="display: flex; align-items: center; gap: 8px; color: #ffffff; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
                                <span style="width: 22px; height: 22px; border-radius: 50%; overflow: hidden; flex-shrink: 0; background: rgba(255, 255, 255, 0.12); border: 1px solid rgba(255, 255, 255, 0.22); display: inline-flex; align-items: center; justify-content: center;">
                                    <img src="https://flagcdn.com/w40/${codeLower}.png" alt="${badgeCode}" style="width: 100%; height: 100%; object-fit: cover; border-radius: 50%;" onerror="this.style.display='none'; this.nextElementSibling.style.display='inline';">
                                    <span style="display: none; font-size: 0.64rem; font-weight: 800; color: #ffffff; text-transform: uppercase;">${badgeCode}</span>
                                </span>
                                <span style="overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${ev.title}</span>
                            </div>
                            <div style="text-align: right;">
                                ${renderUpcomingImpactTriangles(ev.impact)}
                                <span style="color: ${textColor}; font-size: 0.76rem; font-weight: 700;">${ev.impact}</span>
                            </div>
                        </a>
                    `;
                }).join('');
            }

            window.filterUpcomingEvents = function(impactType) {
                window.currentUpcomingImpactFilter = impactType;

                document.querySelectorAll('.ff-impact-pill').forEach(pill => {
                    const filterVal = pill.getAttribute('data-filter');
                    if (filterVal === impactType) {
                        if (impactType === 'high') {
                            pill.style.background = 'rgba(239, 68, 68, 0.25)';
                            pill.style.color = '#ef4444';
                            pill.style.border = '1px solid rgba(239, 68, 68, 0.4)';
                        } else if (impactType === 'medium') {
                            pill.style.background = 'rgba(245, 158, 11, 0.25)';
                            pill.style.color = '#f59e0b';
                            pill.style.border = '1px solid rgba(245, 158, 11, 0.4)';
                        } else if (impactType === 'low') {
                            pill.style.background = 'rgba(156, 163, 175, 0.25)';
                            pill.style.color = '#9ca3af';
                            pill.style.border = '1px solid rgba(156, 163, 175, 0.4)';
                        } else {
                            pill.style.background = 'rgba(255, 255, 255, 0.16)';
                            pill.style.color = '#ffffff';
                            pill.style.border = '1px solid rgba(255, 255, 255, 0.25)';
                        }
                        pill.style.fontWeight = '700';
                    } else {
                        pill.style.background = 'rgba(255, 255, 255, 0.04)';
                        pill.style.color = 'rgba(255, 255, 255, 0.7)';
                        pill.style.border = 'none';
                        pill.style.fontWeight = '600';
                    }
                });

                const data = window.allUpcomingEventsData || [];
                if (impactType === 'all') {
                    renderUpcomingEventsRows(data);
                } else {
                    const filtered = data.filter(item => (item.impact || '').toLowerCase() === impactType.toLowerCase());
                    renderUpcomingEventsRows(filtered);
                }
            };

            function initUpcomingEventsLogic() {
                setTimeout(window.applyBalanceMasking, 100);
                if (window.initSpotlightState) window.initSpotlightState();
                if (window.initMarketSentimentPoll) window.initMarketSentimentPoll();
                if (window.filterUpcomingEvents) window.filterUpcomingEvents('all');
                fetchLiveFxEmpireNews();
                fetchLiveUpcomingEvents();
            }

            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', initUpcomingEventsLogic);
