            function getCoinInfo(sym) {
                if (!sym) return null;
                const upper = sym.toUpperCase();
                if (upper === 'USDT' || upper === 'USD') return USDT_ASSET;
                return SWAP_CRYPTO_COINS.find(c => c.symbol === upper) || { symbol: upper, name: upper, icon: `https://assets.coincap.io/assets/icons/${upper.toLowerCase()}@2x.png` };
            }

            function isExchangeLiveMode() {
                if (typeof window.isCurrentAccountLive === 'function') {
                    return window.isCurrentAccountLive();
                }
                if (window.latestWalletBalances && typeof window.latestWalletBalances.is_live === 'boolean') {
                    return window.latestWalletBalances.is_live;
                }
                const activeMode = window.getActiveTradingMode ? window.getActiveTradingMode() : (localStorage.getItem('kryvex_trading_mode') || 'demo');
                return activeMode === 'live';
            }

            function getSwapCoinBalance(symbol) {
                if (!symbol) return 0;
                // STRICT CHECK: Exchange only works for real funds.
                // In demo mode, NEVER fetch or return demo balances (always 0)
                if (!isExchangeLiveMode()) {
                    return 0;
                }

                const sym = symbol.toUpperCase();

                // 1. Direct check in latestWalletBalances.real_crypto (REAL balances)
                if (window.latestWalletBalances && window.latestWalletBalances.real_crypto && window.latestWalletBalances.real_crypto[sym] !== undefined) {
                    return Number(window.latestWalletBalances.real_crypto[sym]) || 0;
                }
                if (window.latestWalletBalances && window.latestWalletBalances.crypto && window.latestWalletBalances.crypto[sym] !== undefined) {
                    return Number(window.latestWalletBalances.crypto[sym]) || 0;
                }

                if (sym === 'USD' || sym === 'USDT') {
                    if (window.latestWalletBalances?.real_main_balance !== undefined) {
                        return Number(window.latestWalletBalances.real_main_balance) || 0;
                    }
                    if (window.latestWalletBalances?.usdt !== undefined) {
                        return Number(window.latestWalletBalances.usdt) || 0;
                    }
                    return 0;
                }

                return 0;
            }

            function formatCoinBalance(val, symbol) {
                const num = Number(val) || 0;
                if (num === 0) return (symbol === 'USDT' || symbol === 'USDC' || symbol === 'USD') ? '0.00' : '0';
                if (symbol === 'USDT' || symbol === 'USDC' || symbol === 'USD') {
                    return num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
                }
                if (num < 0.00001) return num.toFixed(8);
                if (num < 1) return num.toFixed(6);
                return num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 6 });
            }

            function getCryptoRate(cryptoSym) {
                if (!cryptoSym) return 1;
                return swapState.rates[cryptoSym.toUpperCase()] || 1;
            }

            function updateSwapRateText() {
                const rateEl = document.getElementById('swapLiveRateText');
                if (!rateEl) return;

                if (!swapState.toSymbol || !swapState.fromSymbol) {
                    rateEl.textContent = 'Select an asset to view exchange rate';
                    return;
                }

                const cryptoSym = swapState.fromSymbol === 'USDT' ? swapState.toSymbol : swapState.fromSymbol;
                const cryptoPrice = getCryptoRate(cryptoSym);
                let formattedPrice = '';
                if (cryptoPrice >= 100) {
                    formattedPrice = cryptoPrice.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                } else if (cryptoPrice >= 1) {
                    formattedPrice = cryptoPrice.toFixed(4);
                } else {
                    formattedPrice = cryptoPrice.toFixed(8).replace(/\.?0+$/, '');
                }
                rateEl.textContent = `1 ${cryptoSym} ≈ ${formattedPrice} USDT`;
            }

            function recalcSwapAmount(changedSource = 'from') {
                const fromInput = document.getElementById('swapFromAmount');
                const toInput = document.getElementById('swapToAmount');
                if (!fromInput || !toInput) return;

                if (!swapState.toSymbol || !swapState.fromSymbol) {
                    toInput.value = '';
                    validateSwapForm();
                    return;
                }

                const isFromUsdt = (swapState.fromSymbol === 'USDT');
                const cryptoSym = isFromUsdt ? swapState.toSymbol : swapState.fromSymbol;
                const cryptoPrice = getCryptoRate(cryptoSym);

                if (isFromUsdt) {
                    // From is USDT, To is Crypto
                    if (changedSource === 'from') {
                        const usdtVal = parseFloat(fromInput.value);
                        if (isNaN(usdtVal) || usdtVal <= 0 || cryptoPrice <= 0) {
                            toInput.value = '';
                        } else {
                            const cryptoCalc = usdtVal / cryptoPrice;
                            toInput.value = cryptoCalc >= 1 ? cryptoCalc.toFixed(4).replace(/\.?0+$/, '') : cryptoCalc.toFixed(8).replace(/\.?0+$/, '');
                        }
                    } else {
                        const cryptoVal = parseFloat(toInput.value);
                        if (isNaN(cryptoVal) || cryptoVal <= 0) {
                            fromInput.value = '';
                        } else {
                            const usdtCalc = cryptoVal * cryptoPrice;
                            fromInput.value = usdtCalc.toFixed(2);
                        }
                    }
                } else {
                    // From is Crypto, To is USDT
                    if (changedSource === 'from') {
                        const cryptoVal = parseFloat(fromInput.value);
                        if (isNaN(cryptoVal) || cryptoVal <= 0) {
                            toInput.value = '';
                        } else {
                            const usdtCalc = cryptoVal * cryptoPrice;
                            toInput.value = usdtCalc.toFixed(2);
                        }
                    } else {
                        const usdtVal = parseFloat(toInput.value);
                        if (isNaN(usdtVal) || usdtVal <= 0 || cryptoPrice <= 0) {
                            fromInput.value = '';
                        } else {
                            const cryptoCalc = usdtVal / cryptoPrice;
                            fromInput.value = cryptoCalc >= 1 ? cryptoCalc.toFixed(4).replace(/\.?0+$/, '') : cryptoCalc.toFixed(8).replace(/\.?0+$/, '');
                        }
                    }
                }

                validateSwapForm();
            }

            function validateSwapForm() {
                const fromInput = document.getElementById('swapFromAmount');
                const toInput = document.getElementById('swapToAmount');
                const fromBox = document.getElementById('swapFromBox') || fromInput?.closest('.swap-box');
                const toBox = document.getElementById('swapToBox') || toInput?.closest('.swap-box');
                const submitBtn = document.getElementById('swapSubmitBtn');
                const banner = document.getElementById('swapNoticeBanner');
                const noticeContent = document.getElementById('swapNoticeContent');
                const fromBal = getSwapCoinBalance(swapState.fromSymbol);
                const fromAmt = parseFloat(fromInput?.value) || 0;

                if (!submitBtn) return;

                // Reset error state on boxes
                fromBox?.classList.remove('is-invalid');
                toBox?.classList.remove('is-invalid');

                // Check if user entered an amount that exceeds available wallet balance for the currency
                const isInsufficient = (fromAmt > 0 && fromAmt > fromBal);
                if (isInsufficient) {
                    fromBox?.classList.add('is-invalid');
                    toBox?.classList.add('is-invalid');
                }

                // Scenario 0: Demo Mode (Exchange is strictly available for Real accounts)
                if (!isExchangeLiveMode()) {
                    if (banner) {
                        banner.style.display = 'flex';
                        if (noticeContent) {
                            noticeContent.innerHTML = `⚠️ <strong>Real Accounts Only:</strong> Buy & Exchange is strictly available for Real accounts. Demo accounts cannot exchange currency. Switch to a Live account to exchange funds.`;
                        }
                    }
                    if (toInput) {
                        toInput.value = '';
                        toInput.readOnly = true;
                    }
                    if (fromInput) {
                        fromInput.readOnly = true;
                    }
                    submitBtn.classList.add('is-disabled');
                    submitBtn.disabled = true;
                    submitBtn.textContent = 'Real accounts only';
                    return;
                }

                if (fromInput) fromInput.readOnly = false;

                // Scenario 1: Target currency is not selected yet
                if (!swapState.toSymbol || !swapState.fromSymbol) {
                    if (banner) {
                        banner.style.display = 'flex';
                        if (noticeContent) {
                            noticeContent.innerHTML = `Select a cryptocurrency below to exchange with your USDT.`;
                        }
                    }
                    if (toInput) {
                        toInput.value = '';
                        toInput.readOnly = true;
                    }
                    submitBtn.classList.add('is-disabled');
                    submitBtn.disabled = true;
                    submitBtn.textContent = 'Select an asset';
                    return;
                }

                if (toInput) toInput.readOnly = false;

                // Scenario 2: Zero balance in from asset
                if (fromBal <= 0) {
                    if (banner) banner.style.display = 'flex';
                    if (noticeContent) {
                        noticeContent.innerHTML = `No ${swapState.fromSymbol} in your wallet. <button type="button" id="swapNoticeDepositLink" style="color: #60a5fa; text-decoration: underline; background: none; border: none; font-weight: 700; cursor: pointer; padding: 0;">Deposit</button> to start exchanging.`;
                        const depLink = document.getElementById('swapNoticeDepositLink');
                        if (depLink) {
                            depLink.onclick = (e) => {
                                if (e) {
                                    e.preventDefault();
                                    e.stopPropagation();
                                }
                                if (typeof window.openAddFundsModal === 'function') {
                                    window.openAddFundsModal();
                                    return;
                                }
                                const addFundsModal = document.getElementById('globalAddFundsModal');
                                if (addFundsModal) {
                                    addFundsModal.hidden = false;
                                    addFundsModal.removeAttribute('hidden');
                                    addFundsModal.style.display = 'flex';
                                    addFundsModal.style.zIndex = '999999';
                                }
                            };
                        }
                    }
                    submitBtn.classList.add('is-disabled');
                    submitBtn.disabled = true;
                    submitBtn.textContent = 'Exchange';
                } else if (fromAmt > fromBal) {
                    // Scenario 3: Insufficient balance
                    if (banner) banner.style.display = 'flex';
                    if (noticeContent) {
                        noticeContent.innerHTML = `Insufficient ${swapState.fromSymbol} balance. Available: <strong>${formatCoinBalance(fromBal, swapState.fromSymbol)} ${swapState.fromSymbol}</strong>`;
                    }
                    submitBtn.classList.add('is-disabled');
                    submitBtn.disabled = true;
                    submitBtn.textContent = 'Insufficient balance';
                } else if (fromAmt <= 0) {
                    // Scenario 4: Awaiting amount
                    if (banner) banner.style.display = 'none';
                    submitBtn.classList.add('is-disabled');
                    submitBtn.disabled = true;
                    submitBtn.textContent = 'Enter an amount';
                } else {
                    // Scenario 5: Valid and ready to exchange
                    if (banner) banner.style.display = 'none';
                    submitBtn.classList.remove('is-disabled');
                    submitBtn.disabled = false;
                    submitBtn.textContent = `Exchange ${swapState.fromSymbol} to ${swapState.toSymbol}`;
                }
            }

            function updateSwapUI() {
                const elFromSym = document.getElementById('swapFromSymbol');
                const elFromIcon = document.getElementById('swapFromIcon');
                const elFromBal = document.getElementById('swapFromBalance');
                const elFromChevron = document.getElementById('swapFromChevron');
                const elFromBtn = document.getElementById('swapFromAssetBtn');

                const elToSym = document.getElementById('swapToSymbol');
                const elToIcon = document.getElementById('swapToIcon');
                const elToPlaceholderIcon = document.getElementById('swapToPlaceholderIcon');
                const elToBal = document.getElementById('swapToBalance');
                const elToChevron = document.getElementById('swapToChevron');
                const elToBtn = document.getElementById('swapToAssetBtn');

                // 1. Render From Box
                const isFromUsdt = (swapState.fromSymbol === 'USDT');
                const fromCoin = getCoinInfo(swapState.fromSymbol) || USDT_ASSET;

                if (elFromSym) elFromSym.textContent = fromCoin.symbol;
                if (elFromIcon) {
                    elFromIcon.src = fromCoin.icon;
                    elFromIcon.onerror = function() { this.src = `https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${fromCoin.symbol.toLowerCase()}.png`; };
                }
                if (elFromBal) elFromBal.textContent = formatCoinBalance(getSwapCoinBalance(fromCoin.symbol), fromCoin.symbol);

                // If From is USDT, lock it (one side is always USDT)
                if (elFromChevron) elFromChevron.style.display = isFromUsdt ? 'none' : 'inline-block';
                if (elFromBtn) elFromBtn.style.cursor = isFromUsdt ? 'default' : 'pointer';

                // 2. Render To Box
                const isToUsdt = (swapState.toSymbol === 'USDT');
                const isToNull = (swapState.toSymbol === null);

                if (isToNull) {
                    if (elToSym) elToSym.textContent = 'Select asset';
                    if (elToIcon) elToIcon.style.display = 'none';
                    if (elToPlaceholderIcon) elToPlaceholderIcon.style.display = 'block';
                    if (elToBal) elToBal.textContent = '-';
                    if (elToChevron) elToChevron.style.display = 'inline-block';
                    if (elToBtn) elToBtn.style.cursor = 'pointer';
                } else {
                    const toCoin = getCoinInfo(swapState.toSymbol);
                    if (elToSym) elToSym.textContent = toCoin.symbol;
                    if (elToIcon) {
                        elToIcon.style.display = 'block';
                        elToIcon.src = toCoin.icon;
                        elToIcon.onerror = function() { this.src = `https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${toCoin.symbol.toLowerCase()}.png`; };
                    }
                    if (elToPlaceholderIcon) elToPlaceholderIcon.style.display = 'none';
                    if (elToBal) elToBal.textContent = formatCoinBalance(getSwapCoinBalance(toCoin.symbol), toCoin.symbol);
                    if (elToChevron) elToChevron.style.display = isToUsdt ? 'none' : 'inline-block';
                    if (elToBtn) elToBtn.style.cursor = isToUsdt ? 'default' : 'pointer';
                }

                updateSwapRateText();
                validateSwapForm();
            }

            async function fetchSwapLiveRates() {
                try {
                    const res = await fetch('https://api.binance.com/api/v3/ticker/price');
                    if (res.ok) {
                        const list = await res.json();
                        if (Array.isArray(list)) {
                            list.forEach(item => {
                                const sym = item.symbol;
                                if (sym.endsWith('USDT')) {
                                    const coin = sym.replace('USDT', '');
                                    if (swapState.rates[coin] !== undefined) {
                                        swapState.rates[coin] = parseFloat(item.price);
                                    }
                                }
                            });
                        }
                    }
                } catch (e) {
                    try {
                        const cached = localStorage.getItem('kryvex_cached_markets');
                        if (cached) {
                            const parsed = JSON.parse(cached);
                            if (Array.isArray(parsed)) {
                                parsed.forEach(t => {
                                    const raw = (t.symbol || '').toUpperCase().replace('USDT', '');
                                    if (swapState.rates[raw] !== undefined && t.last_price) {
                                        swapState.rates[raw] = parseFloat(t.last_price);
                                    }
                                });
                            }
                        }
                    } catch (err) {}
                }
                updateSwapUI();
            }

            window.initBuyExchangeView = function() {
                updateSwapUI();
                fetchSwapLiveRates();
            };

            // Direct mode: From = USDT, To = null
            window.resetSwapToDirectMode = function() {
                swapState.fromSymbol = 'USDT';
                swapState.toSymbol = null;
                const fromInput = document.getElementById('swapFromAmount');
                const toInput = document.getElementById('swapToAmount');
                if (fromInput) fromInput.value = '';
                if (toInput) toInput.value = '';
                updateSwapUI();
            };

            // Particular currency mode: From = [Selected Coin], To = USDT
            window.setSwapFromAsset = function(symbol) {
                if (!symbol) {
                    window.resetSwapToDirectMode();
                    return;
                }
                const s = symbol.toUpperCase();
                if (s === 'USDT' || s === 'USD') {
                    window.resetSwapToDirectMode();
                    return;
                }
                const found = SWAP_CRYPTO_COINS.find(c => c.symbol === s);
                if (found) {
                    swapState.fromSymbol = found.symbol;
                    swapState.toSymbol = 'USDT';
                    const fromInput = document.getElementById('swapFromAmount');
                    const toInput = document.getElementById('swapToAmount');
                    if (fromInput) fromInput.value = '';
                    if (toInput) toInput.value = '';
                    updateSwapUI();
                } else {
                    window.resetSwapToDirectMode();
                }
            };

            // Asset Selection Modal Logic (Cryptocurrencies ONLY, USDT is NEVER in this modal)
            function openSwapAssetModal(target) {
                // If clicked on the USDT side, do not open (one side is always USDT)
                if ((target === 'from' && swapState.fromSymbol === 'USDT') || (target === 'to' && swapState.toSymbol === 'USDT')) {
                    return;
                }

                swapState.modalTarget = target;
                const modal = document.getElementById('swapAssetModalBackdrop');
                const title = document.getElementById('swapAssetModalTitle');
                const search = document.getElementById('swapAssetSearchInput');

                if (title) title.textContent = target === 'from' ? 'Select cryptocurrency to sell' : 'Select cryptocurrency to receive';
                if (search) {
                    search.value = '';
                    setTimeout(() => search.focus(), 50);
                }
                renderSwapModalAssetList('');
                if (modal) {
                    modal.hidden = false;
                    modal.style.display = 'flex';
                }
            }

            function closeSwapAssetModal() {
                const modal = document.getElementById('swapAssetModalBackdrop');
                if (modal) {
                    modal.hidden = true;
                    modal.style.display = 'none';
                }
            }

            function renderSwapModalAssetList(filterText = '') {
                const listEl = document.getElementById('swapModalAssetList');
                if (!listEl) return;

                const q = filterText.toLowerCase().trim();
                // Exclude USDT completely! Only show cryptocurrency assets
                const filtered = SWAP_CRYPTO_COINS.filter(c => 
                    !q || c.symbol.toLowerCase().includes(q) || c.name.toLowerCase().includes(q)
                );

                if (!filtered.length) {
                    listEl.innerHTML = `<div style="text-align:center; padding: 24px; color: rgba(255,255,255,0.4); font-size: 0.85rem;">No cryptocurrencies found matching "${filterText}"</div>`;
                    return;
                }

                listEl.innerHTML = filtered.map(c => {
                    const bal = getSwapCoinBalance(c.symbol);
                    const formattedBal = formatCoinBalance(bal, c.symbol);
                    return `
                        <div class="swap-modal-asset-item" data-swap-select="${c.symbol}">
                            <div class="swap-modal-asset-left">
                                <div class="swap-modal-asset-icon">
                                    <img src="${c.icon}" alt="${c.symbol}" onerror="this.src='https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${c.symbol.toLowerCase()}.png';">
                                </div>
                                <div>
                                    <span class="swap-modal-asset-sym">${c.symbol}</span>
                                    <span class="swap-modal-asset-name">${c.name}</span>
                                </div>
                            </div>
                            <div class="swap-modal-asset-balance">
                                ${formattedBal}
                            </div>
                        </div>
                    `;
                }).join('');

                listEl.querySelectorAll('[data-swap-select]').forEach(item => {
                    item.addEventListener('click', () => {
                        const selectedSym = item.getAttribute('data-swap-select');
                        if (swapState.modalTarget === 'from') {
                            swapState.fromSymbol = selectedSym;
                            swapState.toSymbol = 'USDT';
                        } else {
                            swapState.fromSymbol = 'USDT';
                            swapState.toSymbol = selectedSym;
                        }
                        closeSwapAssetModal();
                        updateSwapUI();
                        recalcSwapAmount('from');
                    });
                });
            }

            // Bind Modal Search & Close Buttons
            const swapSearchInput = document.getElementById('swapAssetSearchInput');
            if (swapSearchInput) {
                swapSearchInput.addEventListener('input', (e) => {
                    renderSwapModalAssetList(e.target.value);
                });
            }

            const swapModalCloseBtn = document.getElementById('swapAssetModalCloseBtn');
            if (swapModalCloseBtn) {
                swapModalCloseBtn.addEventListener('click', closeSwapAssetModal);
            }

            const swapAssetModalBackdrop = document.getElementById('swapAssetModalBackdrop');
            if (swapAssetModalBackdrop) {
                swapAssetModalBackdrop.addEventListener('click', (e) => {
                    if (e.target === swapAssetModalBackdrop) closeSwapAssetModal();
                });
            }

            const swapModalDepLink = document.getElementById('swapModalDepositLink');
            if (swapModalDepLink) {
                swapModalDepLink.addEventListener('click', () => {
                    closeSwapAssetModal();
                    const depModal = document.getElementById('depositModalBackdrop');
                    if (depModal) {
                        depModal.hidden = false;
                        depModal.style.display = 'flex';
                    } else {
                        switchMainTab('wallet-ops', true);
                        switchWalletInnerNav('deposit');
                    }
                });
            }

            // Bind Swap View Buttons & Inputs
            const btnSwapBack = document.getElementById('swapBackBtn');
            if (btnSwapBack) {
                btnSwapBack.addEventListener('click', () => {
                    switchMainTab('wallet', true);
                });
            }

            const btnSwapHistory = document.getElementById('swapHistoryBtn');
            if (btnSwapHistory) {
                btnSwapHistory.addEventListener('click', () => {
                    switchMainTab('wallet-ops', true);
                    switchWalletInnerNav('history');
                });
            }

            const btnSwapFromAsset = document.getElementById('swapFromAssetBtn');
            if (btnSwapFromAsset) {
                btnSwapFromAsset.addEventListener('click', () => {
                    if (swapState.fromSymbol !== 'USDT') {
                        openSwapAssetModal('from');
                    }
                });
            }

            const btnSwapToAsset = document.getElementById('swapToAssetBtn');
            if (btnSwapToAsset) {
                btnSwapToAsset.addEventListener('click', () => {
                    if (swapState.toSymbol !== 'USDT') {
                        openSwapAssetModal('to');
                    }
                });
            }

            const btnSwapSwitch = document.getElementById('swapSwitchDirectionBtn');
            if (btnSwapSwitch) {
                btnSwapSwitch.addEventListener('click', () => {
                    // One side is always USDT
                    if (swapState.fromSymbol === 'USDT') {
                        if (swapState.toSymbol) {
                            // Swap: From = Crypto, To = USDT
                            swapState.fromSymbol = swapState.toSymbol;
                            swapState.toSymbol = 'USDT';
                            const fromInput = document.getElementById('swapFromAmount');
                            const toInput = document.getElementById('swapToAmount');
                            if (fromInput) fromInput.value = '';
                            if (toInput) toInput.value = '';
                            updateSwapUI();
                        } else {
                            // If To was null, prompt user to select the crypto to sell for USDT
                            openSwapAssetModal('from');
                        }
                    } else {
                        // From was Crypto, To was USDT -> Swap: From = USDT, To = Crypto
                        swapState.toSymbol = swapState.fromSymbol;
                        swapState.fromSymbol = 'USDT';
                        const fromInput = document.getElementById('swapFromAmount');
                        const toInput = document.getElementById('swapToAmount');
                        if (fromInput) fromInput.value = '';
                        if (toInput) toInput.value = '';
                        updateSwapUI();
                    }
                });
            }

            const btnSwapMax = document.getElementById('swapFromMaxBtn');
            if (btnSwapMax) {
                btnSwapMax.addEventListener('click', (e) => {
                    if (e) {
                        e.preventDefault();
                        e.stopPropagation();
                    }
                    if (typeof window.openAddFundsModal === 'function') {
                        window.openAddFundsModal();
                        return;
                    }
                    const addFundsModal = document.getElementById('globalAddFundsModal');
                    if (addFundsModal) {
                        addFundsModal.hidden = false;
                        addFundsModal.removeAttribute('hidden');
                        addFundsModal.style.display = 'flex';
                        addFundsModal.style.zIndex = '999999';
                    }
                });
            }

            const inputSwapFrom = document.getElementById('swapFromAmount');
            if (inputSwapFrom) {
                inputSwapFrom.addEventListener('input', () => recalcSwapAmount('from'));
            }

            const inputSwapTo = document.getElementById('swapToAmount');
            if (inputSwapTo) {
                inputSwapTo.addEventListener('input', () => recalcSwapAmount('to'));
            }

            // Submit Buy & Exchange Form
            const btnSwapSubmit = document.getElementById('swapSubmitBtn');
            if (btnSwapSubmit) {
                btnSwapSubmit.addEventListener('click', async () => {
                    if (swapState.isSubmitting) return;

                    if (!isExchangeLiveMode()) {
                        if (typeof showWalletToast === 'function') {
                            showWalletToast('Buy & Exchange is strictly available for Real accounts. Switch to a Live account to exchange funds.', 'warning');
                        } else {
                            alert('Buy & Exchange is strictly available for Real accounts.');
                        }
                        return;
                    }

                    if (!swapState.toSymbol || !swapState.fromSymbol) {
                        openSwapAssetModal('to');
                        return;
                    }

                    const fromInput = document.getElementById('swapFromAmount');
                    const amountVal = parseFloat(fromInput?.value) || 0;
                    const fromBal = getSwapCoinBalance(swapState.fromSymbol);

                    if (amountVal <= 0) {
                        if (typeof showWalletToast === 'function') {
                            showWalletToast('Please enter a valid amount to exchange', 'error');
                        } else {
                            alert('Please enter a valid amount to exchange');
                        }
                        return;
                    }

                    if (amountVal > fromBal) {
                        if (typeof showWalletToast === 'function') {
                            showWalletToast(`Insufficient ${swapState.fromSymbol} balance`, 'error');
                        } else {
                            alert(`Insufficient ${swapState.fromSymbol} balance`);
                        }
                        return;
                    }

                    swapState.isSubmitting = true;
                    btnSwapSubmit.disabled = true;
                    btnSwapSubmit.textContent = 'Processing exchange...';

                    try {
                        const isFromUsdt = (swapState.fromSymbol === 'USDT');
                        const cryptoSym = isFromUsdt ? swapState.toSymbol : swapState.fromSymbol;
                        const payload = {
                            action: isFromUsdt ? 'buy' : 'sell',
                            from_currency: swapState.fromSymbol,
                            to_currency: swapState.toSymbol,
                            crypto_currency: cryptoSym,
                            amount: amountVal
                        };

                        const fetchFn = typeof window.authFetch === 'function' ? window.authFetch : async (url, opts) => {
                            const token = localStorage.getItem('kryvex_token') || sessionStorage.getItem('kryvex_token');
                            const res = await fetch(url, {
                                ...opts,
                                headers: {
                                    'Content-Type': 'application/json',
                                    'Accept': 'application/json',
                                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '',
                                    ...(token ? { 'Authorization': `Bearer ${token}` } : {}),
                                    ...(opts.headers || {})
                                }
                            });
                            return res.json();
                        };

                        const result = await fetchFn('/api/wallet/crypto-exchange', {
                            method: 'POST',
                            body: JSON.stringify(payload)
                        });

                        if (result && (result.success || result.status === 'success')) {
                            const successMsg = result.message || `Successfully exchanged ${amountVal} ${swapState.fromSymbol} for ${swapState.toSymbol}!`;
                            if (typeof showWalletToast === 'function') {
                                showWalletToast(successMsg, 'success');
                            } else {
                                alert(successMsg);
                            }

                            if (fromInput) fromInput.value = '';
                            const toInput = document.getElementById('swapToAmount');
                            if (toInput) toInput.value = '';

                            // Refresh balances across wallet
                            if (typeof window.fetchWalletBalances === 'function') {
                                window.fetchWalletBalances();
                            }
                            if (typeof window.syncBalancesToOverview === 'function') {
                                window.syncBalancesToOverview();
                            }

                            setTimeout(updateSwapUI, 400);
                        } else {
                            const errMsg = result?.message || 'Failed to complete exchange. Please try again.';
                            if (typeof showWalletToast === 'function') {
                                showWalletToast(errMsg, 'error');
                            } else {
                                alert(errMsg);
                            }
                        }
                    } catch (err) {
                        const errText = err.message || 'An error occurred during exchange.';
                        if (typeof showWalletToast === 'function') {
                            showWalletToast(errText, 'error');
                        } else {
                            alert(errText);
                        }
                    } finally {
                        swapState.isSubmitting = false;
                        validateSwapForm();
                    }
                });
            }

            // =========================================================================
            // MODERN STEP-BY-STEP DEPOSIT CONTROLLER (MATCHING PRIMEXBT REFERENCE DESIGN)
            // =========================================================================
            function checkIsUserDemoMode() {
                if (typeof window.isCurrentAccountLive === 'function') {
                    return !window.isCurrentAccountLive();
                }
                try {
                    const accounts = JSON.parse(localStorage.getItem('kryvex_trading_accounts_cache') || '[]') || [];
                    const activeUid = localStorage.getItem('kryvex_active_account_uid');
                    if (activeUid) {
                        const acc = accounts.find(a => a.account_uid === activeUid);
                        if (acc) {
                            return Boolean(
                                acc.is_demo || 
                                acc.account_type === 'demo' || 
                                acc.account_name === 'Demo Account' || 
                                String(acc.account_name || '').toLowerCase().startsWith('demo')
                            );
                        }
                    }
                } catch(e) {}
                const mode = (window.getActiveTradingMode ? window.getActiveTradingMode() : (localStorage.getItem('kryvex_trading_mode') || 'demo'));
                return mode === 'demo';
            }

            function checkUserKycStatus() {
                let user = {};
                try {
                    user = JSON.parse(localStorage.getItem('kryvex_user') || '{}') || {};
                } catch(e) {}
                const status = String(user.kyc_status || user.kyc || '').toLowerCase();
                const isVerified = ['verified', 'approved'].includes(status);
                return {
                    status: status || 'unverified',
                    isVerified: isVerified
                };
            }

