            window.setStepDepositMode = function(mode, preserveState = false) {
                mode = window.normalizeDepositMode(mode) || 'crypto';
                stepDepositState.mode = mode;
                try { sessionStorage.setItem('kryvex_active_deposit_mode', mode); } catch(e) {}
                try { localStorage.setItem('kryvex_active_deposit_mode', mode); } catch(e) {}

                if (window.history && window.history.replaceState) {
                    try {
                        const url = new URL(window.location.href);
                        url.searchParams.set('mode', mode);
                        window.history.replaceState(null, '', url.toString());
                    } catch(e) {}
                }

                const btnDepToggleCrypto = document.getElementById('btnDepositToggleCrypto');
                const btnDepToggleMoney = document.getElementById('btnDepositToggleMoney');
                const depositMainTitle = document.getElementById('depositMainTitle');
                const cryptoStepsContainer = document.getElementById('cryptoStepsContainer');
                const moneyStepsContainer = document.getElementById('moneyStepsContainer');

                if (mode === 'money') {
                    if (btnDepToggleCrypto) btnDepToggleCrypto.classList.remove('is-active');
                    if (btnDepToggleMoney) btnDepToggleMoney.classList.add('is-active');
                    if (depositMainTitle) depositMainTitle.textContent = 'Deposit money';
                    if (cryptoStepsContainer) cryptoStepsContainer.style.display = 'none';
                    if (moneyStepsContainer) moneyStepsContainer.style.display = 'block';
                    if (preserveState && stepDepositState.selectedMoneyCurrency) {
                        selectStepMoneyCurrency(stepDepositState.selectedMoneyCurrency);
                    } else {
                        resetStepMoneyView();
                    }
                    if (typeof renderMoneyCurrencyDropdownList === 'function') renderMoneyCurrencyDropdownList('');
                } else {
                    if (btnDepToggleMoney) btnDepToggleMoney.classList.remove('is-active');
                    if (btnDepToggleCrypto) btnDepToggleCrypto.classList.add('is-active');
                    if (depositMainTitle) depositMainTitle.textContent = 'Deposit crypto';
                    if (moneyStepsContainer) moneyStepsContainer.style.display = 'none';
                    if (cryptoStepsContainer) cryptoStepsContainer.style.display = 'block';
                    if (preserveState && stepDepositState.selectedCoin) {
                        selectStepDepositCurrency(stepDepositState.selectedCoin.symbol);
                    } else {
                        resetStepDepositView();
                    }
                    if (typeof renderCurrencyDropdownList === 'function') renderCurrencyDropdownList('');
                }
            };

            // Withdraw Mode Toggle & Step Progress Helpers
            window.setStepWithdrawMode = function(mode) {
                const isMoney = (mode === 'money' || mode === 'inr');
                const targetMode = isMoney ? 'money' : 'crypto';

                try { sessionStorage.setItem('kryvex_active_withdraw_mode', targetMode); } catch(e) {}

                if (window.history && window.history.replaceState) {
                    try {
                        const url = new URL(window.location.href);
                        url.searchParams.set('withdraw_mode', targetMode);
                        window.history.replaceState(null, '', url.toString());
                    } catch(e) {}
                }

                const btnCrypto = document.getElementById('btnWithdrawToggleCrypto');
                const btnMoney = document.getElementById('btnWithdrawToggleMoney');
                const titleEl = document.getElementById('withdrawMainTitle');
                const cryptoContainer = document.getElementById('withdrawCryptoStepsContainer');
                const moneyContainer = document.getElementById('withdrawMoneyStepsContainer');
                const usdtForm = document.getElementById('withdrawForm');
                const inrForm = document.getElementById('inrWithdrawForm');

                if (isMoney) {
                    if (btnCrypto) btnCrypto.classList.remove('is-active');
                    if (btnMoney) btnMoney.classList.add('is-active');
                    if (titleEl) titleEl.textContent = 'Withdraw money';
                    if (cryptoContainer) cryptoContainer.style.display = 'none';
                    if (moneyContainer) moneyContainer.style.display = 'block';
                    if (inrForm) inrForm.style.display = 'flex';
                    if (usdtForm) usdtForm.style.display = 'none';
                } else {
                    if (btnMoney) btnMoney.classList.remove('is-active');
                    if (btnCrypto) btnCrypto.classList.add('is-active');
                    if (titleEl) titleEl.textContent = 'Withdraw crypto';
                    if (moneyContainer) moneyContainer.style.display = 'none';
                    if (cryptoContainer) cryptoContainer.style.display = 'block';
                    if (usdtForm) usdtForm.style.display = 'flex';
                    if (inrForm) inrForm.style.display = 'none';
                }
            };

            // Centralized helper to close all wallet dropdowns when opening a new one
            function closeAllWalletDropdowns(exceptPanelId = null) {
                const dropdownConfigs = [
                    { panelId: 'withdrawCurrencyDropdownPanel', btnId: 'btnOpenWithdrawCurrencyDropdown', chevronId: 'withdrawCurrencyDropdownChevron' },
                    { panelId: 'withdrawFromDropdownPanel', btnId: 'btnOpenWithdrawFromDropdown', chevronId: 'withdrawFromDropdownChevron' },
                    { panelId: 'withdrawNetworkDropdownPanel', btnId: 'btnOpenWithdrawNetworkDropdown', chevronId: 'withdrawNetworkDropdownChevron' },
                    { panelId: 'withdrawMoneyCurrencyDropdownPanel', btnId: 'btnOpenWithdrawMoneyCurrencyDropdown', chevronId: 'withdrawMoneyCurrencyDropdownChevron' },
                    { panelId: 'withdrawMoneyFromDropdownPanel', btnId: 'btnOpenWithdrawMoneyFromDropdown', chevronId: 'withdrawMoneyFromDropdownChevron' },
                    { panelId: 'currencyDropdownPanel', btnId: 'btnOpenCurrencyDropdown', chevronId: 'currencyDropdownChevron' },
                    { panelId: 'depositToDropdownPanel', btnId: 'btnOpenDepositToDropdown', chevronId: 'depositToDropdownChevron' },
                    { panelId: 'depositNetworkDropdownPanel', btnId: 'btnOpenDepositNetworkDropdown', chevronId: 'depositNetworkDropdownChevron' },
                    { panelId: 'moneyCurrencyDropdownPanel', btnId: 'btnOpenMoneyCurrencyDropdown', chevronId: 'moneyCurrencyDropdownChevron' },
                    { panelId: 'moneyDepositToDropdownPanel', btnId: 'btnOpenMoneyDepositToDropdown', chevronId: 'moneyDepositToDropdownChevron' },
                    { panelId: 'moneyPaymentMethodDropdownPanel', btnId: 'btnOpenMoneyPaymentMethodDropdown', chevronId: 'moneyPaymentMethodDropdownChevron' },
                    { panelId: 'withdrawMoneyMethodDropdownPanel', btnId: 'btnOpenWithdrawMoneyMethodDropdown', chevronId: 'withdrawMoneyMethodChevron' }
                ];

                dropdownConfigs.forEach(item => {
                    if (exceptPanelId && item.panelId === exceptPanelId) return;
                    const panel = document.getElementById(item.panelId);
                    const btn = document.getElementById(item.btnId);
                    const chevron = document.getElementById(item.chevronId);
                    if (panel && panel.style.display !== 'none') {
                        panel.style.display = 'none';
                    }
                    if (chevron) {
                        chevron.style.transform = 'rotate(0deg)';
                    }
                    if (btn) {
                        btn.classList.remove('is-open');
                    }
                });
            }
            window.closeAllWalletDropdowns = closeAllWalletDropdowns;

            // Withdraw Crypto Currency Dropdown Logic
            let selectedWithdrawCoin = STEP_DEPOSIT_COINS.find(c => c.symbol === 'USDT') || STEP_DEPOSIT_COINS[0];

            function toggleWithdrawCurrencyDropdown(open) {
                const btnOpen = document.getElementById('btnOpenWithdrawCurrencyDropdown');
                const panel = document.getElementById('withdrawCurrencyDropdownPanel');
                const chevron = document.getElementById('withdrawCurrencyDropdownChevron');
                const searchInput = document.getElementById('withdrawCurrencySearchInput');
                if (!panel) return;
                const shouldOpen = open !== undefined ? open : (panel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('withdrawCurrencyDropdownPanel');
                }
                panel.style.display = shouldOpen ? 'block' : 'none';
                if (chevron) chevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                if (btnOpen) btnOpen.classList.toggle('is-open', shouldOpen);
                if (shouldOpen) {
                    if (searchInput) searchInput.value = '';
                    renderWithdrawCurrencyDropdownList('');
                    setTimeout(() => searchInput?.focus(), 60);
                }
            }

            function renderWithdrawCurrencyDropdownList(filterText = '') {
                const withdrawCurrencyDropdownList = document.getElementById('withdrawCurrencyDropdownList');
                if (!withdrawCurrencyDropdownList) return;
                const q = filterText.toLowerCase().trim();
                const filtered = STEP_DEPOSIT_COINS.filter(c => 
                    !q || c.symbol.toLowerCase().includes(q) || c.name.toLowerCase().includes(q)
                );

                if (!filtered.length) {
                    withdrawCurrencyDropdownList.innerHTML = `<div style="text-align:center; padding: 16px; color: rgba(255,255,255,0.4); font-size: 0.8rem;">No cryptocurrency found matching "${filterText}"</div>`;
                    return;
                }

                withdrawCurrencyDropdownList.innerHTML = filtered.map(coin => {
                    const isSelected = !!window.withdrawFlowSelections?.crypto?.currency && selectedWithdrawCoin?.symbol === coin.symbol;
                    return `
                        <div class="kvx-dropdown-item ${isSelected ? 'is-selected' : ''}" data-withdraw-coin-select="${coin.symbol}">
                            <div class="kvx-dropdown-item-left">
                                <img src="${coin.icon}" alt="${coin.symbol}" class="kvx-currency-icon" onerror="this.src='https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${coin.symbol.toLowerCase()}.png';" />
                                <div class="kvx-dropdown-item-names">
                                    <span class="kvx-currency-symbol">${coin.symbol}</span>
                                    <span class="kvx-dropdown-item-sub">${coin.name}</span>
                                </div>
                            </div>
                            <div class="kvx-dropdown-item-right">
                                ${isSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : ''}
                            </div>
                        </div>
                    `;
                }).join('');

                withdrawCurrencyDropdownList.querySelectorAll('[data-withdraw-coin-select]').forEach(item => {
                    item.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const sym = item.getAttribute('data-withdraw-coin-select');
                        selectWithdrawCurrency(sym);
                        window.markWithdrawFlowSelection?.('crypto', 'currency');
                        toggleWithdrawCurrencyDropdown(false);
                    });
                });
            }

            function selectWithdrawCurrency(symbol) {
                const coin = STEP_DEPOSIT_COINS.find(c => c.symbol === symbol) || STEP_DEPOSIT_COINS[0];
                selectedWithdrawCoin = coin;

                const iconEl = document.getElementById('selectedWithdrawCurrencyIcon');
                const symbolEl = document.getElementById('selectedWithdrawCurrencySymbol');
                const nameEl = document.getElementById('selectedWithdrawCurrencyName');
                const pillEl = document.getElementById('withdrawAssetPill');
                const helpEl = document.getElementById('withdrawNetworkHelpText');

                if (iconEl) iconEl.src = coin.icon;
                if (symbolEl) symbolEl.textContent = coin.symbol;
                if (nameEl) nameEl.textContent = coin.name;
                if (pillEl) pillEl.textContent = coin.symbol;

                const defaultNet = coin.defaultNetwork || (coin.networks ? coin.networks[0] : 'TRC20');
                if (helpEl) {
                    helpEl.textContent = defaultNet;
                }

                // Select default network for newly selected currency
                selectWithdrawNetwork(defaultNet);

                toggleWithdrawCurrencyDropdown(false);
                if (typeof closeAllWalletDropdowns === 'function') closeAllWalletDropdowns();

                updateWithdrawStepProgress();
            }

            // =========================================================================
            // WITHDRAW NETWORK DROPDOWN CONTROLLER
            // =========================================================================
            function toggleWithdrawNetworkDropdown(open) {
                const btnOpen = document.getElementById('btnOpenWithdrawNetworkDropdown');
                const panel = document.getElementById('withdrawNetworkDropdownPanel');
                const chevron = document.getElementById('withdrawNetworkDropdownChevron');
                if (!panel) return;
                const shouldOpen = open !== undefined ? open : (panel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('withdrawNetworkDropdownPanel');
                }
                panel.style.display = shouldOpen ? 'block' : 'none';
                if (chevron) chevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                if (btnOpen) btnOpen.classList.toggle('is-open', shouldOpen);
                if (shouldOpen) {
                    renderWithdrawNetworkDropdownList(selectedWithdrawCoin);
                }
            }

            function renderWithdrawNetworkDropdownList(coin) {
                const withdrawNetworkList = document.getElementById('withdrawNetworkList');
                if (!withdrawNetworkList || !coin) return;
                const networks = coin.networks || [coin.defaultNetwork || 'TRC20'];
                const selectedNet = stepWithdrawState.selectedNetwork || coin.defaultNetwork || networks[0];

                withdrawNetworkList.innerHTML = networks.map(net => {
                    const isSelected = net === selectedNet;
                    const netIcon = NETWORK_ICONS[net] || coin.icon;
                    const meta = NETWORK_META[net] || { title: net, desc: `${coin.symbol} (${net})` };
                    return `
                        <div class="kvx-dropdown-item ${isSelected ? 'is-selected' : ''}" data-withdraw-net-select="${net}" style="padding: 10px 12px; cursor: pointer;">
                            <div class="kvx-dropdown-item-left" style="gap: 12px; display: flex; align-items: center;">
                                <div style="width: 30px; height: 30px; background: rgba(255, 255, 255, 0.08); border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; overflow: hidden;">
                                    <img src="${netIcon}" alt="${net}" style="width: 20px; height: 20px; object-fit: contain;" onerror="this.src='${coin.icon}'" />
                                </div>
                                <div class="kvx-dropdown-item-names" style="display: flex; flex-direction: column;">
                                    <span class="kvx-currency-symbol" style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">${meta.title}</span>
                                    <span class="kvx-dropdown-item-sub" style="font-size: 0.74rem; color: rgba(255,255,255,0.45);">${meta.desc}</span>
                                </div>
                            </div>
                            <div class="kvx-dropdown-item-right">
                                ${isSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : ''}
                            </div>
                        </div>
                    `;
                }).join('');

                withdrawNetworkList.querySelectorAll('[data-withdraw-net-select]').forEach(item => {
                    item.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const net = item.getAttribute('data-withdraw-net-select');
                        selectWithdrawNetwork(net);
                        toggleWithdrawNetworkDropdown(false);
                    });
                });
            }

            function selectWithdrawNetwork(netCode) {
                const withdrawNetworkSelect = document.getElementById('withdrawNetworkSelect');
                const coin = selectedWithdrawCoin || STEP_DEPOSIT_COINS[0];
                const networks = coin.networks || [coin.defaultNetwork || 'TRC20'];
                const net = networks.includes(netCode) ? netCode : (coin.defaultNetwork || networks[0]);

                stepWithdrawState.selectedNetwork = net;

                // Sync hidden select input for backend form submit compatibility
                if (withdrawNetworkSelect) {
                    withdrawNetworkSelect.innerHTML = networks.map(n => `<option value="${n}" ${n === net ? 'selected' : ''}>${n}</option>`).join('');
                    withdrawNetworkSelect.value = net;
                }
                const withdrawCurrencyInput = document.getElementById('withdrawCurrencyInput');
                if (withdrawCurrencyInput) {
                    withdrawCurrencyInput.value = coin.symbol;
                    withdrawCurrencyInput.setAttribute('value', coin.symbol);
                }

                // Update UI Display
                const titleEl = document.getElementById('withdrawNetworkTitle');
                const subEl = document.getElementById('withdrawNetworkSub');
                const iconEl = document.getElementById('selectedWithdrawNetworkIcon');
                const helpEl = document.getElementById('withdrawNetworkHelpText');
                const meta = NETWORK_META[net] || { title: net, desc: `${coin.symbol} (${net})` };
                const netIcon = NETWORK_ICONS[net] || coin.icon;

                if (titleEl) titleEl.textContent = meta.title;
                if (subEl) subEl.textContent = meta.desc;
                if (iconEl) {
                    iconEl.src = netIcon;
                    iconEl.onerror = () => { iconEl.src = coin.icon; };
                }
                if (helpEl) {
                    helpEl.textContent = net;
                }

                // Show only the address saved for this network, plus its address rule
                if (typeof window.renderWithdrawAddressPanel === 'function') {
                    window.renderWithdrawAddressPanel();
                }
                if (typeof window.updateWithdrawCalculation === 'function') {
                    window.updateWithdrawCalculation();
                }

                toggleWithdrawNetworkDropdown(false);
                if (typeof closeAllWalletDropdowns === 'function') closeAllWalletDropdowns();

                updateWithdrawStepProgress();
            }
            window.selectWithdrawNetwork = selectWithdrawNetwork;

            // Money (INR) Currency Dropdown Logic
            function toggleWithdrawMoneyCurrencyDropdown(open) {
                const btnOpen = document.getElementById('btnOpenWithdrawMoneyCurrencyDropdown');
                const panel = document.getElementById('withdrawMoneyCurrencyDropdownPanel');
                const chevron = document.getElementById('withdrawMoneyCurrencyDropdownChevron');
                if (!panel) return;
                const shouldOpen = open !== undefined ? open : (panel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('withdrawMoneyCurrencyDropdownPanel');
                }
                panel.style.display = shouldOpen ? 'block' : 'none';
                if (chevron) chevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                if (btnOpen) btnOpen.classList.toggle('is-open', shouldOpen);
            }

            // Universal Document Event Delegation (Guarantees clicks work after page refresh)
            document.addEventListener('click', function(e) {
                // Toggles
                const witCryptoToggle = e.target.closest('#btnWithdrawToggleCrypto');
                if (witCryptoToggle) {
                    e.preventDefault();
                    e.stopPropagation();
                    window.setStepWithdrawMode('crypto');
                    window.resetWithdrawSteps?.();
                    return;
                }
                const witMoneyToggle = e.target.closest('#btnWithdrawToggleMoney');
                if (witMoneyToggle) {
                    e.preventDefault();
                    e.stopPropagation();
                    window.setStepWithdrawMode('money');
                    window.resetWithdrawSteps?.();
                    return;
                }
                const depCryptoToggle = e.target.closest('#btnDepositToggleCrypto');
                if (depCryptoToggle) {
                    e.preventDefault();
                    e.stopPropagation();
                    window.setStepDepositMode('crypto', false);
                    return;
                }
                const depMoneyToggle = e.target.closest('#btnDepositToggleMoney');
                if (depMoneyToggle) {
                    e.preventDefault();
                    e.stopPropagation();
                    window.setStepDepositMode('money', false);
                    return;
                }

                // Dropdown Trigger Buttons
                const btnWitCurr = e.target.closest('#btnOpenWithdrawCurrencyDropdown');
                if (btnWitCurr) {
                    e.preventDefault();
                    e.stopPropagation();
                    toggleWithdrawCurrencyDropdown();
                    return;
                }
                const btnWitNet = e.target.closest('#btnOpenWithdrawNetworkDropdown');
                if (btnWitNet) {
                    e.preventDefault();
                    e.stopPropagation();
                    toggleWithdrawNetworkDropdown();
                    return;
                }
                const btnWitFrom = e.target.closest('#btnOpenWithdrawFromDropdown');
                if (btnWitFrom) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleWithdrawFromDropdown === 'function') toggleWithdrawFromDropdown();
                    return;
                }
                const btnWitMoneyFrom = e.target.closest('#btnOpenWithdrawMoneyFromDropdown');
                if (btnWitMoneyFrom) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleWithdrawMoneyFromDropdown === 'function') toggleWithdrawMoneyFromDropdown();
                    return;
                }
                const btnWitMoneyCurr = e.target.closest('#btnOpenWithdrawMoneyCurrencyDropdown');
                if (btnWitMoneyCurr) {
                    e.preventDefault();
                    e.stopPropagation();
                    toggleWithdrawMoneyCurrencyDropdown();
                    return;
                }
                const btnDepCurr = e.target.closest('#btnOpenCurrencyDropdown');
                if (btnDepCurr) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleCurrencyDropdown === 'function') toggleCurrencyDropdown();
                    return;
                }
                const btnDepTo = e.target.closest('#btnOpenDepositToDropdown');
                if (btnDepTo) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleDepositToDropdown === 'function') toggleDepositToDropdown();
                    return;
                }
                const btnDepNet = e.target.closest('#btnOpenDepositNetworkDropdown');
                if (btnDepNet) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleDepositNetworkDropdown === 'function') toggleDepositNetworkDropdown();
                    return;
                }
                const btnMoneyCurr = e.target.closest('#btnOpenMoneyCurrencyDropdown');
                if (btnMoneyCurr) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleMoneyCurrencyDropdown === 'function') toggleMoneyCurrencyDropdown();
                    return;
                }
                const btnMoneyDepTo = e.target.closest('#btnOpenMoneyDepositToDropdown');
                if (btnMoneyDepTo) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleMoneyDepositToDropdown === 'function') toggleMoneyDepositToDropdown();
                    return;
                }
                const btnMoneyPM = e.target.closest('#btnOpenMoneyPaymentMethodDropdown');
                if (btnMoneyPM) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (typeof toggleMoneyPaymentMethodDropdown === 'function') toggleMoneyPaymentMethodDropdown();
                    return;
                }

                // Copy buttons
                const copyBtn = e.target.closest('#btnStepCopyAddress, #btnInlineCopyAddress');
                if (copyBtn) {
                    e.preventDefault();
                    if (typeof copyDepositAddress === 'function') copyDepositAddress();
                    return;
                }

                // Scan address button
                const scanBtn = e.target.closest('#btnTriggerCameraScanStep4');
                if (scanBtn) {
                    e.preventDefault();
                    if (typeof copyDepositAddress === 'function') copyDepositAddress();
                    return;
                }

                if (e.target.closest('#withdrawMoneyCurrencyDropdownList .kvx-dropdown-item')) {
                    window.markWithdrawFlowSelection?.('money', 'currency');
                }

                // Item selections inside any dropdown panel -> close all dropdown panels immediately
                const itemSelect = e.target.closest('.kvx-dropdown-item, .kvx-currency-item, [data-withdraw-coin-select], [data-withdraw-acc-id], [data-withdraw-net-select], [data-coin-select], [data-acc-id], [data-network-select], [data-money-currency-select], [data-pm-select]');
                if (itemSelect) {
                    if (typeof closeAllWalletDropdowns === 'function') {
                        closeAllWalletDropdowns();
                    }
                }

                // Click-Outside Panel Dismissal
                const dropdownsToDismiss = [
                    { panelId: 'withdrawCurrencyDropdownPanel', btnId: 'btnOpenWithdrawCurrencyDropdown', toggleFn: toggleWithdrawCurrencyDropdown },
                    { panelId: 'withdrawNetworkDropdownPanel', btnId: 'btnOpenWithdrawNetworkDropdown', toggleFn: toggleWithdrawNetworkDropdown },
                    { panelId: 'withdrawMoneyCurrencyDropdownPanel', btnId: 'btnOpenWithdrawMoneyCurrencyDropdown', toggleFn: toggleWithdrawMoneyCurrencyDropdown },
                    { panelId: 'withdrawFromDropdownPanel', btnId: 'btnOpenWithdrawFromDropdown', toggleFn: (open) => typeof toggleWithdrawFromDropdown === 'function' && toggleWithdrawFromDropdown(open) },
                    { panelId: 'withdrawMoneyFromDropdownPanel', btnId: 'btnOpenWithdrawMoneyFromDropdown', toggleFn: (open) => typeof toggleWithdrawMoneyFromDropdown === 'function' && toggleWithdrawMoneyFromDropdown(open) },
                    { panelId: 'currencyDropdownPanel', btnId: 'btnOpenCurrencyDropdown', toggleFn: (open) => typeof toggleCurrencyDropdown === 'function' && toggleCurrencyDropdown(open) },
                    { panelId: 'depositToDropdownPanel', btnId: 'btnOpenDepositToDropdown', toggleFn: (open) => typeof toggleDepositToDropdown === 'function' && toggleDepositToDropdown(open) },
                    { panelId: 'depositNetworkDropdownPanel', btnId: 'btnOpenDepositNetworkDropdown', toggleFn: (open) => typeof toggleDepositNetworkDropdown === 'function' && toggleDepositNetworkDropdown(open) },
                    { panelId: 'moneyCurrencyDropdownPanel', btnId: 'btnOpenMoneyCurrencyDropdown', toggleFn: (open) => typeof toggleMoneyCurrencyDropdown === 'function' && toggleMoneyCurrencyDropdown(open) },
                    { panelId: 'moneyDepositToDropdownPanel', btnId: 'btnOpenMoneyDepositToDropdown', toggleFn: (open) => typeof toggleMoneyDepositToDropdown === 'function' && toggleMoneyDepositToDropdown(open) }
                ];

                dropdownsToDismiss.forEach(d => {
                    const panelEl = document.getElementById(d.panelId);
                    if (panelEl && panelEl.style.display !== 'none' && !panelEl.contains(e.target) && !e.target.closest('#' + d.btnId)) {
                        d.toggleFn(false);
                    }
                });
            });

            // =========================================================================
            // WITHDRAW FROM ACCOUNT SELECTOR LOGIC
            // =========================================================================
            let stepWithdrawState = {
                selectedAccount: 'main_wallet',
                selectedAccountData: null
            };

            function renderWithdrawFromAccounts() {
                const withdrawFromAccountsList = document.getElementById('withdrawFromAccountsList');
                const withdrawMoneyFromAccountsList = document.getElementById('withdrawMoneyFromAccountsList');
                if (!withdrawFromAccountsList && !withdrawMoneyFromAccountsList) return;

                const accounts = typeof getLiveTradingAccounts === 'function' ? getLiveTradingAccounts() : [];
                const selectedUid = resolveLiveAccountId(stepWithdrawState.selectedAccount);
                const isMoneyMode = (typeof window.getSavedWithdrawMode === 'function' ? window.getSavedWithdrawMode() : null) === 'money';

                let html = '';

                if (accounts && accounts.length > 0) {
                    html += `<div style="padding: 6px 12px 2px; font-size: 0.72rem; font-weight: 700; color: rgba(255,255,255,0.4); text-transform: uppercase; letter-spacing: 0.5px;">Live Accounts (Main Wallet)</div>`;
                    accounts.forEach(acc => {
                        const accUid = getTradingAccountId(acc);
                        const isAccSelected = selectedUid === accUid;
                        const isDemo = false;
                        const mainWallet = getAccountMainWallet(accUid);
                        const bal = isMoneyMode
                            ? '₹' + mainWallet.inr.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
                            : '$' + mainWallet.usd.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                        const accName = acc.account_name || ('Account #' + (acc.login || acc.account_number || accUid));
                        const platformLabel = (acc.platform || ((acc.broker_type === 'mt5' || acc.broker === 'mt5') ? 'MT5' : 'KRYVEX')).toUpperCase();

                        html += `
                            <div class="kvx-dropdown-item ${isAccSelected ? 'is-selected' : ''}" data-withdraw-acc-id="${accUid}" style="padding: 10px 12px;">
                                <div class="kvx-dropdown-item-left" style="gap: 12px;">
                                    <div style="width: 32px; height: 32px; background: ${isDemo ? 'rgba(148, 163, 184, 0.15)' : 'rgba(16, 185, 129, 0.15)'}; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: ${isDemo ? '#94a3b8' : '#10b981'}; flex-shrink: 0;">
                                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                            <rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect>
                                            <line x1="8" y1="21" x2="16" y2="21"></line>
                                            <line x1="12" y1="17" x2="12" y2="21"></line>
                                        </svg>
                                    </div>
                                    <div class="kvx-dropdown-item-names">
                                        <span class="kvx-currency-symbol" style="font-size: 0.88rem; font-weight: 700; color: #ffffff;">${accName}</span>
                                        <span class="kvx-dropdown-item-sub" style="font-size: 0.74rem; color: rgba(255,255,255,0.45);">
                                            ${platformLabel} • Live • Main Wallet ${bal}
                                        </span>
                                    </div>
                                </div>
                                <div class="kvx-dropdown-item-right">
                                    ${isAccSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : ''}
                                </div>
                            </div>
                        `;
                    });
                }

                [withdrawFromAccountsList, withdrawMoneyFromAccountsList].forEach(list => {
                    if (list) {
                        list.innerHTML = html;
                        list.querySelectorAll('[data-withdraw-acc-id]').forEach(item => {
                            item.addEventListener('click', (e) => {
                                e.stopPropagation();
                                const accId = item.getAttribute('data-withdraw-acc-id');
                                selectWithdrawFromAccount(accId);
                                window.markWithdrawFlowSelection?.(list === withdrawMoneyFromAccountsList ? 'money' : 'crypto', 'account');
                                toggleWithdrawFromDropdown(false);
                                toggleWithdrawMoneyFromDropdown(false);
                            });
                        });
                    }
                });
            }
            window.renderWithdrawFromAccounts = renderWithdrawFromAccounts;
            window.addEventListener('kryvex_trading_accounts_loaded', () => renderWithdrawFromAccounts());
            window.addEventListener('kryvex_wallet_updated', () => renderWithdrawFromAccounts());

            function updateWithdrawAccountSummary(accId) {
                const titleEl = document.getElementById('withdrawAccountTitle');
                const subEl = document.getElementById('withdrawAccountSub');
                const moneyTitleEl = document.getElementById('withdrawMoneyAccountTitle');
                const moneySubEl = document.getElementById('withdrawMoneyAccountSub');
                const mainAvailEl = document.getElementById('withdrawMainAvailBalanceText');

                let titleText = 'Main Account';
                let subText = 'Main Wallet';
                const resolvedUid = resolveLiveAccountId(accId);
                const mainWallet = getAccountMainWallet(resolvedUid);
                const availBal = mainWallet.usd;
                const found = getLiveTradingAccounts().find(a => getTradingAccountId(a) === resolvedUid);
                stepWithdrawState.selectedAccountData = found || null;
                if (found) {
                    const platformLabel = (found.platform || ((found.broker_type === 'mt5' || found.broker === 'mt5') ? 'MT5' : 'KRYVEX')).toUpperCase();
                    titleText = found.account_name || ('Account #' + (found.login || found.account_number || resolvedUid));
                    subText = `${platformLabel} (Live) • Main Wallet: $${availBal.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / ₹${mainWallet.inr.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
                }

                if (titleEl) titleEl.textContent = titleText;
                if (subEl) subEl.textContent = subText;
                if (moneyTitleEl) moneyTitleEl.textContent = titleText;
                if (moneySubEl) moneySubEl.textContent = subText;
                if (mainAvailEl) mainAvailEl.textContent = '$' + availBal.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
            }

            function selectWithdrawFromAccount(accId) {
                stepWithdrawState.selectedAccount = accId;
                updateWithdrawAccountSummary(accId);

                toggleWithdrawFromDropdown(false);
                toggleWithdrawMoneyFromDropdown(false);
                if (typeof closeAllWalletDropdowns === 'function') closeAllWalletDropdowns();

                renderWithdrawFromAccounts();
                if (typeof window.updateWithdrawCalculation === 'function') window.updateWithdrawCalculation();
                updateWithdrawStepProgress();
                updateWithdrawMoneyStepProgress();
            }
            window.selectWithdrawFromAccount = selectWithdrawFromAccount;
            window.addEventListener('kryvex_trading_accounts_loaded', () => updateWithdrawAccountSummary(stepWithdrawState.selectedAccount));
            window.addEventListener('kryvex_wallet_updated', () => updateWithdrawAccountSummary(stepWithdrawState.selectedAccount));

            function toggleWithdrawFromDropdown(open) {
                const panel = document.getElementById('withdrawFromDropdownPanel');
                const chevron = document.getElementById('withdrawFromDropdownChevron');
                const btn = document.getElementById('btnOpenWithdrawFromDropdown');
                if (!panel) return;
                const shouldOpen = open !== undefined ? open : (panel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('withdrawFromDropdownPanel');
                }
                panel.style.display = shouldOpen ? 'block' : 'none';
                if (chevron) chevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                if (btn) btn.classList.toggle('is-open', shouldOpen);
                if (shouldOpen) renderWithdrawFromAccounts();
            }

            function toggleWithdrawMoneyFromDropdown(open) {
                const panel = document.getElementById('withdrawMoneyFromDropdownPanel');
                const chevron = document.getElementById('withdrawMoneyFromDropdownChevron');
                const btn = document.getElementById('btnOpenWithdrawMoneyFromDropdown');
                if (!panel) return;
                const shouldOpen = open !== undefined ? open : (panel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('withdrawMoneyFromDropdownPanel');
                }
                panel.style.display = shouldOpen ? 'block' : 'none';
                if (chevron) chevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                if (btn) btn.classList.toggle('is-open', shouldOpen);
                if (shouldOpen) renderWithdrawFromAccounts();
            }

            const btnOpenWithdrawFromDropdown = document.getElementById('btnOpenWithdrawFromDropdown');
            if (btnOpenWithdrawFromDropdown) {
                btnOpenWithdrawFromDropdown.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleWithdrawFromDropdown();
                });
            }

            const btnOpenWithdrawMoneyFromDropdown = document.getElementById('btnOpenWithdrawMoneyFromDropdown');
            if (btnOpenWithdrawMoneyFromDropdown) {
                btnOpenWithdrawMoneyFromDropdown.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleWithdrawMoneyFromDropdown();
                });
            }

            // Money Withdrawal Payment Method Dropdown Logic
            const WITHDRAW_MONEY_METHODS = [
                {
                    id: 'imps',
                    badge: 'IMPS',
                    name: 'IMPS',
                    sub: 'Instant Bank Transfer (IMPS / NEFT / RTGS)',
                    type: 'bank',
                    iconBg: '#2563eb',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 21h18M3 10h18M5 6l7-3 7 3M4 10v11M20 10v11M8 14v3M12 14v3M16 14v3"/></svg>`
                },
                {
                    id: 'upi',
                    badge: 'UPI',
                    name: 'UPI',
                    sub: 'Instant Transfer via UPI ID / VPA',
                    type: 'upi',
                    iconBg: '#0284c7',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>`
                },
                {
                    id: 'paytm',
                    badge: 'Paytm',
                    name: 'Paytm',
                    sub: 'Paytm Wallet / UPI Payout',
                    type: 'upi',
                    iconBg: '#0284c7',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>`
                },
                {
                    id: 'phonepe',
                    badge: 'PhonePe',
                    name: 'PhonePe',
                    sub: 'PhonePe App / Mobile Payout',
                    type: 'upi',
                    iconBg: '#7c3aed',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>`
                },
                {
                    id: 'netbanking',
                    badge: 'Netbanking',
                    name: 'India Local Bank (Netbanking)',
                    sub: 'Pay via Local Bank Netbanking',
                    type: 'bank',
                    iconBg: '#ea580c',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 21h18M3 10h18M5 6l7-3 7 3M4 10v11M20 10v11M8 14v3M12 14v3M16 14v3"/></svg>`
                },
                {
                    id: 'razorpay',
                    badge: 'Razorpay',
                    name: 'Razorpay',
                    sub: 'Razorpay Instant Payout',
                    type: 'bank',
                    iconBg: '#1e3a8a',
                    iconColor: '#38bdf8',
                    iconSvg: `<svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><path d="M13 2L3 14h7v8l10-12h-7l3-8z"/></svg>`
                },
                {
                    id: 'cards',
                    badge: 'Cards',
                    name: 'Cards',
                    sub: 'Debit / Credit Card Payout',
                    type: 'bank',
                    iconBg: '#7c3aed',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"></rect><line x1="1" y1="10" x2="23" y2="10"></line></svg>`
                }
            ];

            let selectedWithdrawMoneyMethod = 'imps';

            function renderWithdrawMoneyMethodList() {
                const listEl = document.getElementById('withdrawMoneyMethodList');
                if (!listEl) return;
                listEl.innerHTML = WITHDRAW_MONEY_METHODS.map(m => {
                    const isSelected = m.id === selectedWithdrawMoneyMethod;
                    return `
                        <div class="kvx-dropdown-item ${isSelected ? 'is-selected' : ''}" data-withdraw-method-id="${m.id}" style="padding: 10px 12px; cursor: pointer; display: flex; align-items: center; justify-content: space-between; border-radius: 8px;">
                            <div class="kvx-dropdown-item-left" style="display: flex; align-items: center; gap: 12px;">
                                <div style="width: 32px; height: 32px; background: ${m.iconBg}; color: ${m.iconColor}; border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0;">
                                    ${m.iconSvg}
                                </div>
                                <div style="display: flex; flex-direction: column;">
                                    <span style="color: #ffffff; font-weight: 700; font-size: 0.88rem;">${m.name}</span>
                                    <span style="color: rgba(255, 255, 255, 0.45); font-size: 0.74rem;">${m.sub}</span>
                                </div>
                            </div>
                            <div class="kvx-dropdown-item-right">
                                ${isSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : ''}
                            </div>
                        </div>
                    `;
                }).join('');

                listEl.querySelectorAll('[data-withdraw-method-id]').forEach(item => {
                    item.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const mid = item.getAttribute('data-withdraw-method-id');
                        selectWithdrawMoneyMethod(mid);
                    });
                });
            }

            function selectWithdrawMoneyMethod(mid) {
                const found = WITHDRAW_MONEY_METHODS.find(m => m.id === mid) || WITHDRAW_MONEY_METHODS[0];
                selectedWithdrawMoneyMethod = found.id;

                const iconWrapper = document.getElementById('withdrawMoneySelectedMethodIconWrapper');
                const title = document.getElementById('withdrawMoneySelectedMethodTitle');
                const methodPillText = document.getElementById('withdrawMoneyMethodPillText');
                const input = document.getElementById('withdrawMoneyMethodInput');

                if (iconWrapper) {
                    iconWrapper.style.background = found.iconBg;
                    iconWrapper.style.color = found.iconColor;
                    iconWrapper.innerHTML = found.iconSvg;
                }
                if (title) title.textContent = found.name;
                if (methodPillText) methodPillText.textContent = found.name;
                if (input) input.value = found.id;

                const bankFieldsGroup = document.getElementById('inrBankFieldsGroup');
                const upiFieldsGroup = document.getElementById('inrUpiFieldsGroup');

                if (found.type === 'upi') {
                    if (bankFieldsGroup) bankFieldsGroup.style.display = 'none';
                    if (upiFieldsGroup) upiFieldsGroup.style.display = 'block';
                } else {
                    if (bankFieldsGroup) bankFieldsGroup.style.display = 'block';
                    if (upiFieldsGroup) upiFieldsGroup.style.display = 'none';
                }

                renderWithdrawMoneyMethodList();
                closeAllWalletDropdowns();
            }

            function toggleWithdrawMoneyMethodDropdown(open) {
                const btnOpen = document.getElementById('btnOpenWithdrawMoneyMethodDropdown');
                const panel = document.getElementById('withdrawMoneyMethodDropdownPanel');
                const chevron = document.getElementById('withdrawMoneyMethodChevron');

                if (!panel) return;

                const shouldOpen = open !== undefined ? open : (panel.style.display === 'none' || !panel.style.display);
                if (shouldOpen) {
                    closeAllWalletDropdowns('withdrawMoneyMethodDropdownPanel');
                    renderWithdrawMoneyMethodList();
                }
                panel.style.display = shouldOpen ? 'block' : 'none';
                if (chevron) chevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                if (btnOpen) btnOpen.classList.toggle('is-open', shouldOpen);
            }

            const btnOpenWithdrawMoneyMethodDropdown = document.getElementById('btnOpenWithdrawMoneyMethodDropdown');
            if (btnOpenWithdrawMoneyMethodDropdown) {
                btnOpenWithdrawMoneyMethodDropdown.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleWithdrawMoneyMethodDropdown();
                });
            }

            const withdrawNetworkSelect = document.getElementById('withdrawNetworkSelect');
            const withdrawWalletAddress = document.getElementById('withdrawWalletAddress');
            const withdrawAmountInput = document.querySelector('#withdrawForm input[name="amount"]');
            const inrWithdrawAmountInput = document.getElementById('inrWithdrawAmount');

            var withdrawFlowSelections = {
                crypto: { currency: false, account: true },
                money: { currency: false, account: true }
            };
            window.withdrawFlowSelections = withdrawFlowSelections;

            function markWithdrawFlowSelection(mode, step) {
                if (!withdrawFlowSelections[mode]) return;
                withdrawFlowSelections[mode][step] = true;
                if (step === 'currency') {
                    const ids = mode === 'crypto'
                        ? ['selectedWithdrawCurrencyPlaceholder', 'selectedWithdrawCurrencyDisplay']
                        : ['withdrawMoneyCurrencyPlaceholder', 'withdrawMoneySelectedCurrencyDisplay'];
                    const placeholder = document.getElementById(ids[0]);
                    const display = document.getElementById(ids[1]);
                    if (placeholder) placeholder.style.display = 'none';
                    if (display) display.style.display = '';
                    if (mode === 'money') {
                        document.getElementById('withdrawMoneyCurrencyItemINR')?.classList.add('is-selected');
                        document.querySelectorAll('.withdraw-money-currency-check').forEach(el => { el.style.display = ''; });
                    }
                }
                updateWithdrawStepProgress();
                updateWithdrawMoneyStepProgress();
            }
            window.markWithdrawFlowSelection = markWithdrawFlowSelection;

            function resetWithdrawSteps() {
                ['crypto', 'money'].forEach(mode => {
                    withdrawFlowSelections[mode].currency = false;
                    withdrawFlowSelections[mode].account = true;
                });
                [['selectedWithdrawCurrencyPlaceholder', 'selectedWithdrawCurrencyDisplay'], ['withdrawMoneyCurrencyPlaceholder', 'withdrawMoneySelectedCurrencyDisplay']].forEach(([ph, disp]) => {
                    const placeholder = document.getElementById(ph);
                    const display = document.getElementById(disp);
                    if (placeholder) placeholder.style.display = '';
                    if (display) display.style.display = 'none';
                });
                document.getElementById('withdrawMoneyCurrencyItemINR')?.classList.remove('is-selected');
                document.querySelectorAll('.withdraw-money-currency-check').forEach(el => { el.style.display = 'none'; });

                ['withdrawForm', 'inrWithdrawForm'].forEach(formId => {
                    document.querySelectorAll(`#${formId} input:not([type=hidden]):not([type=radio]):not([type=checkbox]), #${formId} textarea`).forEach(input => { input.value = ''; });
                });

                if (typeof window.closeAllWalletDropdowns === 'function') window.closeAllWalletDropdowns();
                if (typeof window.selectWithdrawFromAccount === 'function') window.selectWithdrawFromAccount('main_wallet');
                if (typeof window.updateWithdrawCalculation === 'function') window.updateWithdrawCalculation();
                updateWithdrawStepProgress();
                updateWithdrawMoneyStepProgress();
            }
            window.resetWithdrawSteps = resetWithdrawSteps;

            function setWithdrawStepCircle(circle, done, active, num) {
                if (!circle) return;
                circle.classList.toggle('is-completed', done);
                circle.classList.toggle('is-active', !done && active);
                circle.classList.toggle('is-inactive', !done && !active);
                circle.innerHTML = done ? '✓' : String(num);
            }

            function showWithdrawStepContent(id, show) {
                const el = document.getElementById(id);
                if (el) el.style.display = show ? 'block' : 'none';
            }

            function isWithdrawKycVerified() {
                return typeof checkUserKycStatus === 'function' ? checkUserKycStatus().isVerified : true;
            }

            function renderWithdrawVerifyStatus(containerId, verified) {
                const container = document.getElementById(containerId);
                if (!container) return;
                const state = verified ? 'verified' : 'unverified';
                if (container.dataset.state === state) return;
                container.dataset.state = state;
                container.innerHTML = verified ? `
                    <div class="kvx-verify-step-card kvx-verify-step-verified" style="display: flex; align-items: center; justify-content: space-between; background: #191c24; border: 1px solid rgba(16, 185, 129, 0.2); border-radius: 12px; padding: 14px 16px; margin-top: 10px; flex-wrap: wrap; gap: 12px;">
                        <div style="display: flex; align-items: center; gap: 12px;">
                            <div style="width: 36px; height: 36px; border-radius: 50%; background: rgba(16, 185, 129, 0.15); display: flex; align-items: center; justify-content: center; color: #10b981; flex-shrink: 0;">
                                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                                    <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                                    <polyline points="22 4 12 14.01 9 11.01"></polyline>
                                </svg>
                            </div>
                            <div style="display: flex; flex-direction: column;">
                                <span style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">Account Verified</span>
                                <span style="font-size: 0.78rem; color: #10b981;">Your account is verified for withdrawals</span>
                            </div>
                        </div>
                        <div style="display: inline-flex; align-items: center; gap: 6px; background: rgba(16, 185, 129, 0.12); color: #10b981; font-weight: 700; font-size: 0.80rem; padding: 6px 14px; border-radius: 20px;">
                            <span>✓ Active</span>
                        </div>
                    </div>
                ` : `
                    <div class="kvx-verify-step-card kvx-verify-step-unverified" style="display: flex; align-items: center; justify-content: space-between; background: #191c24; border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 14px 16px; margin-top: 10px; flex-wrap: wrap; gap: 12px;">
                        <div style="display: flex; align-items: center; gap: 12px;">
                            <div style="width: 36px; height: 36px; border-radius: 50%; background: rgba(245, 158, 11, 0.15); display: flex; align-items: center; justify-content: center; color: #f59e0b; flex-shrink: 0;">
                                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                    <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path>
                                    <line x1="12" y1="8" x2="12" y2="12"></line>
                                    <line x1="12" y1="16" x2="12.01" y2="16"></line>
                                </svg>
                            </div>
                            <div style="display: flex; flex-direction: column;">
                                <span style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">KYC Verification Required</span>
                                <span style="font-size: 0.78rem; color: rgba(255, 255, 255, 0.45);">Complete identity verification to unlock withdrawals</span>
                            </div>
                        </div>
                        <a href="/kyc" style="display: inline-flex; align-items: center; justify-content: center; background: #2563eb; color: #ffffff; font-weight: 600; font-size: 0.82rem; padding: 8px 18px; border-radius: 8px; text-decoration: none; transition: background 0.15s ease; flex-shrink: 0;">Verify</a>
                    </div>
                `;
            }

            function applyWithdrawStepState(prefix, unlocked, step3Filled) {
                const verified = isWithdrawKycVerified();
                const step3Open = unlocked && verified;
                const step3Done = step3Open && step3Filled;

                setWithdrawStepCircle(document.getElementById(`${prefix}StepCircle3`), step3Done, step3Open, 3);
                setWithdrawStepCircle(document.getElementById(`${prefix}StepCircle4`), unlocked && verified, unlocked && !verified, 4);
                document.getElementById(`${prefix}StepLine3`)?.classList.toggle('is-active', unlocked);

                showWithdrawStepContent(`${prefix}Step3Content`, step3Open);
                showWithdrawStepContent(`${prefix}Step4Content`, unlocked);
                if (unlocked) renderWithdrawVerifyStatus(`${prefix}Step4StatusContainer`, verified);
            }

            function updateWithdrawStepProgress() {
                const netVal = withdrawNetworkSelect ? withdrawNetworkSelect.value : '';
                const addrVal = withdrawWalletAddress ? withdrawWalletAddress.value.trim() : '';
                const amtVal = withdrawAmountInput ? parseFloat(withdrawAmountInput.value) : 0;

                const sel = (withdrawFlowSelections && withdrawFlowSelections.crypto) || {};
                const step1Done = !!sel.currency;
                const step2Done = step1Done && !!sel.account;

                setWithdrawStepCircle(document.getElementById('withdrawStepCircle1'), step1Done, true, 1);
                setWithdrawStepCircle(document.getElementById('withdrawStepCircle2'), step2Done, step1Done, 2);
                document.getElementById('withdrawStepLine1')?.classList.toggle('is-active', step1Done);
                document.getElementById('withdrawStepLine2')?.classList.toggle('is-active', step2Done);

                applyWithdrawStepState('withdraw', step2Done, !!(netVal && addrVal && amtVal > 0));
            }

            function updateWithdrawMoneyStepProgress() {
                const inrAmtVal = inrWithdrawAmountInput ? parseFloat(inrWithdrawAmountInput.value) : 0;

                const sel = (withdrawFlowSelections && withdrawFlowSelections.money) || {};
                const step1Done = !!sel.currency;
                const step2Done = step1Done && !!sel.account;

                setWithdrawStepCircle(document.getElementById('withdrawMoneyStepCircle1'), step1Done, true, 1);
                setWithdrawStepCircle(document.getElementById('withdrawMoneyStepCircle2'), step2Done, step1Done, 2);
                document.getElementById('withdrawMoneyStepLine1')?.classList.toggle('is-active', step1Done);
                document.getElementById('withdrawMoneyStepLine2')?.classList.toggle('is-active', step2Done);

                applyWithdrawStepState('withdrawMoney', step2Done, inrAmtVal > 0);
            }

            ['kryvex_trading_mode_changed', 'kryvex_active_account_changed', 'kryvex_wallet_updated', 'storage'].forEach(evt => {
                window.addEventListener(evt, () => {
                    updateWithdrawStepProgress();
                    updateWithdrawMoneyStepProgress();
                });
            });

            withdrawNetworkSelect?.addEventListener('change', updateWithdrawStepProgress);
            withdrawWalletAddress?.addEventListener('input', updateWithdrawStepProgress);
            withdrawAmountInput?.addEventListener('input', updateWithdrawStepProgress);
            inrWithdrawAmountInput?.addEventListener('input', updateWithdrawMoneyStepProgress);

            // Initial progress call
            setTimeout(() => {
                updateWithdrawStepProgress();
                updateWithdrawMoneyStepProgress();
                renderWithdrawMoneyMethodList();
            }, 100);

            // Helper to prevent wheel scrolling from bubbling to body/lenis
            function isolateDropdownScroll(el) {
                if (!el) return;
                el.addEventListener('wheel', function(e) {
                    e.stopPropagation();
                    const delta = e.deltaY;
                    const up = delta < 0;
                    const atTop = el.scrollTop <= 0;
                    const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 1;

                    if ((up && atTop) || (!up && atBottom)) {
                        e.preventDefault();
                    }
                }, { passive: false });

                el.addEventListener('touchmove', function(e) {
                    e.stopPropagation();
                }, { passive: true });
            }

            // =========================================================================
            // STEP 1: SELECT CURRENCY
            // =========================================================================
            const btnOpenCurrencyDropdown = document.getElementById('btnOpenCurrencyDropdown');
            const currencyDropdownPanel = document.getElementById('currencyDropdownPanel');
            const currencySearchInput = document.getElementById('currencySearchInput');
            const currencyDropdownList = document.getElementById('currencyDropdownList');
            const currencyDropdownChevron = document.getElementById('currencyDropdownChevron');

            isolateDropdownScroll(currencyDropdownList);
            isolateDropdownScroll(currencyDropdownPanel);

            function toggleCurrencyDropdown(open) {
                const btnOpenCurrencyDropdown = document.getElementById('btnOpenCurrencyDropdown');
                const currencyDropdownPanel = document.getElementById('currencyDropdownPanel');
                const currencyDropdownChevron = document.getElementById('currencyDropdownChevron');
                const currencySearchInput = document.getElementById('currencySearchInput');

                if (!currencyDropdownPanel) return;
                const shouldOpen = open !== undefined ? open : (currencyDropdownPanel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('currencyDropdownPanel');
                }
                currencyDropdownPanel.style.display = shouldOpen ? 'block' : 'none';
                if (currencyDropdownChevron) {
                    currencyDropdownChevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                }
                if (btnOpenCurrencyDropdown) {
                    btnOpenCurrencyDropdown.classList.toggle('is-open', shouldOpen);
                }
                if (shouldOpen) {
                    if (currencySearchInput) {
                        currencySearchInput.value = '';
                    }
                    renderCurrencyDropdownList('');
                    setTimeout(() => currencySearchInput?.focus(), 60);
                }
            }

            function renderCurrencyDropdownList(filterText = '') {
                if (!currencyDropdownList) return;
                const isDemo = checkIsUserDemoMode();
                const q = filterText.toLowerCase().trim();
                const filtered = STEP_DEPOSIT_COINS.filter(c => 
                    !q || c.symbol.toLowerCase().includes(q) || c.name.toLowerCase().includes(q)
                );

                if (!filtered.length) {
                    currencyDropdownList.innerHTML = `<div style="text-align:center; padding: 16px; color: rgba(255,255,255,0.4); font-size: 0.8rem;">No currency found matching "${filterText}"</div>`;
                    return;
                }

                currencyDropdownList.innerHTML = filtered.map(coin => {
                    const isSelected = stepDepositState.selectedCoin?.symbol === coin.symbol;
                    return `
                        <div class="kvx-dropdown-item ${isSelected ? 'is-selected' : ''}" data-coin-select="${coin.symbol}">
                            <div class="kvx-dropdown-item-left">
                                <img src="${coin.icon}" alt="${coin.symbol}" class="kvx-currency-icon" onerror="this.src='https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${coin.symbol.toLowerCase()}.png';" />
                                <div class="kvx-dropdown-item-names">
                                    <span class="kvx-currency-symbol">${coin.symbol}</span>
                                    <span class="kvx-dropdown-item-sub">${coin.name}</span>
                                </div>
                            </div>
                            <div class="kvx-dropdown-item-right">
                                ${isDemo ? `
                                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="kvx-currency-lock-icon" title="Deposit not supported in Demo mode">
                                        <rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect>
                                        <path d="M7 11V7a5 5 0 0 1 10 0v4"></path>
                                    </svg>
                                ` : (isSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : '')}
                            </div>
                        </div>
                    `;
                }).join('');

                currencyDropdownList.querySelectorAll('[data-coin-select]').forEach(item => {
                    item.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const sym = item.getAttribute('data-coin-select');
                        selectStepDepositCurrency(sym);
                        toggleCurrencyDropdown(false);
                    });
                });
            }

            if (currencySearchInput) {
                currencySearchInput.addEventListener('input', (e) => {
                    renderCurrencyDropdownList(e.target.value);
                });
            }

            // =========================================================================
            // STEP 2: DEPOSIT TO (ACCOUNT SELECTOR)
            // =========================================================================
            const btnOpenDepositToDropdown = document.getElementById('btnOpenDepositToDropdown');
            const depositToDropdownPanel = document.getElementById('depositToDropdownPanel');
            const depositToAccountsList = document.getElementById('depositToAccountsList');
            const depositToDropdownChevron = document.getElementById('depositToDropdownChevron');

            isolateDropdownScroll(depositToAccountsList);
            isolateDropdownScroll(depositToDropdownPanel);

            function toggleDepositToDropdown(open) {
                const btnOpenDepositToDropdown = document.getElementById('btnOpenDepositToDropdown');
                const depositToDropdownPanel = document.getElementById('depositToDropdownPanel');
                const depositToDropdownChevron = document.getElementById('depositToDropdownChevron');

                if (!depositToDropdownPanel) return;
                const shouldOpen = open !== undefined ? open : (depositToDropdownPanel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('depositToDropdownPanel');
                }
                depositToDropdownPanel.style.display = shouldOpen ? 'block' : 'none';
                if (depositToDropdownChevron) {
                    depositToDropdownChevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                }
                if (btnOpenDepositToDropdown) {
                    btnOpenDepositToDropdown.classList.toggle('is-open', shouldOpen);
                }
                if (shouldOpen) {
                    renderDepositToAccounts();
                }
            }

            function getUserTradingAccounts() {
                if (window.__cachedTradingAccounts && Array.isArray(window.__cachedTradingAccounts)) {
                    return window.__cachedTradingAccounts;
                }
                if (window.walletDataState && Array.isArray(window.walletDataState.tradingAccounts)) {
                    return window.walletDataState.tradingAccounts;
                }
                try {
                    const cached = localStorage.getItem('kryvex_trading_accounts_cache') || localStorage.getItem('kryvex_cached_trading_accounts');
                    if (cached) {
                        const parsed = JSON.parse(cached);
                        if (Array.isArray(parsed)) return parsed;
                    }
                } catch(e) {}
                return [];
            }

            function isDemoTradingAccount(acc) {
                if (!acc) return false;
                const type = String(acc.account_type || acc.type || acc.mode || '').toLowerCase();
                return acc.is_demo === true || acc.is_demo === 1 || acc.is_demo === '1'
                    || type === 'demo'
                    || String(acc.account_name || '').toLowerCase().startsWith('demo');
            }

            function getLiveTradingAccounts() {
                return getUserTradingAccounts().filter(acc => !isDemoTradingAccount(acc));
            }
            window.getLiveTradingAccounts = getLiveTradingAccounts;

            function getTradingAccountId(acc) {
                return acc.account_uid || String(acc.id || acc.account_number || acc.login);
            }

            // 'main_wallet' is the alias for the default live account; every live account has its own main wallet.
            function resolveLiveAccountId(accId) {
                const accounts = getLiveTradingAccounts();
                if (accId && accId !== 'main_wallet' && accounts.some(a => getTradingAccountId(a) === accId)) return accId;
                const def = accounts.find(a => a.is_default) || accounts[0];
                return def ? getTradingAccountId(def) : 'main_wallet';
            }
            window.resolveLiveAccountId = resolveLiveAccountId;

            function getAccountMainWallet(accId) {
                const uid = resolveLiveAccountId(accId);
                const funds = (typeof window.getWithdrawableByAccount === 'function' ? window.getWithdrawableByAccount() : {})[uid];
                const acc = getLiveTradingAccounts().find(a => getTradingAccountId(a) === uid);
                return {
                    usd: Number(funds ? funds.main_usd : (acc?.real_main_balance || 0)),
                    inr: Number(funds ? funds.main_inr : (acc?.real_main_balance_inr || 0)),
                };
            }
            window.getAccountMainWallet = getAccountMainWallet;

            window.getSelectedWithdrawAccountUid = () => resolveLiveAccountId(stepWithdrawState.selectedAccount);
            window.getSelectedDepositAccountUid = () => resolveLiveAccountId(stepDepositState.selectedAccount);

            function renderDepositToAccounts() {
                const accounts = getLiveTradingAccounts();
                const selectedUid = resolveLiveAccountId(stepDepositState.selectedAccount);

                let html = '';

                if (accounts && accounts.length > 0) {
                    html += `<div style="padding: 6px 12px 2px; font-size: 0.72rem; font-weight: 700; color: rgba(255,255,255,0.4); text-transform: uppercase; letter-spacing: 0.5px;">Live Accounts (Main Wallet)</div>`;
                    accounts.forEach(acc => {
                        const accUid = getTradingAccountId(acc);
                        const isAccSelected = selectedUid === accUid;
                        const isDemo = false;
                        const mainWallet = getAccountMainWallet(accUid);
                        const bal = mainWallet.usd.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })
                            + ' / ₹' + mainWallet.inr.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
                        const accName = acc.account_name || ('Account #' + (acc.login || acc.account_number || accUid));
                        const platformLabel = (acc.platform || ((acc.broker_type === 'mt5' || acc.broker === 'mt5') ? 'MT5' : 'KRYVEX')).toUpperCase();

                        html += `
                            <div class="kvx-dropdown-item ${isAccSelected ? 'is-selected' : ''}" data-acc-id="${accUid}" style="padding: 10px 12px;">
                                <div class="kvx-dropdown-item-left" style="gap: 12px;">
                                    <div style="width: 32px; height: 32px; background: ${isDemo ? 'rgba(148, 163, 184, 0.15)' : 'rgba(16, 185, 129, 0.15)'}; border-radius: 8px; display: flex; align-items: center; justify-content: center; color: ${isDemo ? '#94a3b8' : '#10b981'}; flex-shrink: 0;">
                                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                            <rect x="2" y="3" width="20" height="14" rx="2" ry="2"></rect>
                                            <line x1="8" y1="21" x2="16" y2="21"></line>
                                            <line x1="12" y1="17" x2="12" y2="21"></line>
                                        </svg>
                                    </div>
                                    <div class="kvx-dropdown-item-names">
                                        <span class="kvx-currency-symbol" style="font-size: 0.88rem; font-weight: 700; color: #ffffff;">${accName}</span>
                                        <span class="kvx-dropdown-item-sub" style="font-size: 0.74rem; color: rgba(255,255,255,0.45);">
                                            ${platformLabel} • Live • Main Wallet $${bal}
                                        </span>
                                    </div>
                                </div>
                                <div class="kvx-dropdown-item-right">
                                    ${isAccSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : ''}
                                </div>
                            </div>
                        `;
                    });
                }

                if (depositToAccountsList) {
                    depositToAccountsList.innerHTML = html;
                    depositToAccountsList.querySelectorAll('[data-acc-id]').forEach(item => {
                        item.addEventListener('click', (e) => {
                            e.stopPropagation();
                            const accId = item.getAttribute('data-acc-id');
                            selectDepositToAccount(accId);
                            toggleDepositToDropdown(false);
                        });
                    });
                }

                const moneyAccountsList = document.getElementById('moneyDepositToAccountsList');
                if (moneyAccountsList) {
                    moneyAccountsList.innerHTML = html;
                    moneyAccountsList.querySelectorAll('[data-acc-id]').forEach(item => {
                        item.addEventListener('click', (e) => {
                            e.stopPropagation();
                            const accId = item.getAttribute('data-acc-id');
                            selectDepositToAccount(accId);
                            if (typeof toggleMoneyDepositToDropdown === 'function') {
                                toggleMoneyDepositToDropdown(false);
                            }
                        });
                    });
                }
            }
            window.renderDepositToAccounts = renderDepositToAccounts;
            window.addEventListener('kryvex_trading_accounts_loaded', () => renderDepositToAccounts());
            window.addEventListener('kryvex_wallet_updated', () => renderDepositToAccounts());

            function selectDepositToAccount(accId) {
                stepDepositState.selectedAccount = accId;
                const titleEl = document.getElementById('depositToAccountTitle');
                const subEl = document.getElementById('depositToAccountSub');
                const moneyTitleEl = document.getElementById('moneyDepositToAccountTitle');
                const moneySubEl = document.getElementById('moneyDepositToAccountSub');

                let titleText = 'Main Account';
                let subText = 'Funds will be credited to this account\'s Main Wallet.';

                const resolvedUid = resolveLiveAccountId(accId);
                const found = getLiveTradingAccounts().find(a => getTradingAccountId(a) === resolvedUid);
                stepDepositState.selectedAccountData = found || null;
                if (found) {
                    const mainWallet = getAccountMainWallet(resolvedUid);
                    const platformLabel = (found.platform || ((found.broker_type === 'mt5' || found.broker === 'mt5') ? 'MT5' : 'KRYVEX')).toUpperCase();
                    titleText = found.account_name || ('Account #' + (found.login || found.account_number || resolvedUid));
                    subText = `${platformLabel} (Live) • Main Wallet: $${mainWallet.usd.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })} / ₹${mainWallet.inr.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
                }
                renderDepositToAccounts();

                if (titleEl) titleEl.textContent = titleText;
                if (subEl) subEl.textContent = subText;
                if (moneyTitleEl) moneyTitleEl.textContent = titleText;
                if (moneySubEl) moneySubEl.textContent = subText;

                // If step 1 is selected in Crypto, mark step 2 as completed
                if (stepDepositState.selectedCoin) {
                    const stepCircle2 = document.getElementById('stepCircle2');
                    if (stepCircle2) {
                        stepCircle2.innerHTML = '✓';
                        stepCircle2.classList.add('is-completed');
                    }
                }
                // If step 1 is selected in Money, mark money step 2 as completed and unhide Step 3
                if (stepDepositState.selectedMoneyCurrency) {
                    const moneyStepCircle2 = document.getElementById('moneyStepCircle2');
                    const moneyStepLine2 = document.getElementById('moneyStepLine2');
                    if (moneyStepCircle2) {
                        moneyStepCircle2.innerHTML = '✓';
                        moneyStepCircle2.classList.add('is-completed');
                    }
                    if (moneyStepLine2) moneyStepLine2.classList.add('is-active');

                    const moneyStep3Content = document.getElementById('moneyStep3Content');
                    const moneyStepCircle3 = document.getElementById('moneyStepCircle3');
                    if (moneyStep3Content) moneyStep3Content.style.display = 'block';
                    if (moneyStepCircle3) {
                        moneyStepCircle3.classList.remove('is-inactive');
                        moneyStepCircle3.classList.add('is-active');
                    }
                    if (typeof updateMoneyStep3Status === 'function') {
                        updateMoneyStep3Status();
                    }
                }
            }
            window.selectDepositToAccount = selectDepositToAccount;
            window.addEventListener('kryvex_trading_accounts_loaded', () => selectDepositToAccount(stepDepositState.selectedAccount));

            // =========================================================================
            // STEP 3: SELECT NETWORK (DROPDOWN CONTROLLER)
            // =========================================================================
            const btnOpenDepositNetworkDropdown = document.getElementById('btnOpenDepositNetworkDropdown');
            const depositNetworkDropdownPanel = document.getElementById('depositNetworkDropdownPanel');
            const depositNetworkList = document.getElementById('depositNetworkList');
            const depositNetworkDropdownChevron = document.getElementById('depositNetworkDropdownChevron');

            isolateDropdownScroll(depositNetworkList);
            isolateDropdownScroll(depositNetworkDropdownPanel);

            function toggleDepositNetworkDropdown(open) {
                const btnOpenDepositNetworkDropdown = document.getElementById('btnOpenDepositNetworkDropdown');
                const depositNetworkDropdownPanel = document.getElementById('depositNetworkDropdownPanel');
                const depositNetworkDropdownChevron = document.getElementById('depositNetworkDropdownChevron');

                if (!depositNetworkDropdownPanel) return;
                const shouldOpen = open !== undefined ? open : (depositNetworkDropdownPanel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('depositNetworkDropdownPanel');
                }
                depositNetworkDropdownPanel.style.display = shouldOpen ? 'block' : 'none';
                if (depositNetworkDropdownChevron) {
                    depositNetworkDropdownChevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                }
                if (btnOpenDepositNetworkDropdown) {
                    btnOpenDepositNetworkDropdown.classList.toggle('is-open', shouldOpen);
                }
                if (shouldOpen && stepDepositState.selectedCoin) {
                    renderNetworkDropdownList(stepDepositState.selectedCoin);
                }
            }

            if (btnOpenDepositNetworkDropdown) {
                btnOpenDepositNetworkDropdown.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleDepositNetworkDropdown();
                });
            }

            // Global click handler to close all flyouts
            document.addEventListener('click', (e) => {
                if (currencyDropdownPanel && !currencyDropdownPanel.contains(e.target) && !btnOpenCurrencyDropdown?.contains(e.target)) {
                    toggleCurrencyDropdown(false);
                }
                if (depositToDropdownPanel && !depositToDropdownPanel.contains(e.target) && !btnOpenDepositToDropdown?.contains(e.target)) {
                    toggleDepositToDropdown(false);
                }
                if (depositNetworkDropdownPanel && !depositNetworkDropdownPanel.contains(e.target) && !btnOpenDepositNetworkDropdown?.contains(e.target)) {
                    toggleDepositNetworkDropdown(false);
                }
                if (moneyDepositToDropdownPanel && !moneyDepositToDropdownPanel.contains(e.target) && !btnOpenMoneyDepositToDropdown?.contains(e.target)) {
                    toggleMoneyDepositToDropdown(false);
                }
                const moneyPMPanel = document.getElementById('moneyPaymentMethodDropdownPanel');
                const btnOpenPM = document.getElementById('btnOpenMoneyPaymentMethodDropdown');
                if (moneyPMPanel && !moneyPMPanel.contains(e.target) && !btnOpenPM?.contains(e.target)) {
                    if (typeof toggleMoneyPaymentMethodDropdown === 'function') {
                        toggleMoneyPaymentMethodDropdown(false);
                    }
                }
            });

            window.kryvexDepositNetworks = [];
            let isFetchingDepositNetworks = false;

            async function ensureDepositNetworksLoaded() {
                if (window.kryvexDepositNetworks && window.kryvexDepositNetworks.length > 0) {
                    return window.kryvexDepositNetworks;
                }
                if (isFetchingDepositNetworks) return [];
                isFetchingDepositNetworks = true;

                try {
                    const token = localStorage.getItem('kryvex_access_token');
                    let user = {};
                    try { user = JSON.parse(localStorage.getItem('kryvex_user') || '{}') || {}; } catch (e) {}
                    const broker = (user.broker_type || 'kryvex').toLowerCase();

                    const res = await fetch(`/api/wallet?broker_type=${broker}`, {
                        headers: {
                            'Accept': 'application/json',
                            'X-Broker-Type': broker,
                            ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                        }
                    });

                    if (res.ok) {
                        const json = await res.json();
                        const nets = (json.data && json.data.deposit_networks) || [];
                        if (Array.isArray(nets) && nets.length > 0) {
                            window.kryvexDepositNetworks = nets;
                            if (window.walletDataState) {
                                window.walletDataState.depositNetworks = nets;
                                window.walletDataState.deposit_networks = nets;
                            }
                            try {
                                localStorage.setItem('kryvex_deposit_networks_cache', JSON.stringify(nets));
                            } catch(e) {}

                            // Re-render current selected network address
                            if (stepDepositState.selectedNetwork) {
                                selectStepDepositNetwork(stepDepositState.selectedNetwork);
                            }
                            return nets;
                        }
                    }
                } catch (e) {
                    console.error('ensureDepositNetworksLoaded error:', e);
                } finally {
                    isFetchingDepositNetworks = false;
                }
                return [];
            }

            // Trigger immediate background load
            ensureDepositNetworksLoaded();

            window.addEventListener('kryvex_wallet_config_updated', (e) => {
                if (e.detail && e.detail.deposit_networks) {
                    window.kryvexDepositNetworks = e.detail.deposit_networks;
                }
                if (stepDepositState.selectedCoin && stepDepositState.selectedNetwork) {
                    selectStepDepositNetwork(stepDepositState.selectedNetwork);
                }
            });

            function getDepositConfigFor(coinSymbol, networkCode) {
                const sym = String(coinSymbol || 'USDT').toUpperCase();
                const net = String(networkCode || 'TRC20').toUpperCase();
                let depositNets = (window.kryvexDepositNetworks && window.kryvexDepositNetworks.length)
                    ? window.kryvexDepositNetworks
                    : ((window.walletDataState && (window.walletDataState.depositNetworks || window.walletDataState.deposit_networks)) || []);

                // If memory state is not populated yet, check localStorage cache
                if (!depositNets.length) {
                    try {
                        const cached = JSON.parse(localStorage.getItem('kryvex_deposit_networks_cache') || '[]');
                        if (Array.isArray(cached) && cached.length) {
                            depositNets = cached;
                            window.kryvexDepositNetworks = cached;
                        }
                    } catch(e) {}
                }

                // If still empty, trigger fetch
                if (!depositNets.length) {
                    ensureDepositNetworksLoaded();
                }

                const candidateKeys = [];
                if (net === 'TRC20') {
                    candidateKeys.push('TRC20', 'USDT', 'USD_TRC20');
                } else if (net === 'ERC20') {
                    candidateKeys.push('ERC20', 'USD_ERC20', 'ETH');
                } else if (net === 'BEP20') {
                    candidateKeys.push('BEP20', 'USD_BEP20', 'BNB');
                } else if (net === 'SOL') {
                    candidateKeys.push('SOL');
                } else if (net === 'BTC') {
                    candidateKeys.push('BTC');
                } else {
                    candidateKeys.push(net, `USD_${net}`, sym);
                }

                // 1. Search in user deposit networks
                for (const k of candidateKeys) {
                    const found = depositNets.find(n => (n.network || '').toUpperCase() === k);
                    if (found && found.address && found.address.trim()) {
                        return {
                            address: found.address.trim(),
                            minDeposit: found.minimum_deposit !== undefined ? found.minimum_deposit : 0.1
                        };
                    }
                }

                return {
                    address: 'Loading Custodial Address...',
                    minDeposit: 0.1
                };
            }

            function getDepositAddressFor(coinSymbol, networkCode) {
                return getDepositConfigFor(coinSymbol, networkCode).address;
            }

            // =========================================================================
            // STEP SELECTION CONTROLLERS (STEPS 1 TO 5)
            // =========================================================================
            function renderNetworkDropdownList(coin) {
                const listEl = document.getElementById('depositNetworkList');
                if (!listEl || !coin) return;

                const networks = coin.networks || ['TRC20'];
                listEl.innerHTML = networks.map(net => {
                    const isSelected = net === stepDepositState.selectedNetwork;
                    const netIcon = NETWORK_ICONS[net] || coin.icon;
                    const meta = NETWORK_META[net] || { title: net, desc: `${coin.symbol} (${net})` };
                    return `
                        <div class="kvx-dropdown-item ${isSelected ? 'is-selected' : ''}" data-net-select="${net}" style="padding: 10px 12px; cursor: pointer;">
                            <div class="kvx-dropdown-item-left" style="gap: 12px; display: flex; align-items: center;">
                                <div style="width: 30px; height: 30px; background: rgba(255, 255, 255, 0.08); border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; overflow: hidden;">
                                    <img src="${netIcon}" alt="${net}" style="width: 20px; height: 20px; object-fit: contain;" onerror="this.src='${coin.icon}'" />
                                </div>
                                <div class="kvx-dropdown-item-names" style="display: flex; flex-direction: column;">
                                    <span class="kvx-currency-symbol" style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">${meta.title}</span>
                                    <span class="kvx-dropdown-item-sub" style="font-size: 0.76rem; color: rgba(255,255,255,0.45);">${meta.desc}</span>
                                </div>
                            </div>
                            <div class="kvx-dropdown-item-right">
                                ${isSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : ''}
                            </div>
                        </div>
                    `;
                }).join('');

                listEl.querySelectorAll('[data-net-select]').forEach(item => {
                    item.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const net = item.getAttribute('data-net-select');
                        selectStepDepositNetwork(net);
                        toggleDepositNetworkDropdown(false);
                    });
                });
            }

            function selectStepDepositCurrency(coinSymbol) {
                const sym = String(coinSymbol || 'USDT').toUpperCase();
                const coin = STEP_DEPOSIT_COINS.find(c => c.symbol === sym) || STEP_DEPOSIT_COINS[0];
                stepDepositState.selectedCoin = coin;

                // 1. Update Step 1 Display with floating label & selected icon/symbol
                const displayEl = document.getElementById('selectedCurrencyDisplay');
                const floatingLabel = document.getElementById('currencyFloatingLabel');
                if (floatingLabel) floatingLabel.style.display = 'block';

                if (displayEl) {
                    displayEl.innerHTML = `
                        <img src="${coin.icon}" alt="${coin.symbol}" class="kvx-currency-icon" onerror="this.src='https://raw.githubusercontent.com/spothq/cryptocurrency-icons/master/128/color/${coin.symbol.toLowerCase()}.png';" />
                        <span class="kvx-currency-symbol">${coin.symbol}</span>
                        <span class="kvx-currency-name" style="margin-left: 6px; color: rgba(255,255,255,0.45); font-size: 0.85rem;">${coin.name}</span>
                    `;
                }

                // Step 1 completed
                const stepCircle1 = document.getElementById('stepCircle1');
                const stepLine1 = document.getElementById('stepLine1');
                if (stepCircle1) {
                    stepCircle1.innerHTML = '✓';
                    stepCircle1.classList.add('is-completed');
                }
                if (stepLine1) stepLine1.classList.add('is-active');

                // 2. Open Step 2 (Deposit To)
                const step2Content = document.getElementById('step2DepositContent');
                const stepCircle2 = document.getElementById('stepCircle2');
                const stepLine2 = document.getElementById('stepLine2');
                if (step2Content) step2Content.style.display = 'block';
                if (stepCircle2) {
                    stepCircle2.innerHTML = '✓';
                    stepCircle2.classList.remove('is-inactive');
                    stepCircle2.classList.add('is-completed');
                }
                if (stepLine2) stepLine2.classList.add('is-active');

                // 3. Open Step 3 (Select Network)
                const step3Content = document.getElementById('step3DepositContent');
                const stepCircle3 = document.getElementById('stepCircle3');
                const stepLine3 = document.getElementById('stepLine3');
                if (step3Content) step3Content.style.display = 'block';
                if (stepCircle3) {
                    stepCircle3.classList.remove('is-inactive');
                    stepCircle3.classList.add('is-active');
                }
                if (stepLine3) stepLine3.classList.add('is-active');

                // Render Network Dropdown List
                renderNetworkDropdownList(coin);

                // Auto-select default network
                const defaultNet = coin.defaultNetwork || (coin.networks && coin.networks[0]) || 'TRC20';
                selectStepDepositNetwork(defaultNet);

                // 5. Open Step 5 (Verify Account) & Update Status
                const step5Content = document.getElementById('step5DepositContent');
                if (step5Content) step5Content.style.display = 'block';
                updateStep5VerificationStatus();
            }
            window.selectStepDepositCurrency = selectStepDepositCurrency;

            function selectStepDepositNetwork(networkCode) {
                stepDepositState.selectedNetwork = networkCode;
                const coin = stepDepositState.selectedCoin || STEP_DEPOSIT_COINS[0];
                const conf = getDepositConfigFor(coin.symbol, networkCode);
                const address = conf.address;

                // Update Network Dropdown Button Display
                const titleEl = document.getElementById('depositNetworkTitle');
                const subEl = document.getElementById('depositNetworkSub');
                const iconEl = document.getElementById('selectedDepositNetworkIcon');
                const meta = NETWORK_META[networkCode] || { title: networkCode, desc: `${coin.symbol} (${networkCode})` };
                const netIcon = NETWORK_ICONS[networkCode] || coin.icon;

                if (titleEl) titleEl.textContent = meta.title;
                if (subEl) subEl.textContent = meta.desc;
                if (iconEl) {
                    iconEl.src = netIcon;
                    iconEl.onerror = () => { iconEl.src = coin.icon; };
                }

                // Step 3 completed checkmark
                const stepCircle3 = document.getElementById('stepCircle3');
                const stepLine3 = document.getElementById('stepLine3');
                if (stepCircle3) {
                    stepCircle3.innerHTML = '✓';
                    stepCircle3.classList.remove('is-inactive');
                    stepCircle3.classList.add('is-completed');
                }
                if (stepLine3) stepLine3.classList.add('is-active');

                // Re-render network dropdown list to update checkmark
                renderNetworkDropdownList(coin);

                // 4. Open Step 4 (Deposit Address & QR) if KYC is verified
                const step4Content = document.getElementById('step4DepositContent');
                const stepCircle4 = document.getElementById('stepCircle4');
                const stepLine4 = document.getElementById('stepLine4');
                const kyc = checkUserKycStatus();

                if (!kyc.isVerified) {
                    if (step4Content) step4Content.style.display = 'none';
                    if (stepCircle4) {
                        stepCircle4.innerHTML = '4';
                        stepCircle4.classList.add('is-inactive');
                        stepCircle4.classList.remove('is-active', 'is-completed');
                    }
                    if (stepLine4) stepLine4.classList.remove('is-active');
                } else {
                    if (step4Content) step4Content.style.display = 'block';
                    if (stepCircle4) {
                        stepCircle4.classList.remove('is-inactive');
                        stepCircle4.classList.add('is-active');
                    }
                    if (stepLine4) stepLine4.classList.add('is-active');
                }

                // Update Address & QR details
                const labelEl = document.getElementById('stepDepositAddressLabel');
                const textEl = document.getElementById('stepDepositAddressText');
                const qrEl = document.getElementById('stepDepositQrImage');
                const qrLogoImg = document.getElementById('stepDepositQrLogoImg');
                const minEl = document.getElementById('depositNoticeMinAmt');
                const coinHighEl = document.getElementById('stepDepositCoinHighlight');
                const netHighEl = document.getElementById('stepDepositNetHighlight');

                if (labelEl) labelEl.textContent = `${coin.symbol} Deposit Address (${networkCode})`;
                if (textEl) textEl.textContent = address;
                if (minEl) minEl.textContent = '0.1 ' + coin.symbol;
                if (coinHighEl) coinHighEl.textContent = coin.symbol;
                if (netHighEl) netHighEl.textContent = networkCode;

                const scanNote = document.getElementById('cryptoDepositScanNote');
                if (scanNote) {
                    scanNote.textContent = `The system will scan the ${networkCode} blockchain for this TXID and credit the exact transfer amount automatically.`;
                }
                const txInput = document.getElementById('cryptoDepositTxHashInput');
                if (txInput) {
                    txInput.placeholder = (networkCode === 'SOL') ? 'Paste your 88-character Solana TXID signature here' : ((networkCode === 'TRC20') ? 'Paste your 64-character TRON TXID hash here' : 'Paste your 66-character (0x...) TXID hash here');
                }

                if (qrEl && address && !address.includes('Select')) {
                    qrEl.src = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&margin=1&ecc=M&data=${encodeURIComponent(address)}`;
                }

                // 5. Open Step 5 indicator
                const stepCircle5 = document.getElementById('stepCircle5');
                if (stepCircle5) {
                    stepCircle5.classList.remove('is-inactive');
                    stepCircle5.classList.add('is-active');
                }
                updateStep5VerificationStatus();
            }
            window.selectStepDepositNetwork = selectStepDepositNetwork;

            function resetStepDepositView() {
                stepDepositState.selectedCoin = null;
                stepDepositState.selectedNetwork = null;

                // Reset Step 1
                const floatingLabel = document.getElementById('currencyFloatingLabel');
                if (floatingLabel) floatingLabel.style.display = 'none';

                const displayEl = document.getElementById('selectedCurrencyDisplay');
                if (displayEl) {
                    displayEl.innerHTML = `
                        <svg class="w-4 h-4 text-gray-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="18" height="18"><circle cx="11" cy="11" r="8"></circle><path d="m21 21-4.35-4.35"></path></svg>
                        <span class="kvx-dropdown-placeholder" id="selectedCurrencyLabel" style="color: rgba(255,255,255,0.45); font-size: 0.92rem;">Currency</span>
                    `;
                }

                const stepCircle1 = document.getElementById('stepCircle1');
                const stepLine1 = document.getElementById('stepLine1');
                if (stepCircle1) {
                    stepCircle1.innerHTML = '1';
                    stepCircle1.classList.remove('is-completed', 'is-active');
                }
                if (stepLine1) stepLine1.classList.remove('is-active');

                // Reset Step 2
                const step2Content = document.getElementById('step2DepositContent');
                const stepCircle2 = document.getElementById('stepCircle2');
                const stepLine2 = document.getElementById('stepLine2');
                if (step2Content) step2Content.style.display = 'none';
                if (stepCircle2) {
                    stepCircle2.innerHTML = '2';
                    stepCircle2.classList.add('is-inactive');
                    stepCircle2.classList.remove('is-active', 'is-completed');
                }
                if (stepLine2) stepLine2.classList.remove('is-active');

                // Reset Step 3
                const step3Content = document.getElementById('step3DepositContent');
                const stepCircle3 = document.getElementById('stepCircle3');
                const stepLine3 = document.getElementById('stepLine3');
                if (step3Content) step3Content.style.display = 'none';
                if (stepCircle3) {
                    stepCircle3.innerHTML = '3';
                    stepCircle3.classList.add('is-inactive');
                    stepCircle3.classList.remove('is-active', 'is-completed');
                }
                if (stepLine3) stepLine3.classList.remove('is-active');
                toggleDepositNetworkDropdown(false);

                // Reset Step 4
                const step4Content = document.getElementById('step4DepositContent');
                const stepCircle4 = document.getElementById('stepCircle4');
                const stepLine4 = document.getElementById('stepLine4');
                if (step4Content) step4Content.style.display = 'none';
                if (stepCircle4) {
                    stepCircle4.innerHTML = '4';
                    stepCircle4.classList.add('is-inactive');
                    stepCircle4.classList.remove('is-active', 'is-completed');
                }
                if (stepLine4) stepLine4.classList.remove('is-active');

                // Reset Step 5
                const step5Content = document.getElementById('step5DepositContent');
                const stepCircle5 = document.getElementById('stepCircle5');
                if (step5Content) step5Content.style.display = 'none';
                if (stepCircle5) {
                    stepCircle5.innerHTML = '5';
                    stepCircle5.classList.add('is-inactive');
                    stepCircle5.classList.remove('is-active', 'is-completed');
                }
            }
            window.resetStepDepositView = resetStepDepositView;

            // =========================================================================
            // STEP 5: VERIFY ACCOUNT STATUS
            // =========================================================================
            function updateStep5VerificationStatus() {
                const container = document.getElementById('step5StatusContainer');
                if (!container) return;

                const isDemo = checkIsUserDemoMode();
                const kyc = checkUserKycStatus();

                // Keep Step 4 visibility in sync with KYC status when coin and network are selected
                if (stepDepositState.selectedCoin && stepDepositState.selectedNetwork) {
                    const step4Content = document.getElementById('step4DepositContent');
                    const stepCircle4 = document.getElementById('stepCircle4');
                    const stepLine4 = document.getElementById('stepLine4');
                    if (!kyc.isVerified) {
                        if (step4Content) step4Content.style.display = 'none';
                        if (stepCircle4) {
                            stepCircle4.innerHTML = '4';
                            stepCircle4.classList.add('is-inactive');
                            stepCircle4.classList.remove('is-active', 'is-completed');
                        }
                        if (stepLine4) stepLine4.classList.remove('is-active');
                    } else {
                        if (step4Content) step4Content.style.display = 'block';
                        if (stepCircle4) {
                            stepCircle4.classList.remove('is-inactive');
                            stepCircle4.classList.add('is-active');
                        }
                        if (stepLine4) stepLine4.classList.add('is-active');
                    }
                }

                if (!kyc.isVerified) {
                    // KYC is NOT verified
                    container.innerHTML = `
                        <div class="kvx-verify-step-card kvx-verify-step-unverified" style="display: flex; align-items: center; justify-content: space-between; background: #191c24; border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 14px 16px; margin-top: 10px; flex-wrap: wrap; gap: 12px;">
                            <div style="display: flex; align-items: center; gap: 12px;">
                                <div style="width: 36px; height: 36px; border-radius: 50%; background: rgba(245, 158, 11, 0.15); display: flex; align-items: center; justify-content: center; color: #f59e0b; flex-shrink: 0;">
                                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                        <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path>
                                        <line x1="12" y1="8" x2="12" y2="12"></line>
                                        <line x1="12" y1="16" x2="12.01" y2="16"></line>
                                    </svg>
                                </div>
                                <div style="display: flex; flex-direction: column;">
                                    <span style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">KYC Verification Required</span>
                                    <span style="font-size: 0.78rem; color: rgba(255, 255, 255, 0.45);">Complete identity verification to unlock higher deposit limits & fast processing</span>
                                </div>
                            </div>
                            <a href="/kyc" style="display: inline-flex; align-items: center; justify-content: center; background: #2563eb; color: #ffffff; font-weight: 600; font-size: 0.82rem; padding: 8px 18px; border-radius: 8px; text-decoration: none; transition: background 0.15s ease; flex-shrink: 0;">Verify</a>
                        </div>
                    `;
                } else if (isDemo) {
                    // KYC IS verified, BUT current mode is DEMO
                    container.innerHTML = `
                        <div class="kvx-verify-step-card kvx-verify-step-demo" style="display: flex; align-items: center; justify-content: space-between; background: #191c24; border: 1px solid rgba(56, 189, 248, 0.2); border-radius: 12px; padding: 14px 16px; margin-top: 10px; flex-wrap: wrap; gap: 12px;">
                            <div style="display: flex; align-items: center; gap: 12px;">
                                <div style="width: 36px; height: 36px; border-radius: 50%; background: rgba(56, 189, 248, 0.15); display: flex; align-items: center; justify-content: center; color: #38bdf8; flex-shrink: 0;">
                                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                                        <circle cx="12" cy="12" r="10"></circle>
                                        <line x1="12" y1="16" x2="12" y2="12"></line>
                                        <line x1="12" y1="8" x2="12.01" y2="8"></line>
                                    </svg>
                                </div>
                                <div style="display: flex; flex-direction: column;">
                                    <span style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">Demo Account Active</span>
                                    <span style="font-size: 0.78rem; color: rgba(255, 255, 255, 0.45);">Deposits apply to Live trading accounts only.</span>
                                </div>
                            </div>
                            <button type="button" id="btnStepDepositSwitchLive" style="display: inline-flex; align-items: center; justify-content: center; background: #2563eb; color: #ffffff; font-weight: 600; font-size: 0.82rem; padding: 8px 18px; border-radius: 8px; border: none; cursor: pointer; transition: background 0.15s ease; flex-shrink: 0;">Switch to Live</button>
                        </div>
                    `;

                    const switchBtn = document.getElementById('btnStepDepositSwitchLive');
                    if (switchBtn) {
                        switchBtn.addEventListener('click', () => {
                            switchToLiveAccount();
                        });
                    }
                } else {
                    // KYC verified AND account is Live!
                    container.innerHTML = `
                        <div class="kvx-verify-step-card kvx-verify-step-verified" style="display: flex; align-items: center; justify-content: space-between; background: #191c24; border: 1px solid rgba(16, 185, 129, 0.2); border-radius: 12px; padding: 14px 16px; margin-top: 10px; flex-wrap: wrap; gap: 12px;">
                            <div style="display: flex; align-items: center; gap: 12px;">
                                <div style="width: 36px; height: 36px; border-radius: 50%; background: rgba(16, 185, 129, 0.15); display: flex; align-items: center; justify-content: center; color: #10b981; flex-shrink: 0;">
                                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                                        <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                                        <polyline points="22 4 12 14.01 9 11.01"></polyline>
                                    </svg>
                                </div>
                                <div style="display: flex; flex-direction: column;">
                                    <span style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">Account Verified</span>
                                    <span style="font-size: 0.78rem; color: #10b981;">Ready for instant crypto &amp; fiat deposits</span>
                                </div>
                            </div>
                            <div style="display: inline-flex; align-items: center; gap: 6px; background: rgba(16, 185, 129, 0.12); color: #10b981; font-weight: 700; font-size: 0.80rem; padding: 6px 14px; border-radius: 20px;">
                                <span>✓ Active</span>
                            </div>
                        </div>
                    `;
                }
            }
            window.updateStep5VerificationStatus = updateStep5VerificationStatus;
            window.updateStep3VerificationStatus = updateStep5VerificationStatus; // backwards compat

            function switchToLiveAccount() {
                let accounts = [];
                try {
                    accounts = JSON.parse(localStorage.getItem('kryvex_trading_accounts_cache') || '[]') || [];
                } catch(e) {}
                const liveAcc = accounts.find(a => !a.is_demo && a.account_type !== 'demo' && !String(a.account_name || '').toLowerCase().startsWith('demo')) 
                    || accounts.find(a => !a.is_demo && a.account_type !== 'demo');

                if (liveAcc) {
                    localStorage.setItem('kryvex_active_account_uid', liveAcc.account_uid);
                    window.dispatchEvent(new CustomEvent('kryvex_active_account_changed', { detail: { account: liveAcc } }));
                }
                localStorage.setItem('kryvex_trading_mode', 'live');
                window.dispatchEvent(new CustomEvent('kryvex_trading_mode_changed', { detail: { mode: 'live' } }));

                renderCurrencyDropdownList('');
                renderMoneyCurrencyDropdownList('');
                renderDepositToAccounts();
                updateStep5VerificationStatus();
                updateMoneyStep3Status();

                if (typeof showWalletToast === 'function') {
                    showWalletToast('Switched to Live Trading Account. Deposits are now active.', 'success');
                }
            }
            window.switchToLiveAccount = switchToLiveAccount;

            // Copy deposit address buttons handler
            function copyDepositAddress() {
                const textEl = document.getElementById('stepDepositAddressText');
                if (textEl && textEl.textContent && !textEl.textContent.includes('Select')) {
                    navigator.clipboard.writeText(textEl.textContent.trim()).then(() => {
                        const btnStepCopyText = document.getElementById('btnStepCopyText');
                        if (btnStepCopyText) btnStepCopyText.textContent = 'Copied!';
                        if (typeof showWalletToast === 'function') {
                            showWalletToast('Deposit address copied to clipboard!', 'success');
                        }
                        setTimeout(() => {
                            if (btnStepCopyText) btnStepCopyText.textContent = 'Copy';
                        }, 2000);
                    }).catch(() => {
                        if (typeof showWalletToast === 'function') {
                            showWalletToast('Failed to copy address.', 'error');
                        }
                    });
                }
            }

            const btnStepCopyAddress = document.getElementById('btnStepCopyAddress');
            if (btnStepCopyAddress) {
                btnStepCopyAddress.addEventListener('click', copyDepositAddress);
            }
            const btnInlineCopyAddress = document.getElementById('btnInlineCopyAddress');
            if (btnInlineCopyAddress) {
                btnInlineCopyAddress.addEventListener('click', copyDepositAddress);
            }
            const btnTriggerCameraScanStep4 = document.getElementById('btnTriggerCameraScanStep4');
            if (btnTriggerCameraScanStep4) {
                btnTriggerCameraScanStep4.addEventListener('click', () => {
                    copyDepositAddress();
                });
            }

            // Crypto "Confirm I Have Sent" form submission
            const formCryptoDepositNotify = document.getElementById('formCryptoDepositNotify');
            const btnCryptoHaveSent = document.getElementById('btnCryptoHaveSent');
            const btnCryptoHaveSentText = document.getElementById('btnCryptoHaveSentText');

            if (formCryptoDepositNotify) {
                formCryptoDepositNotify.addEventListener('submit', async (e) => {
                    e.preventDefault();
                    const coin = stepDepositState.selectedCoin || STEP_DEPOSIT_COINS[0];
                    const network = stepDepositState.selectedNetwork || coin.defaultNetwork;
                    const txHashInput = document.getElementById('cryptoDepositTxHashInput');
                    const txHashVal = txHashInput?.value ? txHashInput.value.trim() : '';
                    const feedbackEl = document.getElementById('cryptoDepositFeedback');

                    const setFeedback = (msg, type = 'info') => {
                        if (!feedbackEl) return;
                        feedbackEl.style.display = 'block';
                        if (type === 'success') {
                            feedbackEl.style.background = 'rgba(16, 185, 129, 0.15)';
                            feedbackEl.style.border = '1px solid rgba(16, 185, 129, 0.35)';
                            feedbackEl.style.color = '#34d399';
                        } else if (type === 'error') {
                            feedbackEl.style.background = 'rgba(239, 68, 68, 0.15)';
                            feedbackEl.style.border = '1px solid rgba(239, 68, 68, 0.35)';
                            feedbackEl.style.color = '#f87171';
                        } else {
                            feedbackEl.style.background = 'rgba(59, 130, 246, 0.15)';
                            feedbackEl.style.border = '1px solid rgba(59, 130, 246, 0.35)';
                            feedbackEl.style.color = '#60a5fa';
                        }
                        feedbackEl.innerHTML = msg;
                    };

                    if (!txHashVal) {
                        window.showWalletToast('Please enter your Transaction Hash (TXID) from your transfer.', 'error');
                        setFeedback('⚠️ Please enter the Transaction Hash (TXID) from your transfer.', 'error');
                        if (txHashInput) txHashInput.focus();
                        return;
                    }

                    // Smart detection: Did the user accidentally paste a 42-char wallet address instead of a 66-char TXID?
                    if (/^0x[a-fA-F0-9]{40}$/i.test(txHashVal)) {
                        const addrNotice = '⚠️ <strong>You entered a Wallet Address (42 characters) instead of a Transaction Hash / TXID.</strong><br><br>In Trust Wallet / MetaMask, please tap on your transfer transaction and copy the <strong>"Transaction Hash" / "Hash"</strong> (66 characters starting with <code>0x...</code>).';
                        window.showWalletToast('You entered a Wallet Address instead of a Transaction Hash. Please copy the TXID from Trust Wallet.', 'error', 7000);
                        setFeedback(addrNotice, 'error');
                        if (txHashInput) txHashInput.focus();
                        return;
                    }

                    if (btnCryptoHaveSent) btnCryptoHaveSent.disabled = true;
                    if (btnCryptoHaveSentText) btnCryptoHaveSentText.textContent = 'Verifying on Blockchain...';
                    setFeedback(`<div style="display:flex; align-items:center; gap:8px;"><svg style="animation:spin 1s linear infinite; width:16px; height:16px;" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10" stroke-opacity="0.25"/><path d="M12 2a10 10 0 0 1 10 10" stroke-linecap="round"/></svg> <span>Scanning <strong>${network}</strong> blockchain for TXID <code>${txHashVal.substring(0, 14)}...</code></span></div>`, 'info');

                    try {
                        const token = localStorage.getItem('kryvex_access_token');
                        const res = await fetch('/api/wallet/crypto-deposit', {
                            method: 'POST',
                            headers: {
                                'Content-Type': 'application/json',
                                'Accept': 'application/json',
                                ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                            },
                            body: JSON.stringify({
                                asset: coin.symbol,
                                network: network,
                                tx_hash: txHashVal,
                                account_uid: resolveLiveAccountId(stepDepositState.selectedAccount)
                            })
                        });

                        const data = await res.json();
                        if (res.ok && data.success) {
                            const successMsg = `🎉 <strong>Deposit Verified!</strong> ${data.message || 'Balance credited successfully!'}`;
                            window.showWalletToast(data.message || 'Deposit verified successfully!', 'success', 6000);
                            setFeedback(successMsg, 'success');
                            if (txHashInput) txHashInput.value = '';

                            // Refresh wallets, trading accounts, and history ledgers
                            if (typeof window.loadWallet === 'function') window.loadWallet();
                            if (typeof window.loadTradingAccounts === 'function') window.loadTradingAccounts();
                            if (typeof window.loadWalletConfig === 'function') window.loadWalletConfig();
                            if (typeof window.loadNavbarTradingAccounts === 'function') window.loadNavbarTradingAccounts(true);
                            if (typeof window.fetchLedgerTransactions === 'function') window.fetchLedgerTransactions();
                            window.dispatchEvent(new CustomEvent('kryvex_wallet_updated'));
                        } else {
                            const errMsg = data.message || `Verification failed on ${network} blockchain. Please verify your TXID.`;
                            window.showWalletToast(errMsg, 'error', 6000);
                            setFeedback(`❌ <strong>Verification Error:</strong> ${errMsg}`, 'error');
                        }
                    } catch (err) {
                        console.error('Crypto deposit notification failed:', err);
                        const netErr = 'An error occurred while connecting to the blockchain. Please try again.';
                        window.showWalletToast(netErr, 'error');
                        setFeedback(`❌ ${netErr}`, 'error');
                    } finally {
                        if (btnCryptoHaveSent) btnCryptoHaveSent.disabled = false;
                        if (btnCryptoHaveSentText) btnCryptoHaveSentText.textContent = 'Verify & Credit Deposit';
                    }
                });
            }

            // Live event listeners to update UI instantly when mode or account changes
            window.addEventListener('kryvex_trading_mode_changed', () => {
                renderCurrencyDropdownList(currencySearchInput ? currencySearchInput.value : '');
                renderMoneyCurrencyDropdownList(moneyCurrencySearchInput ? moneyCurrencySearchInput.value : '');
                updateStep3VerificationStatus();
                updateMoneyStep3Status();
            });
            window.addEventListener('kryvex_active_account_changed', () => {
                renderCurrencyDropdownList(currencySearchInput ? currencySearchInput.value : '');
                renderMoneyCurrencyDropdownList(moneyCurrencySearchInput ? moneyCurrencySearchInput.value : '');
                updateStep3VerificationStatus();
                updateMoneyStep3Status();
            });

            // Initial render: Setup dropdown & start in initial collapsed state as in Image 2
            renderCurrencyDropdownList('');
            resetStepDepositView();

            // =========================================================================
            // MONEY (INR) PROGRESSIVE STEP CONTROLLER
            // =========================================================================
            const STEP_MONEY_CURRENCIES = [
                { symbol: 'INR', name: 'Indian Rupee', method: 'UPI / IMPS / NetBanking', flag: '🇮🇳' }
            ];

            const btnOpenMoneyCurrencyDropdown = document.getElementById('btnOpenMoneyCurrencyDropdown');
            const moneyCurrencyDropdownPanel = document.getElementById('moneyCurrencyDropdownPanel');
            const moneyCurrencySearchInput = document.getElementById('moneyCurrencySearchInput');
            const moneyCurrencyDropdownList = document.getElementById('moneyCurrencyDropdownList');
            const moneyCurrencyDropdownChevron = document.getElementById('moneyCurrencyDropdownChevron');
            isolateDropdownScroll(moneyCurrencyDropdownList);
            isolateDropdownScroll(moneyCurrencyDropdownPanel);

            function toggleMoneyCurrencyDropdown(open) {
                if (!moneyCurrencyDropdownPanel) return;
                const shouldOpen = open !== undefined ? open : (moneyCurrencyDropdownPanel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('moneyCurrencyDropdownPanel');
                }
                moneyCurrencyDropdownPanel.style.display = shouldOpen ? 'block' : 'none';
                if (moneyCurrencyDropdownChevron) {
                    moneyCurrencyDropdownChevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                }
                if (btnOpenMoneyCurrencyDropdown) {
                    btnOpenMoneyCurrencyDropdown.classList.toggle('is-open', shouldOpen);
                }
                if (shouldOpen) {
                    if (moneyCurrencySearchInput) {
                        moneyCurrencySearchInput.value = '';
                    }
                    renderMoneyCurrencyDropdownList('');
                    setTimeout(() => moneyCurrencySearchInput?.focus(), 60);
                }
            }

            if (btnOpenMoneyCurrencyDropdown) {
                btnOpenMoneyCurrencyDropdown.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleMoneyCurrencyDropdown();
                });
            }

            // Money Step 2 Deposit To Dropdown
            const btnOpenMoneyDepositToDropdown = document.getElementById('btnOpenMoneyDepositToDropdown');
            const moneyDepositToDropdownPanel = document.getElementById('moneyDepositToDropdownPanel');
            const moneyDepositToAccountsList = document.getElementById('moneyDepositToAccountsList');
            const moneyDepositToDropdownChevron = document.getElementById('moneyDepositToDropdownChevron');
            isolateDropdownScroll(moneyDepositToAccountsList);
            isolateDropdownScroll(moneyDepositToDropdownPanel);

            function toggleMoneyDepositToDropdown(open) {
                if (!moneyDepositToDropdownPanel) return;
                const shouldOpen = open !== undefined ? open : (moneyDepositToDropdownPanel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('moneyDepositToDropdownPanel');
                }
                moneyDepositToDropdownPanel.style.display = shouldOpen ? 'block' : 'none';
                if (moneyDepositToDropdownChevron) {
                    moneyDepositToDropdownChevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                }
                if (btnOpenMoneyDepositToDropdown) {
                    btnOpenMoneyDepositToDropdown.classList.toggle('is-open', shouldOpen);
                }
                if (shouldOpen) {
                    renderDepositToAccounts();
                }
            }

            if (btnOpenMoneyDepositToDropdown) {
                btnOpenMoneyDepositToDropdown.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleMoneyDepositToDropdown();
                });
            }

            document.addEventListener('click', (e) => {
                if (moneyCurrencyDropdownPanel && !moneyCurrencyDropdownPanel.contains(e.target) && !btnOpenMoneyCurrencyDropdown?.contains(e.target)) {
                    toggleMoneyCurrencyDropdown(false);
                }
                if (moneyDepositToDropdownPanel && !moneyDepositToDropdownPanel.contains(e.target) && !btnOpenMoneyDepositToDropdown?.contains(e.target)) {
                    toggleMoneyDepositToDropdown(false);
                }
                const moneyPMPanel = document.getElementById('moneyPaymentMethodDropdownPanel');
                const btnOpenPM = document.getElementById('btnOpenMoneyPaymentMethodDropdown');
                if (moneyPMPanel && !moneyPMPanel.contains(e.target) && !btnOpenPM?.contains(e.target)) {
                    if (typeof toggleMoneyPaymentMethodDropdown === 'function') {
                        toggleMoneyPaymentMethodDropdown(false);
                    }
                }
            });

            function renderMoneyCurrencyDropdownList(filterText = '') {
                if (!moneyCurrencyDropdownList) return;
                const isDemo = checkIsUserDemoMode();
                const q = filterText.toLowerCase().trim();
                const filtered = STEP_MONEY_CURRENCIES.filter(c => 
                    !q || c.symbol.toLowerCase().includes(q) || c.name.toLowerCase().includes(q)
                );

                if (!filtered.length) {
                    moneyCurrencyDropdownList.innerHTML = `<div style="text-align:center; padding: 16px; color: rgba(255,255,255,0.4); font-size: 0.8rem;">No fiat currency found matching "${filterText}"</div>`;
                    return;
                }

                moneyCurrencyDropdownList.innerHTML = filtered.map(c => {
                    const isSelected = stepDepositState.selectedMoneyCurrency === c.symbol;
                    return `
                        <div class="kvx-currency-item ${isSelected ? 'is-selected' : ''}" data-money-coin-select="${c.symbol}">
                            <div class="kvx-currency-item-left">
                                <span style="font-size: 1.5rem; line-height: 1; display:flex; align-items:center;">${c.flag}</span>
                                <div class="kvx-currency-item-names">
                                    <span class="kvx-currency-symbol">${c.symbol}</span>
                                    <span class="kvx-currency-fullname">${c.name} (${c.method})</span>
                                </div>
                            </div>
                            <div class="kvx-currency-item-right">
                                ${isDemo ? `
                                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="kvx-currency-lock-icon" title="Deposit not supported in Demo mode">
                                        <rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect>
                                        <path d="M7 11V7a5 5 0 0 1 10 0v4"></path>
                                    </svg>
                                ` : (isSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1rem;">✓</span>` : '')}
                            </div>
                        </div>
                    `;
                }).join('');

                moneyCurrencyDropdownList.querySelectorAll('[data-money-coin-select]').forEach(item => {
                    item.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const sym = item.getAttribute('data-money-coin-select');
                        selectStepMoneyCurrency(sym);
                        toggleMoneyCurrencyDropdown(false);
                    });
                });
            }

            if (moneyCurrencySearchInput) {
                moneyCurrencySearchInput.addEventListener('input', (e) => {
                    renderMoneyCurrencyDropdownList(e.target.value);
                });
            }

            function selectStepMoneyCurrency(curSymbol) {
                const sym = String(curSymbol || 'INR').toUpperCase();
                stepDepositState.selectedMoneyCurrency = sym;

                // 1. Update Step 1 Display with floating label
                const displayEl = document.getElementById('moneySelectedCurrencyDisplay');
                const floatingLabel = document.getElementById('moneyCurrencyFloatingLabel');
                if (floatingLabel) floatingLabel.style.display = 'block';

                if (displayEl) {
                    displayEl.innerHTML = `
                        <span style="font-size: 1.35rem; line-height: 1;">🇮🇳</span>
                        <span class="kvx-currency-symbol" style="margin-left: 6px;">INR</span>
                        <span class="kvx-currency-name" style="margin-left: 6px; color: rgba(255,255,255,0.45); font-size: 0.85rem;">Indian Rupee (UPI / IMPS)</span>
                    `;
                }

                // Step 1 completed styling
                const stepCircle1 = document.getElementById('moneyStepCircle1');
                const stepLine1 = document.getElementById('moneyStepLine1');
                if (stepCircle1) {
                    stepCircle1.innerHTML = '✓';
                    stepCircle1.classList.add('is-completed');
                }
                if (stepLine1) stepLine1.classList.add('is-active');

                // 2. Open Step 2 (Deposit To)
                const step2Content = document.getElementById('moneyStep2Content');
                const stepCircle2 = document.getElementById('moneyStepCircle2');
                const stepLine2 = document.getElementById('moneyStepLine2');
                if (step2Content) step2Content.style.display = 'block';
                if (stepCircle2) {
                    stepCircle2.classList.remove('is-inactive');
                    stepCircle2.classList.add('is-active');
                }
                if (stepLine2) stepLine2.classList.add('is-active');
                renderDepositToAccounts();

                // Select Deposit To Account and automatically unhide Step 3
                selectDepositToAccount(stepDepositState.selectedAccount || 'main_wallet');
            }
            window.selectStepMoneyCurrency = selectStepMoneyCurrency;

            // Money Payment Method State & Data
            const MONEY_PAYMENT_METHODS = [
                {
                    id: 'razorpay',
                    name: 'Razorpay',
                    sub: 'UPI · Cards · Netbanking',
                    iconBg: '#1e3a8a',
                    iconColor: '#38bdf8',
                    iconSvg: `<svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><path d="M13 2L3 14h7v8l10-12h-7l3-8z"/></svg>`,
                    detail: 'Instant automatic deposit via Razorpay gateway. Supports UPI, Cards, and Netbanking with immediate account crediting.'
                },
                {
                    id: 'paytm',
                    name: 'Paytm',
                    sub: 'Pay via Razorpay UPI',
                    iconBg: '#0284c7',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>`,
                    detail: 'Pay via Paytm app or Paytm UPI ID. You will be redirected to complete payment securely.'
                },
                {
                    id: 'phonepe',
                    name: 'PhonePe',
                    sub: 'Real UPI · pay in PhonePe app',
                    iconBg: '#7c3aed',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>`,
                    detail: 'Open your PhonePe mobile app to approve the payment request for instant deposit processing.'
                },
                {
                    id: 'netbanking',
                    name: 'India Local Bank (Netbanking)',
                    sub: 'Pay via Razorpay netbanking',
                    iconBg: '#ea580c',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 21h18M3 10h18M5 6l7-3 7 3M4 10v11M20 10v11M8 14v3M12 14v3M16 14v3"/></svg>`,
                    detail: 'Transfer directly from top Indian banks including HDFC, ICICI, SBI, Axis, Kotak, and 50+ local banks.'
                },
                {
                    id: 'upi',
                    name: 'UPI',
                    sub: 'Any UPI app via Razorpay',
                    iconBg: '#0284c7',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><path d="M12 18h.01"/></svg>`,
                    detail: 'Pay using any UPI app (Google Pay, PhonePe, Paytm, BHIM, CRED) by entering your VPA or scanning QR.'
                },
                {
                    id: 'cards',
                    name: 'Cards',
                    sub: 'Debit / Credit via Razorpay',
                    iconBg: '#7c3aed',
                    iconColor: '#ffffff',
                    iconSvg: `<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"></rect><line x1="1" y1="10" x2="23" y2="10"></line></svg>`,
                    detail: 'Pay using domestic or international Debit or Credit cards (Visa, MasterCard, RuPay, Maestro).'
                }
            ];

            let selectedMoneyPaymentMethod = 'razorpay';

            function toggleMoneyPaymentMethodDropdown(open) {
                const panel = document.getElementById('moneyPaymentMethodDropdownPanel');
                const chevron = document.getElementById('moneyPaymentMethodDropdownChevron');
                const btn = document.getElementById('btnOpenMoneyPaymentMethodDropdown');
                if (!panel) return;

                const shouldOpen = open !== undefined ? open : (panel.style.display === 'none');
                if (shouldOpen) {
                    closeAllWalletDropdowns('moneyPaymentMethodDropdownPanel');
                }

                panel.style.display = shouldOpen ? 'block' : 'none';
                if (chevron) chevron.style.transform = shouldOpen ? 'rotate(180deg)' : 'rotate(0deg)';
                if (btn) btn.classList.toggle('is-open', shouldOpen);
                if (shouldOpen) renderMoneyPaymentMethodList();
            }

            function renderMoneyPaymentMethodList() {
                const listEl = document.getElementById('moneyPaymentMethodList');
                if (!listEl) return;

                listEl.innerHTML = MONEY_PAYMENT_METHODS.map(m => {
                    const isSelected = selectedMoneyPaymentMethod === m.id;
                    return `
                        <div class="kvx-dropdown-item ${isSelected ? 'is-selected' : ''}" data-method-id="${m.id}" style="padding: 10px 14px; cursor: pointer;">
                            <div class="kvx-dropdown-item-left" style="gap: 12px; align-items: center;">
                                <div style="width: 34px; height: 34px; background: ${m.iconBg}; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: ${m.iconColor}; flex-shrink: 0;">
                                    ${m.iconSvg}
                                </div>
                                <div class="kvx-dropdown-item-names" style="display: flex; flex-direction: column; text-align: left; line-height: 1.25;">
                                    <span class="kvx-currency-symbol" style="font-size: 0.90rem; font-weight: 700; color: #ffffff;">${m.name}</span>
                                    <span class="kvx-dropdown-item-sub" style="font-size: 0.76rem; color: rgba(255,255,255,0.45);">${m.sub}</span>
                                </div>
                            </div>
                            <div class="kvx-dropdown-item-right">
                                ${isSelected ? `<span style="color:#10b981; font-weight:bold; font-size:1.1rem;">✓</span>` : ''}
                            </div>
                        </div>
                    `;
                }).join('');

                listEl.querySelectorAll('[data-method-id]').forEach(item => {
                    item.addEventListener('click', (e) => {
                        e.stopPropagation();
                        const mid = item.getAttribute('data-method-id');
                        selectMoneyPaymentMethod(mid);
                        toggleMoneyPaymentMethodDropdown(false);
                    });
                });
            }

            function updateMoneyPayButtonText() {
                const amountInput = document.getElementById('stepMoneyDepositAmount');
                const payBtnText = document.getElementById('moneyPayBtnText');
                const receiveAmtDisplay = document.getElementById('moneyReceiveAmtDisplay');
                
                const amount = Number(amountInput?.value || 0);
                const currCode = stepDepositState.selectedMoneyCurrency || 'INR';
                const currSymbol = currCode === 'USD' ? '$' : (currCode === 'EUR' ? '€' : '₹');

                const found = MONEY_PAYMENT_METHODS.find(m => m.id === selectedMoneyPaymentMethod) || MONEY_PAYMENT_METHODS[0];
                const methodName = found ? found.name : 'Razorpay';

                if (receiveAmtDisplay) {
                    receiveAmtDisplay.textContent = `${currSymbol}${amount.toFixed(2)} ${currCode}`;
                }

                if (payBtnText) {
                    if (amount > 0) {
                        payBtnText.textContent = `Pay ${currSymbol}${amount.toLocaleString()} with ${methodName}`;
                    } else {
                        payBtnText.textContent = `Pay with ${methodName}`;
                    }
                }
            }

            function selectMoneyPaymentMethod(mid) {
                selectedMoneyPaymentMethod = mid;
                const found = MONEY_PAYMENT_METHODS.find(m => m.id === mid) || MONEY_PAYMENT_METHODS[0];
                const titleEl = document.getElementById('moneyPaymentMethodTitle');
                const subEl = document.getElementById('moneyPaymentMethodSub');
                const iconBadge = document.getElementById('moneyPaymentMethodIconBadge');
                const detailTextEl = document.getElementById('moneyPaymentMethodDetailText');
                const infoCardTitle = document.getElementById('moneyInfoCardTitle');
                const infoCardSub = document.getElementById('moneyInfoCardSub');
                const subStep3HeaderTitle = document.getElementById('moneySubStep3HeaderTitle');

                if (titleEl) titleEl.textContent = found.name;
                if (subEl) subEl.textContent = found.sub;
                if (iconBadge) {
                    iconBadge.style.background = found.iconBg;
                    iconBadge.style.color = found.iconColor;
                    iconBadge.innerHTML = found.iconSvg;
                }
                if (detailTextEl) {
                    detailTextEl.textContent = found.detail;
                }
                if (infoCardTitle) {
                    infoCardTitle.textContent = `Pay with Razorpay · ${found.name}`;
                }
                if (infoCardSub) {
                    infoCardSub.textContent = `${found.name} deposit (Razorpay Wallet)`;
                }
                if (subStep3HeaderTitle) {
                    subStep3HeaderTitle.textContent = `Pay via Razorpay · ${found.name}`;
                }

                updateMoneyPayButtonText();
            }

            function resetStepMoneyView() {
                stepDepositState.selectedMoneyCurrency = null;

                const step3Title = document.getElementById('moneyStep3Title');
                if (step3Title) step3Title.textContent = 'Verify account';

                // Reset Step 1 to Initial Placeholder
                const floatingLabel = document.getElementById('moneyCurrencyFloatingLabel');
                if (floatingLabel) floatingLabel.style.display = 'none';

                const displayEl = document.getElementById('moneySelectedCurrencyDisplay');
                if (displayEl) {
                    displayEl.innerHTML = `
                        <svg class="w-4 h-4 text-gray-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" width="18" height="18"><circle cx="11" cy="11" r="8"></circle><path d="m21 21-4.35-4.35"></path></svg>
                        <span class="kvx-currency-placeholder" id="moneySelectedCurrencyLabel" style="color: rgba(255,255,255,0.45); font-size: 0.92rem;">Currency</span>
                    `;
                }

                const stepCircle1 = document.getElementById('moneyStepCircle1');
                const stepLine1 = document.getElementById('moneyStepLine1');
                if (stepCircle1) {
                    stepCircle1.innerHTML = '1';
                    stepCircle1.classList.remove('is-completed');
                }
                if (stepLine1) stepLine1.classList.remove('is-active');

                // Collapse Step 2
                const step2Content = document.getElementById('moneyStep2Content');
                const stepCircle2 = document.getElementById('moneyStepCircle2');
                const stepLine2 = document.getElementById('moneyStepLine2');
                if (step2Content) step2Content.style.display = 'none';
                if (stepCircle2) {
                    stepCircle2.classList.add('is-inactive');
                    stepCircle2.classList.remove('is-active');
                    stepCircle2.classList.remove('is-completed');
                    stepCircle2.innerHTML = '2';
                }
                if (stepLine2) stepLine2.classList.remove('is-active');

                if (typeof toggleMoneyDepositToDropdown === 'function') {
                    toggleMoneyDepositToDropdown(false);
                }

                // Collapse Step 3
                const step3Content = document.getElementById('moneyStep3Content');
                const stepCircle3 = document.getElementById('moneyStepCircle3');
                if (step3Content) step3Content.style.display = 'none';
                if (stepCircle3) {
                    stepCircle3.classList.add('is-inactive');
                    stepCircle3.classList.remove('is-active');
                    stepCircle3.classList.remove('is-completed');
                    stepCircle3.innerHTML = '3';
                }
            }
            window.resetStepMoneyView = resetStepMoneyView;

