                            const btnOpenPM = document.getElementById('btnOpenMoneyPaymentMethodDropdown');
                            if (btnOpenPM) {
                                btnOpenPM.addEventListener('click', (e) => {
                                    e.stopPropagation();
                                    toggleMoneyPaymentMethodDropdown();
                                });
                            }
                            renderMoneyPaymentMethodList();

                            // Bind amount input listener & quick amount pills listener
                            const amountInput = document.getElementById('stepMoneyDepositAmount');
                            const subStep3Wrap = document.getElementById('moneySubStep3Wrap');
                            const circle2 = document.getElementById('moneySubStepCircle2');
                            const badge2 = document.getElementById('moneySubStepBadge2');

                            if (amountInput) {
                                amountInput.addEventListener('input', () => {
                                    const val = Number(amountInput.value || 0);
                                    if (val > 0) {
                                        if (circle2) {
                                            circle2.style.background = '#10b981';
                                            circle2.style.color = '#ffffff';
                                            circle2.innerHTML = '✓';
                                        }
                                        if (badge2) {
                                            badge2.style.display = 'inline';
                                        }
                                        if (subStep3Wrap) {
                                            subStep3Wrap.style.display = 'flex';
                                        }
                                    } else {
                                        if (circle2) {
                                            circle2.style.background = 'rgba(255, 255, 255, 0.15)';
                                            circle2.style.color = 'rgba(255, 255, 255, 0.6)';
                                            circle2.innerHTML = '2';
                                        }
                                        if (badge2) {
                                            badge2.style.display = 'none';
                                        }
                                        if (subStep3Wrap) {
                                            subStep3Wrap.style.display = 'none';
                                        }
                                    }
                                    updateMoneyPayButtonText();
                                });
                            }

                            container.querySelectorAll('.money-quick-amt-btn').forEach(pill => {
                                pill.addEventListener('click', () => {
                                    const amt = pill.getAttribute('data-amt');
                                    if (amountInput) {
                                        amountInput.value = amt;
                                        amountInput.dispatchEvent(new Event('input'));
                                    }
                                });
                            });

                            const payNowBtn = document.getElementById('btnStepMoneyPayNow');
                            if (payNowBtn) {
                                payNowBtn.addEventListener('click', async (e) => {
                                    e.preventDefault();

                                    const isDemo = checkIsUserDemoMode();
                                    const kyc = checkUserKycStatus();

                                    if (!kyc.isVerified) {
                                        showWalletToast('KYC verification is required before INR deposits can be processed.', 'error');
                                        return;
                                    }
                                    if (isDemo) {
                                        showWalletToast('Deposits are not allowed for Demo accounts. Please switch to a Live account.', 'error');
                                        return;
                                    }

                                    const amountInr = Number(document.getElementById('stepMoneyDepositAmount')?.value || 0);
                                    if (!amountInr || amountInr <= 0) {
                                        showWalletToast('Please enter a valid deposit amount.', 'error');
                                        return;
                                    }

                                    payNowBtn.disabled = true;
                                    const origText = document.getElementById('moneyPayBtnText')?.textContent || 'Pay with Razorpay';
                                    if (document.getElementById('moneyPayBtnText')) {
                                        document.getElementById('moneyPayBtnText').textContent = 'Initiating Razorpay...';
                                    }

                                    let user = {};
                                    try {
                                        user = JSON.parse(localStorage.getItem('kryvex_user') || '{}') || {};
                                    } catch (err) {}

                                    try {
                                        const token = localStorage.getItem('kryvex_access_token');
                                        const orderRes = await fetch('/api/wallet/razorpay/create-order', {
                                            method: 'POST',
                                            headers: {
                                                'Content-Type': 'application/json',
                                                'Accept': 'application/json',
                                                ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                                            },
                                            body: JSON.stringify({ amount_inr: amountInr, account_uid: window.getSelectedDepositAccountUid?.() }),
                                        }).then(r => r.json());

                                        if (!orderRes || !orderRes.success) {
                                            throw new Error(orderRes?.message || 'Failed to initialize Razorpay payment order.');
                                        }

                                        const RazorpayCtor = await (async function loadRazorpaySdk() {
                                            return new Promise((resolve, reject) => {
                                                if (window.Razorpay) { resolve(window.Razorpay); return; }
                                                const existing = document.querySelector('script[src*="razorpay"]');
                                                if (existing) {
                                                    existing.addEventListener('load', () => resolve(window.Razorpay));
                                                    existing.addEventListener('error', () => reject(new Error('Razorpay SDK failed to load.')));
                                                    return;
                                                }
                                                const script = document.createElement('script');
                                                script.src = 'https://checkout.razorpay.com/v1/checkout.js';
                                                script.async = true;
                                                script.onload = () => resolve(window.Razorpay);
                                                script.onerror = () => reject(new Error('Failed to load Razorpay SDK.'));
                                                document.head.appendChild(script);
                                            });
                                        })();

                                        const options = {
                                            key: orderRes.key_id,
                                            amount: orderRes.amount_paise,
                                            currency: orderRes.currency || 'INR',
                                            name: 'Kryvex Exchange',
                                            description: `INR Wallet Deposit ₹${amountInr}`,
                                            order_id: orderRes.order_id,
                                            prefill: {
                                                name: orderRes.user?.name || user.name || '',
                                                email: orderRes.user?.email || user.email || '',
                                                contact: orderRes.user?.mobile || user.mobile || '',
                                            },
                                            theme: {
                                                color: '#7c3aed',
                                            },
                                            handler: async function (response) {
                                                if (document.getElementById('moneyPayBtnText')) {
                                                    document.getElementById('moneyPayBtnText').textContent = 'Verifying Payment...';
                                                }
                                                try {
                                                    const verifyRes = await fetch('/api/wallet/razorpay/verify', {
                                                        method: 'POST',
                                                        headers: {
                                                            'Content-Type': 'application/json',
                                                            'Accept': 'application/json',
                                                            ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                                                        },
                                                        body: JSON.stringify({
                                                            razorpay_order_id: response.razorpay_order_id || orderRes.order_id,
                                                            razorpay_payment_id: response.razorpay_payment_id || '',
                                                            razorpay_signature: response.razorpay_signature || '',
                                                            amount_inr: amountInr,
                                                        }),
                                                    }).then(r => r.json());

                                                    if (!verifyRes || !verifyRes.success) {
                                                        throw new Error(verifyRes?.message || 'Payment verification failed. If money was debited, contact support with your Razorpay payment ID.');
                                                    }
                                                    showWalletToast(verifyRes.message || 'Razorpay Payment Verified & Wallet Credited! 🎉', 'success');
                                                    const amtEl = document.getElementById('stepMoneyDepositAmount');
                                                    if (amtEl) { amtEl.value = ''; amtEl.dispatchEvent(new Event('input')); }
                                                    if (window.loadWalletConfig) await window.loadWalletConfig();
                                                    if (window.loadLedgerHistory) await window.loadLedgerHistory(1);
                                                    if (window.reloadFuturesBalances) await window.reloadFuturesBalances();
                                                } catch (err) {
                                                    showWalletToast(err.message || 'Payment verification failed.', 'error');
                                                } finally {
                                                    payNowBtn.disabled = false;
                                                    if (document.getElementById('moneyPayBtnText')) {
                                                        document.getElementById('moneyPayBtnText').textContent = origText;
                                                    }
                                                }
                                            },
                                            modal: {
                                                ondismiss: function () {
                                                    payNowBtn.disabled = false;
                                                    if (document.getElementById('moneyPayBtnText')) {
                                                        document.getElementById('moneyPayBtnText').textContent = origText;
                                                    }
                                                    showWalletToast('Razorpay payment cancelled.', 'warning');
                                                }
                                            }
                                        };

                                        const rzp = new RazorpayCtor(options);
                                        rzp.open();

                                    } catch (error) {
                                        showWalletToast(error.message || 'Unable to initiate Razorpay payment.', 'error');
                                        payNowBtn.disabled = false;
                                        if (document.getElementById('moneyPayBtnText')) {
                                            document.getElementById('moneyPayBtnText').textContent = origText;
                                        }
                                    }
                                });
                            }
                        });
                    }
                }
            }

            function bindStepInrFormSubmit() {
                const form = document.getElementById('stepInrDepositForm');
                if (!form) return;
                form.addEventListener('submit', async (e) => {
                    e.preventDefault();
                    const isDemo = checkIsUserDemoMode();
                    const kyc = checkUserKycStatus();

                    if (!kyc.isVerified) {
                        showWalletToast('KYC verification is required before INR deposits can be submitted.', 'error');
                        return;
                    }
                    if (isDemo) {
                        showWalletToast('Deposits are not allowed for Demo accounts. Please switch to a Live account.', 'error');
                        return;
                    }

                    const amount = Number(document.getElementById('stepInrDepositAmount')?.value || 0);
                    const utr = (document.getElementById('stepInrDepositUtr')?.value || '').trim();
                    const slipFile = document.getElementById('stepInrDepositSlip')?.files[0];
                    const submitBtn = document.getElementById('btnStepInrDepositSubmit');

                    if (!amount || amount <= 0) {
                        showWalletToast('Please enter a valid deposit amount.', 'error');
                        return;
                    }
                    if (!utr) {
                        showWalletToast('Please provide the transaction UTR number.', 'error');
                        return;
                    }

                    if (submitBtn) {
                        submitBtn.disabled = true;
                        submitBtn.textContent = 'Submitting request...';
                    }

                    try {
                        const token = localStorage.getItem('kryvex_access_token');
                        const formData = new FormData();
                        formData.append('amount_inr', amount);
                        formData.append('utr_number', utr);
                        if (slipFile) {
                            formData.append('payment_slip', slipFile);
                        }

                        const res = await fetch('/api/wallet/inr-deposit-request', {
                            method: 'POST',
                            headers: {
                                'Accept': 'application/json',
                                ...(token ? { 'Authorization': `Bearer ${token}` } : {})
                            },
                            body: formData
                        });
                        const data = await res.json();
                        if (data && data.success) {
                            showWalletToast('INR deposit request submitted successfully. It will be credited once verified.', 'success');
                            form.reset();
                        } else {
                            showWalletToast(data?.message || 'Failed to submit deposit request.', 'error');
                        }
                    } catch (err) {
                        showWalletToast(err.message || 'Error submitting deposit request.', 'error');
                    } finally {
                        if (submitBtn) {
                            submitBtn.disabled = false;
                            submitBtn.textContent = 'Submit Deposit Request';
                        }
                    }
                });
            }





            // Real-time Live Deposit Poller (Detects TronLink / Blockchain transfers automatically)
            let depositPollInterval = null;
            function startDepositStatusPoller() {
                if (depositPollInterval) clearInterval(depositPollInterval);

                let depositPollLoading = false;
                depositPollInterval = setInterval(async () => {
                    if (document.hidden || depositPollLoading) return;
                    const isDemo = checkIsUserDemoMode();
                    if (isDemo) return;

                    const token = localStorage.getItem('kryvex_access_token') || localStorage.getItem('access_token');
                    if (!token) return;

                    depositPollLoading = true;
                    try {
                        const res = await fetch('/api/wallet/deposit-status', {
                            headers: {
                                'Accept': 'application/json',
                                'Authorization': `Bearer ${token}`
                            }
                        });
                        const data = await res.json();
                        if (data && data.success && data.new_deposits_count > 0) {
                            const dep = data.new_deposits[0];
                            showWalletToast(`🎉 Received on-chain deposit of ${dep.amount} ${dep.currency}! Balance updated!`, 'success');
                            if (typeof window.loadWallet === 'function') window.loadWallet();
                            if (typeof window.loadWalletConfig === 'function') window.loadWalletConfig();
                            if (typeof window.loadTradingAccounts === 'function') window.loadTradingAccounts();
                            if (typeof window.loadNavbarTradingAccounts === 'function') window.loadNavbarTradingAccounts(true);
                            window.dispatchEvent(new CustomEvent('kryvex_wallet_updated'));
                        }
                    } catch (err) {
                        // Silent fail for background polling
                    } finally {
                        depositPollLoading = false;
                    }
                }, 10000);
            }

            startDepositStatusPoller();

            // FAQ Accordion Handlers
            document.querySelectorAll('[data-faq-target]').forEach(btn => {
                btn.addEventListener('click', () => {
                    const targetId = btn.getAttribute('data-faq-target');
                    const ansEl = document.getElementById(targetId);
                    const parent = btn.closest('.kvx-faq-item');
                    if (ansEl) {
                        const isOpen = ansEl.style.display !== 'none';
                        ansEl.style.display = isOpen ? 'none' : 'block';
                        if (parent) {
                            parent.classList.toggle('is-open', !isOpen);
                        }
                    }
                });
            });

            // Money (INR) Bank details renderer (Deprecated - replaced by Deposit to dropdown)
            function renderStepInrBankDetails() {}
            window.renderStepInrBankDetails = renderStepInrBankDetails;

            // Must run after every const in initWalletPage is initialized; routing touches withdraw/deposit controls declared above.
            handleUrlRouting();
            if (typeof window.updateNavDepositButtonVisibility === 'function') {
                window.updateNavDepositButtonVisibility();
            }

            // Initial URL Routing Check
            const isWithdrawPath = window.location.pathname.endsWith('/withdraw');
            const isExchangePath = window.location.pathname.endsWith('/wallet/exchange') || window.location.pathname.endsWith('/exchange');
            const isHistoryPath = window.location.pathname.endsWith('/wallet/history') || window.location.pathname.endsWith('/history');
            const urlParams = new URLSearchParams(window.location.search);
            const tabParam = (urlParams.get('tab') || '').toLowerCase();
            const subtabParam = (urlParams.get('subtab') || '').toLowerCase();

            if (isExchangePath || tabParam === 'exchange' || subtabParam === 'exchange') {
                switchMainTab('exchange');
                const assetParam = urlParams.get('asset') || urlParams.get('coin');
                if (assetParam && assetParam.toUpperCase() !== 'USDT' && assetParam.toUpperCase() !== 'USD' && typeof window.setSwapFromAsset === 'function') {
                    window.setSwapFromAsset(assetParam);
                } else if (typeof window.resetSwapToDirectMode === 'function') {
                    window.resetSwapToDirectMode();
                }
            } else if (isWithdrawPath || subtabParam === 'withdraw' || tabParam === 'withdraw') {
                switchMainTab('wallet-ops');
                switchWalletInnerNav('withdraw');
                let savedWithdrawMode = '';
                try { savedWithdrawMode = sessionStorage.getItem('kryvex_active_withdraw_mode') || ''; } catch(e) {}
                const withdrawModeParam = (urlParams.get('withdraw_mode') || urlParams.get('mode') || savedWithdrawMode || '').toLowerCase();
                const currencyParam = (urlParams.get('currency') || urlParams.get('coin') || urlParams.get('asset') || '').toUpperCase();
                if (withdrawModeParam === 'money' || withdrawModeParam === 'inr' || withdrawModeParam === 'fiat' || currencyParam === 'INR') {
                    if (typeof window.setStepWithdrawMode === 'function') {
                        window.setStepWithdrawMode('money');
                    }
                } else {
                    if (typeof window.setStepWithdrawMode === 'function') {
                        window.setStepWithdrawMode('crypto');
                    }
                }
            } else if (tabParam === 'deposit' || subtabParam === 'deposit' || window.location.pathname.endsWith('/deposit')) {
                switchMainTab('wallet-ops');
                const currencyParam = (urlParams.get('currency') || urlParams.get('coin') || urlParams.get('asset') || '').toUpperCase();
                const explicitMode = window.normalizeDepositMode(urlParams.get('mode') || urlParams.get('method') || urlParams.get('type'));
                const modeParam = explicitMode || (currencyParam === 'INR' ? 'money' : '') || window.getSavedDepositMode() || 'crypto';
                switchWalletInnerNav('deposit');
                if (modeParam === 'money') {
                    if (typeof window.setStepDepositMode === 'function') {
                        window.setStepDepositMode('money', false);
                    }
                } else {
                    if (typeof window.setStepDepositMode === 'function') {
                        window.setStepDepositMode('crypto', false);
                    }
                    if (currencyParam) {
                        if (typeof window.selectStepDepositCurrency === 'function') {
                            window.selectStepDepositCurrency(currencyParam);
                        }
                    } else {
                        if (typeof window.resetStepDepositView === 'function') {
                            window.resetStepDepositView();
                        }
                    }
                }
            } else if (isHistoryPath || subtabParam === 'history' || subtabParam === 'ledger' || tabParam === 'history' || tabParam === 'ledger') {
                switchMainTab('wallet-ops');
                switchWalletInnerNav('history');
                setTimeout(() => {
                    const panel = document.getElementById('innerPanelHistory') || document.getElementById('viewSectionWalletOps');
                    if (panel) panel.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }, 120);
            } else if (tabParam === 'trading') {
                switchMainTab('trading');
            } else if (tabParam === 'overview') {
                switchMainTab('overview');
            } else {
                switchMainTab('wallet');
            }
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initWalletPage);
        } else {
            initWalletPage();
        }
    </script>
@endpush

