                                (function () {
                                    try {
                                        var params = new URLSearchParams(window.location.search);
                                        if (params.get('mode') || params.get('currency')) return;
                                        var saved = sessionStorage.getItem('kryvex_active_deposit_mode') || localStorage.getItem('kryvex_active_deposit_mode');
                                        if (saved !== 'money' && saved !== 'crypto') return;
                                        var isMoney = saved === 'money';
                                        document.getElementById('btnDepositToggleCrypto').classList.toggle('is-active', !isMoney);
                                        document.getElementById('btnDepositToggleMoney').classList.toggle('is-active', isMoney);
                                        document.getElementById('depositMainTitle').textContent = isMoney ? 'Deposit money' : 'Deposit crypto';
                                        document.getElementById('cryptoStepsContainer').style.display = isMoney ? 'none' : 'block';
